/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200512-9","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"文教委員会","time":"午前１０時１０分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３２号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３２号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ですので、所得制限を設けるべきではないと思うのですが、そこの部分の区のお考えを伺いたいと思います。品川区としても、こうしたひとり親世帯への支援が必要になるのではないかと思うのですけれども、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"区はこの国の方針に従って実施しています。ひとり親世帯につきましては、練馬区の状況は委員ご指摘のとおりだと思いますけれども、品川区といたしましては、ひとり親世帯に関しては、現在のところは支給支援する予定はございません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"児童手当のほうは国がやっていることというのは分かっていますけれども、やはり区としても支援していくということも含め、あと、国にも対象を広げていくようにということで求めていくことが必要だと思いますけれども、いかがでしょうか。そういった形も含めて、ぜひ検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"児童扶養手当の追加の考え方ですけれども、こちらは児童扶養手当も国の法律に則っておりますので、区といたしましては方針として従っているところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"児童扶養手当のほうは国だと。区でやっている児童育成手当というほうもひとり親家庭だと思ったのですけれども、そういったことも含めて区として考えていただきたいと思うのですが、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"様々な社会状況がありますので、今、この段階では、まずは臨時特別給付金の一時金を考えて対応しているところでございまして、社会状況を踏まえて、区といたしまして対応すべきときに、しかるべきときに対応していきたいと考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、検討を進めていっていただきたいと思います。やはり新型コロナウイルス感染症の影響で立ち行かなくなって、再開後、認証保育所がなくなっているということは区としてもよくないことだと思いますので、家賃ですとか、人件費の固定費の補助をしていくべきではないかと思うのですが、いかがでしょうか。","respondent":"若生保育支援課長","answer":"対象期間がいつからかですが、実施期間に挙げさせていただいている登園自粛の働きかけを依頼している期間ということでございまして、具体的には、これは認可保育所も同様なのですけれども、３月分から登園自粛に伴っての保育料の返還ということで行っておりますので。","voiceIndex":13,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営費の補助は減らさないように国から指導されているというところもあって対応していくということでしたけれども、やはり今、新型コロナウイルス感染症の影響で、園への登録自体をやめてしまうという方も出てきているのかなと思うのです。ぜひやっていただきたいと思うのですが、改めてご答弁いただければと思います。","respondent":"若生保育支援課長","answer":"新型コロナウイルス感染症の影響等で在園の登録自体を外すといいますか、そういったことは事例としてお伺いはしていないところではあるのですけれども、基本的に認証保育所については、登録人数によって運営費等を算定していますので。","voiceIndex":15,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、固定費の補助ということを考えていただきたいと思います。次に、ベビーシッターの利用支援ですが、今回、補助の方法が２つあるということで、利用者にとっての違い、何が違うのか、利用する際にはどういう方がどちらのほうがいいのか、そういったところがよく分からなかったので伺いたいのと、都が認定したベビーシッターということで、何社ぐらいあるのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"そこで、今回、事業を開始するにあたって、４月にさかのぼって適用するという形になると、これまで仮に休園になってしまって、ベビーシッターを使用してしまって自己負担で全額支払ってしまった方についても補助の対象になってきますので、そういった場合には。","voiceIndex":18,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ利用者の方に分かりやすく周知をしていただけたらと思います。就学援助のほうなのですけれども、今回、これまで求めてきたものが実施されてよかったと考えています。これまで、難しいとおっしゃってこられましたけれども、どのように考え方を整理されたのか、伺いたいと思います。今回、１食５００円ということで考えた理由について伺いたいと思います。","respondent":"篠田学務課長、若生保育支援課長","answer":"１食５００円の考え方ですけれども、基本的には、いわゆる給食費相当分で考えますと食材費だけですので２４０円から３２０円と非常に低額で、なかなか１食分というのは難しいかなと。助成券方式、このベビーシッター事業者連携型というほうですけれども、こちらですと都が認定した事業者に限られますので、認定事業者として１５事業者となっております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"就学援助のほうで、考え方を整理されて実施されたということで、今回、４月、５月の２か月分ということですが、３月から休校されているので、ぜひ３月を入れていただきたいというふうに思うのですけれども、なぜ入れないのか、伺いたいと思います。今後、６月、まだちょっと分からない部分もありますが、今後の見通しも伺いたいと思います。","respondent":"篠田学務課長","answer":"こちらに関しましては、給食の再開は学校の再開に関わってくるということで、学校がいつから再開されるのか、また、どのような形で再開されていくのかによって、給食の提供等もいろいろ変わってきますので、そのときの状況を見ながら、必要に応じて。","voiceIndex":23,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"６月分というところでは、今後、学校がどう再開されていくかということもありましたけれども、ここがなかなか難しいところではあると思うのですが、休校の際にはぜひ広げていただきたいと思いますし、あと、開校に向けて、やはり今、子どもたちの学ぶ権利が脅かされているという状況になっていますので、なかなか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は関連していると思っているのですが、今、休校が長期化していて、宿題だけでいいのかというふうに思います。ぜひ今後の教育活動について、受験生もいらっしゃいますので、検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"就学援助の部分で昼食代、１食５００円。こちらは区の決断として、私も３月の委員会で言及させていただきましたし、会派としても４月に要望させていただいたところですけれども、これをやっていただいたということで大変に評価をしています。これは意見です。ベビーシッターが足らなくて、申し込んでもサービスを受けられないみたいな話になるような心配はないのかという点についてお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"これは区としてやっているところが、障害児ですとか、そういった集団保育が適さない場合の児童に対して１対１で保育をするというようなことで、ベビーシッターと似ている形ではあるのですが。","voiceIndex":31,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"特に新規の方のご利用が今回非常に増えてくるというところ、ニーズがあるというところで、都の支援も打ち出されてきたと思うので、新規の方へのご案内のあり方は非常にしっかりとやっていただきたいという思いがありますが、そこについての今の予定というか、どのように区内の子育て世帯の方にご利用をご案内していくのかというところで最後にお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"区市町村バウチャー型で届出している事業者の中に、当然、東京都で認定している１５事業者と重複している事業者もありますので、そこの中で先ほど言った１４０人の中にもそういった方は入ってくるというふうに認識しています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"今、少しお話があったかもしれないのですけれども、ベビーシッターについてお伺いいたします。資料では、「保育所等が臨時休園等を行ったことにより、」「ベビーシッターの利用を余儀なくされた場合」と書いてありますけれども、今回はその利用の要件として、保育園に入所していた、預けていたという方のみが対象になるという理解なのか。“入所していた”という要件が必要なのでしょうか。","respondent":"若生保育支援課長","answer":"対象者ですけれども、これは保育所等に通う児童ということになりますので、認可ですとか認証、それから認可外、そういったものを含めて、やはり“保育園に在園している”というところが要件になっているものです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"すみません、少し細かいところなのですが、確認させてください。もう１点、子育て世帯への臨時特別給付金についてのところ、こちらも確認だけなのですけれども、対象児童のところで、「上記のほか、同年３月分の児童手当の対象となっている児童であれば、４月から新高校１年生となっている場合も対象となります」とあるのですけれども、これはちょっと詳しく教えていただければと思います。","respondent":"若生保育支援課長、三ッ橋子育て応援課長","answer":"これは償還払い方式ですと、利用後に領収書ですとか証拠書類をご提出いただいて、その後、審査、支払いという形になりますので、通常ですと。すみません。交通費につきましては、現時点では対象とはしてございません。対象外です。したがいまして、３月分を含むという部分については、新高校１年生も含まれるということになっております。","voiceIndex":40,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"すみません、私の理解がちょっと悪くて申し訳ないのですが、先ほど、筒井委員が質問しましたベビーシッターの対象者ですけれども、医療従事者などの保護者の方に対しても保育所が開いていないところがあるということでよろしいのでしょうか。いまいちベビーシッターを利用する方がどのような方なのかが分からなくて。","respondent":"若生保育支援課長","answer":"基本的には、資料の事業概要に書かせていただいたとおり、新型コロナウイルス感染が発生して臨時休園してしまって、医療従事者等も含めて登園ができないような方がまずメインで対象になってくるだろうというようなことで考えております。","voiceIndex":46,"id":"exchange-015"},{"speaker":"せお委員","kind":"質問","question":"新型コロナウイルスに感染している方が保育所で出たという場合の休園となると、そのほかの方は濃厚接触者にはならないのですか。","respondent":"若生保育支援課長","answer":"濃厚接触者と判定された園児ですとか保護者が家にいらっしゃる場合は、当然、ベビーシッターの利用は難しいかと考えていますが、それ以外で、自粛されていて、実際は登園していなかったり、あるいは。","voiceIndex":48,"id":"exchange-016"},{"speaker":"せお委員","kind":"質問","question":"理解いたしました。１点だけ。子育て世帯への臨時特別給付金、児童手当の１万円の部分ですけれども、国からの全員に配られる１０万円の給付金にはあったのですけれども、ＤＶを受けて逃げていらっしゃる方に対しての周知について“こういう方法があります”ということがあったと思うのですけれども、児童手当の対象の方で、そういった対象の方はいらっしゃるのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"所得であったり、また、どちらが世帯主になるかとか、そういうものの中でＤＶについても、認定するにあたっては通常から取り組んでいるところですので、通常どおりということです。ホームページ上でも「ＤＶについては」という文言は載せる予定です。","voiceIndex":50,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは質問ではなくて要望するのですが、それぞれ都なりで対応して、いろいろこういった施策を行っていただいてありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":15601,"voices":66}},{"id":"r02-20200512-5","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"総務委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"私からは、民生費で、特別定額給付金の件でお聞きします。そういう中で、やはり支給がいつになるかという声をいろんな方からお聞きしました。ホームページで見ますと、申請書を送るのが今月の２２日だったと思いますが、それまでのことは事細かに書いているのですけれども、肝心要の給付の時期については特に記載がなかったものでしたので、まず、目安でも結構ですので、給付時期について教えてください。","respondent":"品川財政課長","answer":"特別定額給付金の支給についてです。５月１日よりコールセンター設置等をしまして、マイナンバーカードによるオンライン申請は５月１日から開始しております。支給ですけれども、オンライン申請については５月１８日頃を目途として出せればと考えています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"６月ではなくて、とにかく一刻も早く、５月下旬にでも支給してもらいたいという声がありますので、区役所の方も本当に大変だと思いますけれども、ぜひよろしくお願いします。今日も朝８時５０分に受付を締め切ったという話を聞いています。そういう情報をホームページで見たのですけれども、これは１日に受付できるキャパシティー、数があるそうなのです。そこを教えてもらってもよろしいでしょうか。","respondent":"品川財政課長","answer":"オンライン申請の受付ですけれども、確かに１日の上限というのはあって、この間、いろいろマイナンバーカードに関する申請関係が多くなっております。１つは、マスコミ等でも最近言われております、暗証番号を忘れてしまったという件です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"という感じの表示がされています。品川区でももう少し、人の流れというわけではないですけれども、申請をなるべく書類申請の方向に持っていくようにすれば、多分、朝、相当混雑されていると思うので、少しでも混雑解消、また３密の解消にもなると思うのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"この間、今回の補正予算にも出ておりますとおり、事務をなるべく郵送扱いという形で進めているところです。委員がおっしゃるとおり、こういったところについても、郵送受付を促していくような形で周知の努力をしていきたいと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"特別定額給付金の事務費のことなのですけれども、こちらは国庫支出金から出ていると思うのですけれども、これは前もって国から出された数字なのか、もしくは区から提示したものなのかを教えてもらえますでしょうか。","respondent":"品川財政課長","answer":"事務費につきましては、区で、委託費用、それからシステム等の改修費用を試算しまして計上しているものです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"これは東京都でも似たようなものがあったと思うのですけれども、たしかこれは商店街の加盟店舗の数・規模によって、最大１００万円だったと思うのですけれども、１００店舗以上、５０店舗から１００店舗未満、５０店舗未満で分かれていたと思うのですけれども、それ以外に何か要件というのはあるのでしょうか。それと、これは申請方式なのかどうかを教えてもらいたいのですけれども。","respondent":"品川財政課長","answer":"商店街の奨励金につきましては、基本的には、１００店舗以上の商店街、５０店舗以上１００店舗未満の商店街、５０店舗未満の商店街という形で、金額は分けてやっていく予定です。","voiceIndex":14,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"さらなる対策の充実をしていただきたいという視点で幾つか絞って伺いたいと思います。初めに補償についてです。あわせて伺いますが、ＰＣＲ検査にかかわる費用なのですけれども、やはり全額、国庫負担を、区として求めるべきだと思っているのですけれども、それについても、いろいろ同時に聞いてしまって申し訳ないのですが、それぞれお答えいただきたいと思います。","respondent":"品川財政課長","answer":"そういう中で、国に求めたりというところは、区としては避けていきたいと考えております。今後、ＰＣＲ検査等といったところも、国で補助を考えるような動き等も出てくるかもしれませんので、そういった状況も見極めながら、状況に応じて対応していきたいと考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、直接支援や補償について、区独自で進めていただきたいと思いますが、やはり各自治体が一丸となって取り組むべきときだから国に求めないといった姿勢では、今回のコロナ危機から住民の命と暮らし、営業を守ることはできないと思います。区も実施を見送っていく。そうしたことの検討も必要ではないかと思いますけれども、そもそもの考え方と具体的なことと、それぞれお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"それを見込みまして、それに合った歳出の考え方というところは、令和３年度予算編成にあたって、実際に必要になってくるところではないかと思います。","voiceIndex":18,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の補正予算には、学生への支援は位置づけられておりませんが、なぜなのかということを伺いたいと思います。例えば、大学生を含めた区独自の給付型奨学金や、国や都に対して授業料を半減するなどの要請をぜひやっていただきたいと思いますけれども、いかがでしょうか。中止というのは、現状の海上ルートに戻すということを求めていただきたいと思いますけれども、最後にいかがでしょうか。","respondent":"品川財政課長","answer":"はこういった状況も見ながら、かつ区としてどういう対応をしていったらいいかというところも踏まえながら、検討していきたいと考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"総合審査の説明についてなのですが、総務委員会で以前にもお話ししたのですけれど、結果だけでなく各委員会での議論の中身、経緯だったりも説明していただきたいですし、説明資料もより丁寧なものを求めたいと思います。要望ですが、何かお考えなどがあったら一言頂けたらと思います。これは要望です。こちらについて、区での検査結果の公表についてはどのようにお考えなのかということを伺いたいです。","respondent":"品川財政課長","answer":"ライフライン関係ですけれども、これについては、国等の動き、それから最近ではマスコミ等でもＮＨＫの料金など、いろいろ動きが出ているところですので、そういった状況も踏まえながら様子を見て、必要があれば対応していきたいと考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ライフラインの確保について、国等の動きを見てというのもあったのですけれど、都のほうでも、水道料金やライフラインの４カ月間の何らかの支援があったと思うのです。そういったことがわかりやすくホームページなどで掲載されたらいいということを、苦しい方たち、生活が苦しくなってきた方たちにとにかく情報が届くように、細かく発信していただけたらと要望いたしますが、いかがでしょうか。","respondent":"品川財政課長","answer":"それは、必要に応じて、ホームページ等、周知は考えていきたいと思います。","voiceIndex":24,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"あまり中身に入りたくはないのですが、確認だけさせていただきたいところが多少あります。それから、ベビーシッター利用支援事業助成とあるのですけれど、これは具体的にどんなものとして助成されていくのかということを、まず確認したいです。今の計算上、多分、二、三カ月はかかるはずです。さっきの答弁はちょっと危険だと思ったので、それは所管のほうといろいろ確認していただきたいと考えています。","respondent":"品川財政課長","answer":"５月末で全体のどれぐらいが出せるのかというところはまだ未定ですけれども、あくまでも郵送による申請でお金を出せる時期というのが、５月末を目途にというところでの説明です。","voiceIndex":27,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"少し大きなくくりで質問したいのですけれども、今回、新型コロナウイルス感染症対策での予算づけで、国・都からの補助金というか、いろいろあるのですけれども、１０分の１０ではないものがありますよね。本来だったら１０分の１０あっていいのではないですか。それが２分の１であったりするので、それはどういう考え方で、区のほうからのお金を出そうという考え方なのか。いかがでしょうか。","respondent":"品川財政課長","answer":"この財政調整基金は、使い方としては非常に柔軟に使える基金ですので、先ほど委員のほうで、見直し、考え直し等が必要ではないかというところなのですが、基本的には財政調整基金の中で対応できるのではないかと考えております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"例えばオリンピック・パラリンピックなど、延期になってしまったわけですから、それにかかわる経費というのは、来年度に回すという形もとれるわけであって、それはもう、今は集中して新型コロナウイルス感染症対策、あと経済を守っていくのだというところを区民の方にお願いして、「だから、ここの部分は我慢してください。生活を守っていくのだということを、ぜひ表明していただきたいと思います。","respondent":"品川財政課長","answer":"来年度予算につきましても、そういうところも踏まえて、とにかく区民が安心するような政策を積極的に打っていきたいと考えております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"専決処分にして、一日でも早く皆さんの手元に案内を送る。これは、区でどうしてこんな対応をしてしまったのか、私は不思議でならない。やはり、こういうふうに閣議決定して、皆さんがテレビや新聞報道で見ているならば、即刻、送れるような体制を敷いて、例えば外注にするのではなくて職員を使ってでも、一日でも早く送るべきだったと私は思うのですが、その辺について１点だけお答えください。","respondent":"品川財政課長","answer":"非常に早急にという思いについては区としても全く同じです。ただ、マスコミ等で日程がいろいろと出ているさなか、内部の事務処理の方向、方針といったところは、なかなか区でも、マスコミで出ている内容と同期を合わせて動いているものではないというところが１つあります。","voiceIndex":33,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"中小・零細企業、２万件あったらどうやって区で対応できるのですか。品川区はやはりこれだけ繁栄して、これだけ多くの産業が根づいているまちですから、その火は絶やさないようにしていただきたいと私は思います。ですけれど、世帯ですから、親に行くわけですよね。であるなら、やはり人のためになるお金の使い方というのをやってほしいのですが、その点について総合的に見解だけお聞かせください。","respondent":"品川財政課長","answer":"この間、新型コロナウイルス感染症対策を進めている中で、委員のお話のとおり、制度としては、区としてしっかりと対応している動きでいるところなのですが、どうしても実際に具体的事務手続きのところで時間がかかるという部分については。","voiceIndex":35,"id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"さっき伺ったのですけれど、聞き逃してしまったかもしれないので、確認なのですけれど、新型コロナウイルス感染症の影響で生活が困窮してしまった方に対して、住居確保給付金以外に区としての支援は、今、検討中なのでしょうか。それともまだ特には検討などはないのか。その部分をお聞かせいただけますか。","respondent":"品川財政課長","answer":"また１つ、このジャンルについては国の政策等でも、事業所のほうの家賃だと思いますけれど、若干ずれている部分があるかとは思いますが、動きは出ているところです。そういったところも見ながら必要性について検討して、必要があれば動いていきたいと考えております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった、相談に来た方などからも、今、どういった支援が必要なのかと聞き取ることなどは可能だと思いますし、またほかにもいろいろ方法があると思うので、ぜひ少しでも、皆さんの状態がどんどん悪い方向に行かないような支援を、区として当事者の方たちの声を聞いて進めていってほしいと要望いたしますが、いかがでしょうか。","respondent":"品川財政課長","answer":"当然、区民の声、それから状況等も考えながら、必要な施策に対しては早急に打っていきたいという考えは常に持っておりますので、時機を見て、必要であれば対応していきたいとは考えてあります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういったところで、窓口にかなり多くの方が来ているというところでは、行政が３密をつくるような体制を、何とか工夫して解消していっていただきたいという思いがありますので、ぜひその点は、今からでもできることをしていただければと思いますので、お考えをお聞かせいただければと思います。","respondent":"品川財政課長","answer":"区としても、本当にこの状況をできる限り早く解消していきたいと考えておりますので、どういう点を工夫すればそれがうまくできるのかというところも検討しながら、ぜひ利用者の方が本当に待つことがないような形でやっていきたいところもありますし。","voiceIndex":41,"id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"やはりマイナンバーカードを申請しに来てしまう方の印象としては、５月１日、マイナンバーカードがあればオンラインで申請できるというところの認識にあると思うので、そこを、先ほどのお話では、「郵送で受付けしていってください」という周知をされるということなのですが、今、マイナンバーカードを発行しても、かなり時間がかかるというところで、むしろ郵送のほうが早いのですというところも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"今、各委員の質疑で確認できたところもありますので、そういったところは除きます。それは、子育て世帯の臨時特別給付金についても、どういう封筒で送るのか、新しくつくるのか、この辺をまず教えてください。","respondent":"品川財政課長","answer":"封筒については、現在どのように動いているか、既存のものになるか、その辺は把握してございません。","voiceIndex":44,"id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"もし印刷を業者に委託するのだったら、そういうメッセージをちょっと添えて封筒に入れるなどということも、やはり区民全体で、そういう共通の価値観というか方向性を持って、みんなで乗り越えていこうというメッセージにもなるのではないかと思うので、当然、スピード感というのは大事なので、もしそんなのをやっている暇はないということだったら、当然必要ないのだけど、もし可能なのであれば。","respondent":"品川財政課長","answer":"なかなか全生徒に対してパソコンを配備してというような環境を整えるというのは、この間、各企業がテレワーク等動いている中で、やはりパソコンの台数などもなかなか確保できないという状況の中で、いかに今ある環境の中で。","voiceIndex":46,"id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"先ほど来あった、学生に対する支援も、これは既に公明党も自民党も、国のほうで困窮学生１人１０万円というのは政府に対して提言されて、これが答弁でも既に前向きな答弁が出ているわけですから、そういったことも含め、だけれども、そういったところになかなか支援の手が届かない、そうした区民に対する支援策を、やはり区も同時並行でしっかり考えていただくということも大事ではないかというのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"積極的な予算をさらにつけていただきたいということと、国に対してもしっかり意見を述べていただきたいと要望して賛成。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":28144,"voices":60}},{"id":"r02-20200512-10","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"議会運営委員会","time":"午後 ３時２５分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1180,"voices":8}},{"id":"r02-20200518-10","meetingId":"r02-cm05","date":"2020年5月18日","dateIso":"2020-05-18","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"資料Ｎｏ.２の常任委員会委員選出一覧表にかかわって一言申し上げたいと思うのですけれども、議会運営委員会委員長宛てに西本区議から意見が届けられていると思います。ご本人から、まだ返答がないということでした。返事をすべきではないかということが１つと、その意見も踏まえて再検討することも必要ではないかと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前回の議運で決定した事項ですので、全会一致ということでやっております。ですから、再検討は必要ないというのが自民党の判断です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"大倉委員","kind":"意見","question":"前回の決定どおりということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、その議運の後に、西本議員が、こういう文書を異議申し立て、再考を求めるということを書面に記して、もし委員長のお手元にも行っているならば、議運で云々ではなくて、委員長として西本議員に、こういうことで決まったからとか、こういう事情でこうなったとか、そういうご説明は少しでもされたらよかったのかなという、それだけ意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"各会派のご意見で見直す必要はないという意見が多数だったと思います。一言だけ意見を述べさせていただきたいと思いますが、やはり私も賛成しました前回の決定を受けて、西本議員から意見が上がり、そのご指摘をなるほどなと思うところがありました。提案のときに総合審査の話がありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6478,"voices":24}},{"id":"r02-20200519-6","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"区民委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番を入れ替えまして、２、その他","agenda":"の順番を入れ替えまして、２、その他","exchanges":[{"speaker":"こんの副委員長","kind":"意見","question":"今年度、昨年の５月から今日に至るまで、鈴木真澄委員長を中心に、委員の皆様、そして理事者の皆様にご協力いただきまして、無事滞りなくこの最後の委員会を迎えることになりまして、お世話になりました。思いもかけないこのコロナの問題で、全員の理事者の皆様にご挨拶できないのが残念ですが、両部長のほうから各課長にどうぞよろしくお伝えくださいませ。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"通知カード廃止に伴う事務の変更","agenda":"通知カード廃止に伴う事務の変更","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのですけれども、今、定額給付金の件でマイナンバーの担当課が非常に混乱しているということがニュースにもなっておりまして、その後、品川区で１日上限１００件というのはどのようになったかというのを１点伺いたいのと、こちらの件に関して、どれぐらい事務処理が発生して、今。","respondent":"木村戸籍住民課長","answer":"引き続き窓口では、なるべく早く受け取れるような形ということで、郵送、行き来の感染リスクを避けるということもありますので、そういう形をご案内してまいりたいと思っています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"連日お疲れさまです。窓口に来た場合でも引き続き利用することは可能ということであるのですけれども、これは期間としてはいつぐらいまでとかというのは、ずっとできるのか、それとも何年までなのかとか、そういうことは決まっているのか、教えていただきたいです。","respondent":"木村戸籍住民課長","answer":"国では経過措置というような言い方をしているのですけれども、具体的にそれがいつまでかというのはまだ示されていない状況です。おっしゃるように、未来永劫ということではないとは思っています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それからもう一つ、今のくにば委員と重複するようなことになるかもしれませんが、課長や部長が外で誘導されていたり、本当に連日ご努力はすごくされているなというので感謝申し上げたいところなのですが、やはり報道なんかでもとにかく行政のスピードがすごく求められる中で、国から急にこういうふうに各自治体でやってくれというところで。","respondent":"木村戸籍住民課長","answer":"特別定額給付金担当と連携いたしまして、これからどういうふうに出していくか、なかなか出し方は難しいところもあるのですけれども、郵送申請が２１日に発送して、これから郵送の処理が入り、大体それでどのぐらいの処理量でというところが出てくると思いますので。","voiceIndex":13,"id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問","question":"すいません、給付金の話になって申し訳ないですけれども、期間を例えばもう少しスピードを速めるために何ができるとか、そういったところはなかなか難しいところになってしまうものですか。人を増員するとか、そういったことというのは、なかなか扱うものが扱うものだけに難しいとか、そういうことになってくるところなのでしょうか。","respondent":"鈴木（真）委員長、木村戸籍住民課長","answer":"そこになってしまうと、部署も違ってくると思うので。答えられる範囲でよろしくお願いします。聞く話によれば、基本的には人海戦術しか今のところは、そういう仕組みというのですか、チェックしてというところは報道のとおりでございまして、そこの分量はどうしても縮められないところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"湯澤委員","kind":"意見","question":"本当に連日一生懸命やられた成果で、今日なんかはすごく空いていたななんて思っておりますが、またこのようなときもあるかもしれませんので、ぜひ引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"こういう細かいことは、実はそのときになって、窓口に来て、分からなくてということが、より窓口の煩雑さが、余計に負担がかかってしまうと思われるので、そこをなるだけ事前に軽減できるような方策としては、周知でここに記載されていますけれども、カードを作っている人はもうカードを作ってしまっているので、まだ作っていない方々にこうしたことを事前に分かりやすく何か通知するなどするほうが。","respondent":"木村戸籍住民課長","answer":"ただ、お知らせを最低限しておかなければいけないと思いますので、そういう手続のご案内のところに、例えばホームページであったりチラシであったり、ご案内をするときの本人確認資料という記載のところに丁寧にうたうような形で考えていきたいと思います。","voiceIndex":20,"id":"exchange-007"},{"speaker":"こんの副委員長","kind":"意見","question":"ですので、ただでさえ、今、本当にコロナの関係で全庁的に対応してくださって大変な中なので、そうではない通常の業務のところを何とか軽減できる対策という形で申し上げましたが、今おっしゃった対応も考えてくださっているということですので、引き続きご面倒をおかけいたしますけれども、そうした対策などもできる限り頑張っていただければなというところで、意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-008"}]},{"id":"topic-03","title":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","agenda":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今ご説明のあった無料相談窓口、最後の部分からお伺いしたいと思います。これはどのぐらいの、出張セミナーもありますけれども、無料相談窓口ということですが、どのぐらいの相談件数を予定なさっているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"国のほうでも徐々に、例えば今日、ホームページなんかを見た限りですと、五反田のＴＯＣとか青物横丁にも相談窓口を作るような内容を見たりしたので、それでかなりできてきているのかなとは思うのですけれども、かなり分かりづらいという話もあるので。","voiceIndex":27,"id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"日曜日、５月１７日付ですか、東京新聞の１面トップに、まさにこの２つの助成金、協力金をめぐって、法外な手数料を取るという記事が出ていて、そんなことはすべきではないという趣旨の記事なのですけれども、そういうのも出るぐらいに、自分で申請できるから自分で申請しなさいよとも書いているのですが、詳しい人はそれができるにしても、実態としては。","respondent":"遠藤商業・ものづくり課長","answer":"持続化給付金の代行というようなお話を頂きましたけれども、例えば国のほうで４００カ所以上のサポート窓口ができるというような話を聞いておりますので、基本的にこちらはパソコンでの申請ということで、インターネットでの申請と聞いておりますので。","voiceIndex":29,"id":"exchange-010"},{"speaker":"おくの委員","kind":"質問・要望","question":"ただ、実態としてはやはりありますもので、一応考えておいていただきたいとは思います。要望として出しておきます。それから、最初に戻ります。融資あっ旋の件数を教えていただきましたけれども、今のところ、あっ旋された件数は、さっきの話ですと５月７日現在１,６０３件、それから１５日現在で１,８２３件とお教えいただきました。実際に融資が実行された件数はどのぐらいになっているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"５月１２日に条例改正等をお願いさせていただいたときに実行件数をご案内させていただきましたが、あそこから変化は、今のところ、私どもでは把握できていない状況です。","voiceIndex":31,"id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"たしか４００件弱ぐらいだったと思うのですが、では、どのぐらいあっ旋して、全て実行されるものなのですか、結果的に。","respondent":"遠藤商業・ものづくり課長","answer":"融資あっ旋の金額ですが、うちのほうで恐らく、当時５００万円だったところが多かったので、目いっぱい、まずはうちのほうでお話しされるようなことが多いと。","voiceIndex":33,"id":"exchange-012"},{"speaker":"おくの委員","kind":"意見","question":"倒産というか経営危機に陥らせないぞと。その効果を表すためにも、あっ旋した以上はやはり融資の方向へ、融資の方向へ、１００％というのは……、本当に１００％を目指して頑張らなければいけないというのが政治、行政のやるスタンスだと思うのですけれども、六、七割では足りないと思うのですが、その点、どうお考えになりますか。","respondent":"遠藤商業・ものづくり課長","answer":"六、七割とご案内させていただいたのは、私どもが融資あっ旋した部分についての大体何割ぐらいかですので、融資のメニューは、当然区が融資あっ旋する部分以外にも、都道府県でも同じような融資制度をやっておりますし、また、東京商工会議所でもやられていますので。","voiceIndex":37,"id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"あっ旋したうち、あっ旋して、それで、いや、相談が来たりもするのですが、あっ旋してもらったけれども信用保証協会からオーケーが出ないとか、それから結果として融資が受けられないというような相談も来たりするのですが、そういう実態をどのぐらいおつかみになっていますか。お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"私どもで融資あっ旋した場合でも、その後、実際に貸す銀行あるいは保証協会がそれぞれ審査をやると聞いておりますので、当然その中では、国のほうでは随分、今回のコロナに対してはふだんと違うような対応をするようにという通知は出ているところではありますけれども。","voiceIndex":39,"id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"何で信用保証協会がオーケーを出さないのかとか、あるいは銀行が融資をしないのかとか、そこら辺、何が障害になっているのかというのを、せっかくあっ旋したのに何でそういうふうに結果として融資の実行に至らないのかというのを、私たちも、区側もつかんで、この融資あっ旋で枠をどんどん広げている、区内産業を本当に維持したいということでやっているわけではないですか。難しいとは思いますけれども。","respondent":"遠藤商業・ものづくり課長","answer":"実態を把握するということは大事かと考えていますので、ある程度終わってからになってしまうかもしれませんけれども、この辺の検証はしっかりしていきたいなと考えています。","voiceIndex":41,"id":"exchange-015"},{"speaker":"おくの委員","kind":"質問・要望","question":"絶対とか全部とか、私も言うつもりはないのです。私もここでうまいこと説明できないのですけれども、非常に専門的な理由で。終わってからではなくて、本当に今、倒産しそうなのだから、だからこそ広く融資が必要だしということだから、まさに同時進行的につかむように私たちは努力しなければいけないし、それを何とかできる限りやっていただきたいと思うのですけれども、いかがでしょう。","respondent":"遠藤商業・ものづくり課長","answer":"関係者からそれぞれ正式な回答という形ではないのですけれども、いろいろお話しする機会がありますので、その辺は捉えていきたいと思っています。","voiceIndex":43,"id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"前回の補正予算の審議は５月１２日でしたけれども、その２日後には江東区で家賃助成が始まりました。都の協力金の対象外の中小企業に対して家賃補助、条件はありますけれども、３０万円の給付というのが江東区の補正予算には盛り込まれました。品川区でもぜひこの方向を私は考えていただきたいと思います。固定費の助成ということに関して、今一度、どのようにお考えになるか、お願いいたしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"これまで私どもも様々な支援といいますか、融資の金額などを上げていただきまして、ほかの枠にないようなものを実施いただいたところです。今、家賃の助成ということがございました。","voiceIndex":45,"id":"exchange-017"},{"speaker":"松澤委員","kind":"確認","question":"融資の件で１つ、今、日本政策金融公庫などは民間の金融機関などと連携しまして、幅広く緩和をしましょうみたいな流れができていると確認しているのです。すいません、素人考えになってしまうかもしれないのですが、そういった融資保証の中で、品川区が後ろにつくといいますか、保証をする、保証人が品川区というのですか、何て言えばいいのか……。やめます。すいません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"いいですか。何て言ったらいいか。保証がうまくいかないからなかなかお金を借りられないという部分で、品川区が後ろに私たちがついているから大丈夫ですよみたいな形をとると、スムーズにお金が借りられるという。そんなイメージを持ったもので、そういうのがあると、スピード感を持ってお金を借りられるという部分で、いいのかなという。","respondent":"遠藤商業・ものづくり課長","answer":"私どもの融資あっ旋でできる部分につきましてはやらせていただいて、ほかのところの保証等につきましては、現在のところ、難しいかなと考えています。","voiceIndex":49,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"ではもう一つ、コロナでいろいろな部分で補償だ助成金だと一生懸命やって、本当に助かってありがたいのですけれども、終わりもあるわけですよね。終わりがあるという中で、これから先、今後を見据えて、では、これから産業で力を入れるにはどうすればいいのか。何かそういったコロナ収束後のビジョンというのですか、そういうのはまだ全然ないものなのですか。","respondent":"遠藤商業・ものづくり課長","answer":"コロナで大分落ち込んでいる部分がありますので、その後、各企業、商店街なども含めまして、いろいろな事業をやっていきたいという部分で、事態が治まればすぐにやりたいという部分があるかと思いますので、こちらとしてもできる限りの支援をやらせていただきたいということで。","voiceIndex":51,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、情報弱者を作ってもらいたくないという思いで質問させていただいているので、また今後、こういうようなことで何か作るのであれば、本当に丁寧に、同じことを何回も分かっているよというぐらい分かるようなパンフレットを作っていただきたいという思いが１点。もう１点は、この申込み方法で事前予約制は分かるのですが、株式会社キャンパスクリエイトというのは、今まで区と関係があった会社ですか。","respondent":"遠藤商業・ものづくり課長","answer":"最後に、中小企業診断士の窓口ですが、現行の融資等の相談につきましては現行のままの体制でやらせていただきまして、すいません、ご案内できませんで失礼しました、２つ、相談窓口を新たに設けするような形になりますけれども。","voiceIndex":53,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"細かくて申し訳ないのですけれども、なぜここの会社だったか。それとも東京とか国からご紹介を受けたとか、過去に何か一緒に仕事をした関係があったとか、なぜここが出てきたのかということを知りたいのです。私が要望したのが書いてあればもっとよかったと思うのですけれども。だって、２５日、３日間あるわけですよね、２２日からやるわけですから。その辺についてお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"本来であれば、前回の補正予算にこちらも本当は乗っけてお金を頂戴するのが筋だろうなとは思っていたのですけれども、そのときまでに金額も間に合わなかったようなところがございまして、ただ、少しでも急ぐという部分がございまして、契約につきましても。","voiceIndex":55,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"よく分かりました。納得しました。とにかく課長、今回は、全体を網羅していただきたいと思います。ちょっと分からないとか、特に高齢者の方で、先ほども言いましたけれども、パソコンとかあまりという方においても、決められた時間内だと思うのですけれども、丁寧に説明してあげて、この制度を活用していただけるようになっていただくことを本当に心から望みますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"課長も先ほどおっしゃったように、国のほうでも相談窓口を、五反田ＴＯＣとか青物横丁とか、そういったところでも開設を予定するとお聞きしているのですが、今回のご説明の中で、相談ブースが２つで１日大体十五、六件ということだと思うのですが、協力金のときは５０万円です、２店舗以上は１００万円ですと金額が決まっていたので。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業センター１階ロビーで、場所はありますので、あまりに集中するようであれば、中小企業診断士協会とも相談という形になりますけれども、そういう場面になりましたら、増やすことも考えていきたいと思います。","voiceIndex":58,"id":"exchange-024"},{"speaker":"こんの副委員長","kind":"確認","question":"先ほど藤原委員、そして湯澤委員からも同じような質問がありましたので、そこは重ならないようにお聞きしたいと思うのですが、１点、ちょっと重なってしまうかもしれませんけれども、確認ですが、中小企業診断士の相談窓口でやる相談請負業務というのでしょうか、どこまで相談に乗るかということ。細かいことで恐縮ですが、その辺をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"その辺をまず準備していただいて、それを持ってうちの相談窓口に来ていただいて、場合によっては計算などを一緒にさせていただいて、こうこうこうですから、これはこういう形になりますねというような話でサポートさせていただければという状況で今進めておりますので。","voiceIndex":60,"id":"exchange-025"},{"speaker":"こんの副委員長","kind":"質問","question":"分かりました。最初にそろえる書類について、自分で計算しなければいけないのを中小企業診断士と一緒に計算をして書き込む数字など書類を用意して、それを持ってサポート会場に行って入力のお手伝いをしてもらうという、こういう２段階で、品川区は申請を希望する人にきちんと給付金が行き渡るようなサポート、支援をするという理解でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回お見えになる方は、パソコンの操作も慣れていないでしょうし、そもそも申請自体やったことがないという方を想定しておりますので、できるだけ丁寧に、本人がちゃんと分かるような形で、場合によってはメモなども作りながらやっていきたいと考えています。","voiceIndex":62,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19361,"voices":66}},{"id":"r02-20200519-7","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)を先に行います。 それでは、(4)新型コロナウイルス感染症の対応","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)を先に行います。 それでは、(4)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、その中で専門外来に紹介される方がどう変わっているのか、また件数についても、４月３０日までは２６６人ということで伺っているのですけれども、その確認と、どう件数が変わっているのかについてもお聞かせいただきたいと思います。ということになると、今、１８６人までの感染者が確認されているわけですけれども、併せて濃厚接触者の合計の人数が何人ぐらいになるのか。","respondent":"鷹箸保健予防課長","answer":"それから次の質問にも移ってしまうのですが、濃厚接触者も非常に、１８６人いればお１人、ご夫婦であればその同じ人数、家族が４人ならと、たくさん出るので、それを全部我々常勤だけではできませんので、それも派遣の看護師たちにかなりの数をお願いして対応しています。","voiceIndex":7,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、クリニックのドクターから直接帰国者・接触者外来に紹介されるという件数もあると思うのですけれども、そこのところは把握がされていないということだったので、ちょっと分からなかったですが、品川区の相談センターに来た人数のうち、帰国者・接触者外来に行ったのは２６６人と４月末の段階で伺っていたので、それからさらに検査の件数は減るのかと私は思っていたのですけれども。","respondent":"鷹箸保健予防課長","answer":"先ほどの１,４７０件は保健所のほうの電話相談からご紹介した数以外に、医療機関が紹介した数を全部合わせたものが１,４７０件で、ものすごい数が区内の医療機関あるいは区外の医療機関も含めて帰国者・接触者外来に紹介をされて。","voiceIndex":13,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それから保健所の皆さんの頑張りも本当にあって、また医療機関の皆さんの頑張りや努力によって感染が随分少なくなってきたし、また季節的なものもあると思うのですけれども、そういう状況の中で、これから第二波、第三波が必ずやってくるだろうという中で、それに備えた対策を今、この少なくなった時点でやっていくことが必要なのではないかということが言われていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"保健所の件についてはいろいろ伺ったのですけれども、保健センターのほうの対応なのですが、乳幼児健診は元々ずっと密な感じでやっていたと思うのです。それに加えてこれまでちょっとお休みしていた部分だけ人数も増えていると思うのですけれども、具体的にどういう形でやっていくことを考えていらっしゃいますか。","respondent":"榎本荏原保健センター所長","answer":"その４か月児健診を進めながら、その後については１歳６か月児と３歳児健診も、１回の対象人数を減らしますとちょっと回数を増やさないと難しいというところはどうしても出てきますので、そこも工夫しながら全体のスケジュールをうまく組んでやっていきたいと考えています。","voiceIndex":20,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"前段のこれまでのところなのですけれども、電話相談あるいはアンケートの返ってきた割合はどのように数字で把握していますか。それから時間を区切ってというのは保健センター側から時間を区切って、あなたは例えばこの日の何時何分から何分の間みたいな形でやっていくのでしょうか。そうすると、何か逆に行けない方も増えてしまうのかなと思うのですが、そこら辺は何か工夫があるか教えてください。","respondent":"榎本荏原保健センター所長","answer":"アンケートの返信についてですけれども、センターによって違うと思いますが、８割から９割ぐらいは返信があって、返信がなかった方にお電話をして返信をいただいたとかというのも含めると、９割ぐらいは集まってきておりまして、アンケートに返信のなかった方にはお電話をして。","voiceIndex":22,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"すごく丁寧にやっていただいて、ありがたいと思います。それからお伺いしたいのが、今、コロナで（２）に関係してくるところでもあるのですけれども、いろいろな処方箋などが電話で取れるなどの緩和措置があって、これというのはこの緊急事態宣言ですが、この時期が終わってももう半永久的と言ったらいいのか、こうした体制は続いていくのでしょうか。これはもし分かれば教えていただきたいと思います。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"今回、確かにコロナ対応で特別な通知が出されているのですけれども、これまではオンライン診療は初回は必ず面談というか診察。オンライン診療は見直しを行うことになっています。それと新しい形で進めることになっているから、進める方向は変わらないと思います。","voiceIndex":24,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"初診についてはいろいろハードルもあるかと思うのですけれども、通院だと、逆にずっと長く療養されている方なんかの処方箋を電話、ファックスなどでできるというのも、しかも郵送で送ってもらうみたいなのもあったと思いますけれども、その点はどうでしょう。それももしご存じでしたら教えてください。","respondent":"鷹箸保健予防課長","answer":"処方はそのまま継続というのは今までもでしたし、今後も可能かと思います。今回、自宅療養の方に対しても、継続な処方が必要な方については……。","voiceIndex":27,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"ＰＣＲ検査センターを設置して３日間ということで、初動の対応だけお聞きしたいと思います。３日間で３５件ということで、まずこの３５件それぞれの医師会の所属の、いわゆるかかりつけ医等からのご紹介ということで、何軒のクリニックからのご紹介だったかを一つ確認させていただいて、分母として両医師会全体の先生、何百といらっしゃって、そのうちこういうことに参画されている方。教えてください。","respondent":"舩木保健体制整備担当課長","answer":"幾つかご質問をいただきましたが、先週３日間開設いたしましたところで、どのぐらいのかかりつけ医から来た結果の３５件であるとか、全体の医師会の会員の先生方でどのぐらいのご協力をというところにつきましては、実は定期的に医師会と私どもで情報交換といいますか。","voiceIndex":31,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと質問を忘れていたのですけれども、前回もお伺いしました妊婦パッケージ、保健センター。その後、どういう形で実施するか、検討を進められましたか。この間は検討中というお話だったと思いますけれども。","respondent":"榎本荏原保健センター所長","answer":"妊婦の追加パッケージの話で、多分、対象の方のさかのぼりというか、その辺りの話かと。検討中と、まだちょっと未確定というところで、都からは基準日が４月１日。その話でしょうか。","voiceIndex":37,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"都が言っているのは４月１日に妊娠状態であった方が対象で、その後生まれた方でもオーケーだよと。その後生まれたのはオーケーだけれども、４月１日以降に新たに妊娠された方はちょっとペンディングだけれども、区で何らか対象にしようと考えているという意味で受け取ってよろしいのでしょうか。それとスケジュール的なものも併せて教えていただけば。基準日というのはそういう意味ですね。","respondent":"榎本荏原保健センター所長","answer":"都からの通知の基準日というのは４月１日以降、今年度３月３１日までの時点で妊婦だった方を全て対象にするということなのですが、妊娠中に状況把握や相談をしたということが前提でありましたので。","voiceIndex":41,"id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"電話相談はもう始まって、電話での確認とかはもう始まっているということでよろしいのでしょうか。","respondent":"榎本荏原保健センター所長","answer":"電話での相談が始まっているかというご質問でしたけれども、基本的には電話ですと、お１人お１人というとかなり時間がかかってしまいますので、いろいろ検討して、アンケートのやりとりでという形をまずとって。","voiceIndex":43,"id":"exchange-011"}]},{"id":"topic-02","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと確認させていただきたいのが、改めてなのですけれども、この月見橋の家というのは元々何の施設だったのか、たしかデイサービスはしていたような気がするのですが、どういう施設だったのかを改めて教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"月見橋の家の仕様・構造の変更ですが、ここは、細かいところはまだ伺ってはいないのですが、ただ、当初予定していた元に戻ったとき、工事に入る前に３階建てだった建物といった構造の大きなところは変更はないと伺っております。","voiceIndex":50,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここに仕様・構造の変更に伴う到達防護工の見直しによる補助工法の追加と書いてあるのでちょっと伺ったのですが、基本的には変わらないのに、そこがこういうふうに書いてあるのはどういうことなのかがちょっとよく分からないです。","respondent":"宮尾高齢者福祉課長","answer":"私が変わらないと申し上げたのは、基本的な施設の構成ですとか、広さですとか、当初予定をしておりました内容とか、そこはしっかりと担保をしてもらえるです。工事の詳しい工法については存じ上げておりませんが、そこはしっかりと担保してくれるということは確認をしています。","voiceIndex":52,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"この仮移転先というのは、何といってもプレハブ造りで、そこまで長年使うことを想定はしていなかたのではないかと思うのですが、一応の耐用年数とか契約年数、それからなかなか工事で６年間一気に延びるというのは珍しいと思うのですけれども、その間に例えば不具合が出てきたりとか、居住性が落ちていたりとか、何かこの仮移転先の改善みたいなことの必要性をどう受け止めて。","respondent":"宮尾高齢者福祉課長","answer":"仮移転先のプレハブですが、実は今回、工事の変更が決まるのが３回目なのです。","voiceIndex":56,"id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"やはりプレハブがかなり長期になっていて、恒久施設よりも居住性が劣るのは確かなので、不具合を直すというだけではなくて、ちょっと今の施設の基準に合わせたようなことを考えていただけるとありがたいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-015"}]},{"id":"topic-03","title":"西大井三丁目国家公務員宿舎","agenda":"西大井三丁目国家公務員宿舎","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの場所は防災機能ということで防災広場と障害者施設ということなのですけれども、おおよそ半々ぐらいの面積の割合ということになるのでしょうか。障害者グループホームや短期入所などの障害者施設の規模がどれぐらいになるのかが今の時点で決まっているようであれば、土地の面積ですとか延床面積、どれぐらいの障害者施設がつくられるのかというところを教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"２点目にグループホームと短期入所の人数ですけれども、この敷地内で最大の人数ということで今、想定しまして、１９人程度ということになっております。そのうち短期入所ですけれども、今のところ３名を予定しています。","voiceIndex":64,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者のグループホームにしても、短期入所にしても、すごく障害者の皆さんから待ちに待たれている施設ですので、こういう形でできるのはすごく当事者また家族の皆さんにとってもすごく待ち望んだ施設ということになると思うのですけれども、そこの中で、例えば短期入所では医療的ケアの人とかも対象にするのかとか。","respondent":"松山障害者福祉課長","answer":"今後ですけれども、そういったお声は障害者福祉課あるいは今回の基礎調査等々の中から既に頂いております。現在のこちらの説明会は周辺住民に対する説明会ですので、そちらのお声も併せて頂きながら、区として検討を図ってまいりたいと考えています。","voiceIndex":66,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"地域の方に対しての説明会はもうされていますよね。障害者の当事者、家族の方、団体の皆さんですとか、そういう関係の方のところに対して、ここにこういう施設ができるという説明会みたいなのはいつ頃計画されているのかについて、最後にお聞かせください。","respondent":"松山障害者福祉課長","answer":"現段階では１９名程度の障害者のグループホームをこちらのほうに国の土地を取得して造りたいということで、案を住民説明会のほうに出させていただいたという時点ですので、もう少し固まりましたら、詳細については当事者に。","voiceIndex":68,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に一言。実際に当事者やご家族の方というのはいろいろな思いを持っていらっしゃいますので、また設計とかということに対してもいろいろなご要望とか何かもあると思いますので、ぜひ当事者、家族の方々の声を聞きながら進めていただくということでよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-019"},{"speaker":"あべ委員","kind":"確認","question":"これも多分指定管理で運営をされていくことになるのか、ちょっと先ほどのやりとりがよく分からなかったのですけれども、それを確認したいのと、施設の設計よりも前なのか後なのか、それはどんな感じの順番で考えていらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"それから設計については、運営事業者と設計事業者ということになろうかと思いますけれども、設計の後で運営をと今のところは考えております。","voiceIndex":71,"id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"まだ取得前なのでということですけれども、直営でやるということはなかなか考えづらいのかと思います。運営しやすい施設づくりという観点も必要だと思いますので、また取得後により良い方法を考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-021"}]},{"id":"topic-04","title":"医療的ケア児地域生活支援促進事業","agenda":"医療的ケア児地域生活支援促進事業","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医療的ケア児の施設をつくるということなんですけれども、そもそも医療的ケア児の人数が何人いるのかを教えていただきたいと思います。もう１つは医療的ケア児の方が通ってくる場合に、かなり様々準備をしたりとか大変な状況があると思うのですけれども、送迎はあるのかどうかについても教えてください。","respondent":"松山障害者福祉課長","answer":"それから全ての医療的ケア児が対象なのかというご質問ですけれども、人工呼吸器を付けている方を含めた全ての医療的ケアが必要なお子さんが対象と考えています。それから３点目、送迎についてですが、現段階では難しいと考えています。","voiceIndex":79,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それなので、この２５人というのはアンケートに答えた数であって、実際はもっと多いのではないかと思うのですけれども、そういう点でいえば、なぜこの２３人ということになるのかという思いがしているのですが、なかなかこの医療的ケアの方というのは障害福祉サービスを受けられていない方が多くて、医療のほうだけ使われているという方がすごく多かったりするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません。それともう１つなのですけれども、今回の地域生活支援促進事業というのは区の独自の事業ということでいいのでしょうか。地域生活支援事業として区が行うということでもないということで、丸々区の事業ということで捉えていいのか、その点についても伺いたいと思います。そのところをお願いします。","respondent":"松山障害者福祉課長","answer":"地域生活支援事業の枠組みに当てはまるのか、今後医療的ケアの国からの補助事業に当てはまるのかは、しばらく様子を見ながら事業の組み立てをしていきたいと考えています。","voiceIndex":83,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"医療的ケアの方を１人で乗せることがなかなか大変なので行動が制限されるとか、常に介護者と運転者の２人が必要だとか、感染に気を付けなければならないので移動手段に制限があるとか、とにかく酸素ボンベだったりとか呼吸器だったりとかということで、とにかく荷物も多いし、残量も気になるし、感染のリスクも考えなくてはいけないので。","respondent":"松山障害者福祉課長","answer":"ただ、戸越ルームという立地の状況です。今後、現段階ではまずは相談とつどいの場所、あるいは交流の場所、遊び場の提供から始めるですので、この状態から始めて、今後、医療的ケア児を支えるようなことのサービスにつながればと考えています。","voiceIndex":85,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あの中でせめて医療的ケアの方が出していただいたものを独自に集計して、そこの中からニーズを把握するということができるものなのかどうなのか、ちょっと検討していただきたいと思うのと、それから私は、改めてそれほど多い人数ではないので、医療的ケア児、これから協議会も立ち上げていくわけですから、医療的ケア児・者に対するニーズ調査を行い。","respondent":"松山障害者福祉課長","answer":"１点目ですけれども、確かに送迎については課題と認識しておりますし、医療的ケアのお子さんを抱える保護者の声を実際に生で聞ける貴重な場所だと感じておりますので、そういったご相談のお声を聞きながら今後の事業展開につなげていきたいと考えています。","voiceIndex":87,"id":"exchange-026"},{"speaker":"西村委員","kind":"質問・要望","question":"もう１つが、実際に親御さんたちのいろいろなワークショップとか話し合いとかどういう形になるか分からないですけれども、同じ思いを共有したりしている時間だけでもお子さんを一時預かりしてくださったり、その時間だけでも見ていただいたり、そういった要望もありまして、世田谷区にあるもみじの家なんかは利用面談が３年待ちだそうで、それぐらいの人気の、皆さんに注目される施設になるといいなと思うと。","respondent":"松山障害者福祉課長","answer":"使いやすい施設にするためのやはり外出サポートというご提案を頂きましたので、検討していきたいと考えています。それから２点目ですけれども、事業内容の工夫、運営方法の中でお子さんを預かりしてという形になろうかと思います。","voiceIndex":89,"id":"exchange-027"},{"speaker":"西村委員","kind":"質問・要望","question":"プロポーザルもまだこれからなのですけれども、こういった取組みをやるというような事業者にぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"区内の医療的ケア児はとりあえず２３人という数字が出ていたわけですけれども、これは１８歳以下の全てのお子さんと考えてよろしいでしょうか。この２３人の中で、送迎がなくても自力で、もちろんお子さん、もちろんと言っていいのか、ここに来られる方というのはどのぐらいの割合の方がいらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"自力でいらっしゃれるかどうかはちょっとこちらのほうではまだ把握はしておりませんが、何かしらのサポートでいらっしゃれる方が、人数的には明確にお答えはできませんけれども、全くいらっしゃれないという方はそれほど多くはないであろうと思います。","voiceIndex":92,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうした施設ができるのは大変ありがたいなと思いますし、必要な方皆さんに活用していただきたいと思うのです。なので人数が少ないわけですから、そこを１人１人潰していってほしい。ちょっとそれについてのお考えを伺いたいと思います。使い方として、予約制になっていくのでしょうか。相談は予約だと思うのですけれども、利用自体はどのようにお考えでしょうか。","respondent":"松山障害者福祉課長","answer":"それから２点目の予約制なのか、ふらっと行けるのかというところですけれども、確かにふらっとというのがなかなかもちろん厳しいところではありますけれども、ただできれば区といたしましては、兄弟のお子さんも一緒に連れて。","voiceIndex":94,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"そうするごとにそれぞれスタッフが必要になると思います。１,２００万円のほとんどが人件費だと思うのですけれども、この委託料の設定できちんと医療的ケアに対応できるスタッフの方が雇えるのかとちょっと疑問なのですが、委託料の中の人件費を幾らと見込んでいらっしゃるのでしょうか。それで十分とお考えになられるか教えてください。","respondent":"松山障害者福祉課長","answer":"委託料は委員のご指摘のとおり、ほぼ人件費です。人件費につきましては、１月から３月の間、３か月分を見込んでおりますので、こちらのほう、委託料につきましては、十分に可能なものと考えております。","voiceIndex":96,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと安心しました。この数字で年間なのはあまりにもどうするのだろうという感じだったので、それはちょっと安心いたしました。ただ、ここで看護師以外のスタッフが相当の経験を持った方でないとと思うのですけれども、そこが実施要領の中ではちょっと見当たらなかったものですから、それを加えたほうがいいのではないかと思うのですが、どのように思われるでしょうか。","respondent":"松山障害者福祉課長","answer":"やはり相談時に医療的なケアの相談が受けられるという体制をとるためには、一定程度の経験が必要なものと考えております。こちらの公募案につきましては、あくまでも案とさせていただいています。ちょっと入れる文言については検討していきたいと考えています。","voiceIndex":98,"id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"ぜひよろしくお願いします。この医療的ケアの施設なのですが、品川区としての医療的なケアの子どもたちに対する医療的ケアに関する政策とセットで動いていくと思うのですけれども、先ほどもちょっと出ましたが、協議会との関係、それから既に動いている地域自立支援協議会との関係というのは、この施設をどう捉えたらいいのでしょうか。","respondent":"松山障害者福祉課長","answer":"自立支援協議会は非常に課題の範囲が広うありますので、医療的ケアにつきましてはこちらの医療的ケアに特化した連絡会で意見交換、情報共有、連携強化を行ってまいりたいと考えております。","voiceIndex":100,"id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"それから本年度コロナで止まってしまっている部分があるのですけれども、見通しなり教えていただければと思います。","respondent":"松山障害者福祉課長","answer":"協議会の開催の仕方も、例えば東京都自立支援協議会ですと書面開催ですとかいったようなこともやってありますので、そういったことも含めまして考えていきたいと思っています。","voiceIndex":102,"id":"exchange-034"},{"speaker":"あべ委員","kind":"提案","question":"書面開催も結構いいと思いますし、今でしたら障害がある方、当事者も参加できるという意味ではオンライン開催なども含めて考えていっていただくといいかと思います。最後は提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"厚労省のほうが医療的ケア児・者の問題とかを話し合う協議の場をつくるようにということで、平成３０年度末までに各自治体でそういう協議の場をつくるようにという方針を出して、品川区の場合、１年ちょっと遅れてしまっているような状況で、でももう準備会はつくられて、コロナの問題がなければもう協議会も実際に動き出すというところまで来ていたと思うのですけれども、コロナの問題があって。","respondent":"松山障害者福祉課長","answer":"それから大人のほうに関しますと、ピッコロが始まっておりますので、そちらのメンバーになります。大体メンバーは２０人以内を想定しております。それから障害者団体です。２つの団体から出ていただいています。","voiceIndex":105,"id":"exchange-036"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"どうも１年間お疲れさまです。引き続き、区民の皆さんや施設の要望をお聞きいただいて応えていただけたらと思いますし、第二波、第三波というのも心配される中ですので、今後も見通して、区民の命と暮らしを守るために共に頑張っていけたらと思います。１年間、お疲れさまでした。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3566#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29621,"voices":114}},{"id":"r02-20200519-8","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"建設委員会","time":"午後 １時００分～午後 ３時３３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すみません、議事進行について若干の意見とご質問があるので、発言します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":2,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"もちろん新型コロナウイルス感染症対応ということは分かるのですけれども、換気ですとかこまめな休憩などを行えば審査をすることはできるのではないかと思いますし、すべきではなかったのかなと思うのですけれども、冒頭、今回の委員長の判断の理由を伺わせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-002"}]},{"id":"topic-02","title":"先ほど申し上げましたとおり、聴取する順番を変更し、(2)から(4)を先に取り上げてまいります。 それでは、(2)令和２年６月都営住宅入居者募集","agenda":"先ほど申し上げましたとおり、聴取する順番を変更し、(2)から(4)を先に取り上げてまいります。 それでは、(2)令和２年６月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"後ほど区営住宅、区民住宅の使用料等の猶予および分納についての報告があると思うのですけど、こちらの都営住宅では使用料の納付期限猶予、あるいは減額や免除などの対応などそういった動きがあるのか、そこら辺、もし分かっていたら教えてください。","respondent":"森住宅課長","answer":"収入が大きく減少したということであれば、例えば収入認定の見直しとかは、通常どおりやっていると聞いております。猶予につきましても、詳しい条件等は手元にございませんが、そういう対応をしているとは聞いております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"区としても、都営住宅の入居者募集のお知らせをいろいろなところにするときに、従来からの制度とはいっても、こういう場合はそういった措置もあるのだということで、ぜひ区民の方に伝わるように、周知など工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-03","title":"西大井三丁目国家公務員宿舎","agenda":"西大井三丁目国家公務員宿舎","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"３月１２日に、要望のとおり売払を決定する通知を受けたとありますが、これはいわゆる貸付ではなくて、売りますよということだけが通知されたのか、金額等はこれからの交渉なのか、いかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"委員ご指摘のとおりでして、今回、売り払うことの決定ということですので、この後、品川区だけですけれども、入札という手続に進みまして、今年度中に取得の手続を進めるという手順になっております。","voiceIndex":16,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川区が買うわけですけれども、入札という表現になると。それで、予算特別委員会のときも質問したのですけど、予算書に予定の取得費用がありますので、そこを上限にして、できる限り安く買っていただきたいと思っているのですけれども、一応その辺の考え方について。","respondent":"佐藤木密整備推進課長","answer":"今年度予算につきましては、木密整備推進課と障害者福祉課が約半分ずつということで計上しておりますので、その範囲で再度、精査いたしまして、入札に進むということになります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"事業説明会とワークショップは大体いつ頃の開催を目指しているのか伺います。ワークショップですけれども、行財政改革特別委員会で説明があったときに、木密事業の内容で行いますみたいなことだったのですが、具体的な流れというのですか、あるいは回数みたいなものですとか、人数や想定対象者なども、教えていただければと思います。","respondent":"佐藤木密整備推進課長","answer":"今回の新型コロナウイルス感染症の関係もございまして、スケジュール的には遅れております。現在の緊急事態宣言が解除されるのを待ちまして、地域の方に周知させていただいて、まずは事業説明会を一度、開かせていただいた上で、希望者の方を募集します。","voiceIndex":20,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"前回、昨年９月に住民に対して計画、粗々なところだったのですけれども、説明会が行われましたけれども、時間が大分、経過しているので、こういう検討状況というのを一度、事業説明会の前にでも何らか、ニュースの発行なのか、いろいろ工夫してお知らせすることが必要なのではないかと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"佐藤木密整備推進課長","answer":"委員ご指摘のとおり、昨年９月に一度、事業説明会を行っております。それも踏まえまして、今回、再度、事業説明会を予定しておりますので、当該敷地から一定の範囲の方々にポスティング等をいたしまして周知した上で、事業説明会ということを予定しております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"周知というのは開催の周知ということですよね。重ねてお願いしたいのですが、どうなったのだろうということで、新型コロナウイルス感染症の問題もあるので、いつ終束するかというのもまだ見通せないところがあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"所管同士のすり合わせと同時に、地域で暮らす障害者の方たちとなると、もっと難しいと思うのです。品川区はそういった施設が少ないですから。そういう方たちとの意見のすり合わせにあたっては、ぜひ円満に、両方にとっていい施設になってほしいと思うので、その辺はどういうふうに計画されているのか伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"残ったところは防災広場として活用しようという形になって、ここまで来ております。昨年９月の説明会の際も、そういった形で地域の方には説明しておりますが、今後とも説明会等の機会を捉えて説明して、納得を得ていきたいと考えております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"そういうときは、所管はもう関わらない感じですか。障害者施設のほうは障害者施設のほうでワークショップなり何なりやるとして、これは所管が違いますという話なのか、同じところにできるのだからお互いに連携しながらやりましょうよというのをこちらから働きかけるとかそういうことができるのか、その辺を伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"昨年、９月に行いました住民説明会は、もちろん両課で対応いたしまして、今年度、これから予定しておりますけれども、住民説明会も、両課で対応したいと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"吉田委員","kind":"意見","question":"そういうふうに丁寧に進められてきているので、きっとそういうことはないと思うのですけれども、一般的な例として、障害者のグループホーム、居住の場、そういうものができるときに、時々、近隣から反対運動が起きるというのが現実にあります。障害者当事者の方たちも、ぜひ所管に働きかけてほしいと思いますけれども、こちらの課でもくれぐれもお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、１点だけ教えてください。どうしてかというと、１,６００m2の中の建蔽、容積でやるのか、それとも８００m2の中での容積、建蔽でやるのかで大分、建て方が変わってくると思う。今、敷地の利用は、８００m2ぐらいになりますということなのだけれども、その意味がよく分からない。そこら辺のテクニカルな話も教えていただければと思います。","respondent":"佐藤木密整備推進課長","answer":"ただ、三方は現状の道路で囲われておりますので、そこの空間については適切に確保できるように、これからも連携して設計していくという形を考えております。","voiceIndex":30,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"お願いだけしておきます。１,６００m2の中でグループホームをどれぐらいにするかというのはあるけれども、それで容積、建蔽を使ってそれなりの、敷地は８００m2だとしても、外構でくくるかどうかは別としても、例えば８００m2にして、それなりのグループホームをその中の容積、建蔽でやると、そして外周もとなると、結構無駄なスペースができる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-014"}]},{"id":"topic-04","title":"（仮称）品川区立環境学習交流施設の検討状況","agenda":"（仮称）品川区立環境学習交流施設の検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"少し具体的なところをお伺いしたいのですけれども、資料別紙の建物パースの公園南側というところなのですけれども、前回でしたか、この場所に幼い子供向けの遊具スペースがあるので、代わりとなるものを引き続き確保していただきたいということで質問し、じゃぶじゃぶ池などを今、検討していますということだったのですけれども、このパースだと、滑り台とかはありますけれども。","respondent":"提坂環境課長","answer":"樹木の伐採ですけれども、樹木診断を行いまして、敷地内に３メートル以上の高木が４５本ございまして、そのおのおのについて診断を実施したところです。","voiceIndex":37,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し大きなところで幾つかお伺いします。この大きな視点というのも学習できるような施設にすべきだと思うのですけれども、いかがでしょうかというのが１点目です。講座計画に、戸越公園内の池・樹木を活用した工作等とありますけれども、豊かな自然がある戸越公園内ならではの施設にしていく必要があると思うのですけれども、その点での工夫などは何かあるのでしょうか、伺わせてください。２点目です。","respondent":"提坂環境課長","answer":"最初のご質問につきましては、施設の中で現在、地球規模で起きている環境問題ですとか、あとは身近なところで起きている環境問題、それから過去にこういういろいろな環境上の問題が起きてきましたとか、そういうところを分かっていただくような展示とか。","voiceIndex":39,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。やはり地域とともにという点で強調されていますので、最初のスタートの地点である程度、今後のことを考えて、住民に直接説明する機会というのは、時期とか手法は工夫しつつも、これは重要なスタート時点での説明なのではないかと思うのですけれども、そこら辺の改善というか工夫をしていくべきだと思いますが、いかがでしょうか。","respondent":"提坂環境課長","answer":"それで、その上で今回、三ツ木保育園の仮設園舎ですとか戸越公園の管理事務所の解体工事と合わせて、説明会を合同で行いたいところであったのですが、令和４年４月の開設へ向けていろいろとスケジュールを立てますと、この５月末というのがぎりぎりの線で。","voiceIndex":41,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域とともに歩む施設というこのコンセプトから考えて、やはり私はそこら辺は丁寧にやっていくべきだと思いますので、座席を離すとかいろいろ工夫はあると思いますし、あるいは希望者の方だけしか来ないわけですから、１２月の工事説明会までまだ時間もありますので、新型コロナウイルス感染症等々の感染拡大防止というのは一番最優先ではありますが。","respondent":"提坂環境課長","answer":"地中熱の関係でご説明しますけれども、空調の省エネの対策ということで、地下にある温度の安定した地下水を活用した空調ということでございまして、そもそも地中熱というのが一般的に地表からおおよそ地下２００メートルの深さまでの地中にある熱のことを指してございまして。","voiceIndex":43,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"その後、前任の環境課長はその説明会での住民の皆さんの反応を受けて、丁寧にそのご意見も聞きながら、こちらの計画も変えられるようなところは変えて進めておりますというのを後追いのご説明で伺っていたのですけれども、そういうことでいうと、去年の説明会の後、それなりに近隣の住民の方たちとの関係はつくりながらここまで計画を進めてこられているのだろうなと私は解釈していたのですが。","respondent":"提坂環境課長、森住宅課長、中村都市環境部長","answer":"今後の工事説明会までの間に説明会を行わないのかですが、一応、今、実施設計を進めているところで、７月が工期となってございまして。こういう理由で、説明会ではなくて戸別配布をさせていただいていますということは。説明会等のスケジュールについて、ご報告いたしましたけれども、ただ、これは、本意ということではなくて、やはり。","voiceIndex":45,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからもう一個、最後にこのテーマですけれども、取りあえずはそれぞれよく工夫されているかと思うのですけれども、これがずっと続くということなのか、運営の中でこのテーマについても例えば利用された方たちにもう少し次はこういうようなテーマも取り上げてほしいとか、そういう意見を出すような場面があるのか、運営事業者と協議するような場面があるのか、今後の運営について伺いたいと思います。","respondent":"提坂環境課長","answer":"令和４年４月以降に、開設するわけですけれども、それで実際に施設を利用した方のご意見、その辺ももちろん頂戴いたしますし、あと地球環境とか身近な環境というのは常に変化しているものですので、その辺のいろいろなタイムリーな企画というのを随時。","voiceIndex":49,"id":"exchange-020"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"分かりました。３階の平面図、当初案だと、例えば階段はダブルスキン階段になっていたのです。今度はそれが直階段になったということと、あと、以前は多機能トイレがあったのですけれども、今回はトイレが２つ。これはやはり設計上のいろいろな事情があるかと思うのですけれども、この自然換気、吹き抜けではなくなったということでよろしいのですか。","respondent":"提坂環境課長","answer":"すみません、そこら辺は私、勉強不足で申し訳ないのですけれども、前回の説明と違うということであれば、その辺は設計が変わったと思うのですが、安全管理とかその辺の問題で、屋上にあった施設を一部３階に下ろしたとかそういうところがあるとは聞いてあります。","voiceIndex":53,"id":"exchange-021"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"では最後に、この３階の平面図で、当初は展望テラスになっていたのです。今回は菜園があるということで、別紙の４番目、開設準備の中の、樹木を活用した工作やクイズとか、そういうのを何か取り入れた菜園になるということでよろしいのでしょうか。","respondent":"提坂環境課長","answer":"菜園については当初、屋上に計画というか予定があったのですが、先ほど申し上げた理由によって、屋上に設置するのは難しいということで３階に下ろしております。平面図を見ていただくと、その横に緑に親しむ新緑デッキということで、こちらを計画させていただいているところです。","voiceIndex":55,"id":"exchange-022"}]},{"id":"topic-05","title":"に戻りまして、建設委員会所管にかかる新型コロナウイルス感染症の対応","agenda":"に戻りまして、建設委員会所管にかかる新型コロナウイルス感染症の対応","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"都民住宅も今、同様に減免等について検討されているということを伺っているのですが、区営および区民住宅は、この４月、５月という２カ月ではなくて、もう少しそういった実態も踏まえながら、まだこれからそういうお話が出てくるのかもしれませんけれども、場合によってはもう少し長くしていただく。最低でも都営住宅、また都民住宅等に合わせていくみたいな形。","respondent":"森住宅課長","answer":"猶予期間が４月、５月分ですけれども、この猶予を始めたのは、４月の半ば頃に検討を進めまして、その頃には緊急事態宣言はまだゴールデンウイーク明けまでというところもございましたので、一応５月ということで切らせていただいたところですが、５月あるいは６月分、７月分。","voiceIndex":61,"id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問","question":"期間については、状況を踏まえながら臨機応変に対応していただけるということで伺いましたのでよかったのですけれども、減免についてはなかなか今のところというお話でしたが、都営また都民住宅等も行う予定と聞いています。そういった制度があるのですけれども、使えないとすると、たしか半年後、１年後ですか、分割で分納していかなければいけないと。","respondent":"森住宅課長","answer":"実際、今、分納していただいている方の中にも、住居確保給付金と今の分納の制度ということで両方使っていただいている方もおられますので、特に区営の方につきましては、設定した家賃から様々な家庭の状況、収入の状況に応じて減額をして。","voiceIndex":63,"id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。ぜひそういった情報をもう一回、積極的に、特に区営の指定管理者と、区民住宅の指定管理者は違いますし、またその間で情報の格差というか、そういったものがあってもいけませんので、必要とされる方がしっかりと情報に触れられるように、今の住居確保給付金についても併せてしっかり周知していただきたいと思います。要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"２番の実際に自転車等駐車場の使用料の返還を申し出た方ですか、申請者数を、見込み数でもいいのですけれども、伺いたいと思います。３番目についても、実績というのですか、申請はどれぐらいあるのか、あるいは見込んでいるのか伺いたいと思います。","respondent":"川口交通安全担当課長、稲田土木管理課長","answer":"試算では現在のところ１００％で還付した場合だと、おおむね８５１万４,３００円というところです。なお、現在までですけれども、昨日現在で今のところ５４人の方が返還の申請に来ているところです。３番の占用料の納付期限の猶予なのですけれども、現在、これで猶予しているという物件はございません。","voiceIndex":70,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"それと、６番目でしながわ水族館あるいは区民公園内にはプレーパークなどもありますし、あるいはしながわ防災体験館も閉じていますけれども、それぞれ休止中の業務にあたっていた従業員の方の実態というのですか、雇用、賃金、あるいは実際、働いているのかとか、そこら辺の状況について伺わせてください。","respondent":"高梨公園課長","answer":"ただ、委託業者のほうも様々な自粛要請を受けて、やはり縮小体制での委託業務といった形で、人員を一部縮小してやるといったような業務も出ていますが、ただ、公園につきましては、遊具の周りで多くのお子さんが遊んでいるというような時期もございましたので。","voiceIndex":73,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"最後のところでもう少し伺いたいのですけれども、例えばしながわ水族館は指定管理でしたか、業務委託の管理料みたいなのは、事前にまとめて払うわけですけれども、実際に館は休止しているわけですが、とはいっても動物の世話というお仕事もありますので、それで実際、仕事をしておられて、きちんと賃金が払われているのかというところを伺ったのです。","respondent":"高梨公園課長","answer":"プレーパークのほうは、ＮＰＯ法人のほうに委託しているわけなのですけれども、ほかの委託もそうなのですが、基本的に１月これだけの仕事をやったから幾ら払うというような単価物については、縮小しているので、今月の支払金額は少なくなるというところもありますが、ただ。","voiceIndex":75,"id":"exchange-028"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。シャチハタは不可ですとなっています。この辺りは、端的に言ったら国が全然、進んでいないとは思うのですけれども、まずうちの区から、各所管のところから、手書きでやるのだったら別に印鑑はなくてもいいというふうな処理はできないのかと思うのですけれども、そこはいかがでしょうか。","respondent":"川口交通安全担当課長","answer":"今後、何かそのようなＯＡ化というかオンライン化でできるものがございましたら、また検討させていただきたいと考えております。","voiceIndex":77,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"印鑑のところはどうですか。口座振替のほうは、これは金融機関が絡むのでしょうがないと思うのです。ただ、請求書というか、申請書兼請求書のところとか、この辺りから、本当に細かくて申し訳ないのですけれども、ここぐらいだったら印鑑は要らないのではないかと思うのですけれども、いかがですか。","respondent":"川口交通安全担当課長","answer":"そちらの部分につきましても、印鑑の必要性につきまして今後、検討させていただければと考えています。","voiceIndex":79,"id":"exchange-030"},{"speaker":"松本委員","kind":"質問","question":"加えて、これはＰＤＦで上げていただいているのですけれども、私も最近、字を書くのが苦手になってきて、還付の理由とかも手書きでと書かれているかと思うのですが、例えばこれをワードやエクセルで上げていただくとか、そういったことも今後できればと思うのですけれども、いかがでしょうか。","respondent":"川口交通安全担当課長","answer":"様式等につきましては、ＰＤＦで上げさせていただいたところですけれども、今後、もしワード等の様式で、どうしても手書きが必要な部分というところはしょうがないのですけれども、それ以外で可能な部分につきましては、そのような様式でできればとも考えております。","voiceIndex":81,"id":"exchange-031"},{"speaker":"たけうち委員","kind":"意見","question":"そもそも知っていらっしゃるかどうかというところです。それから、５月３１日までの予定となっていますけれども、例えば緊急事態宣言等が延長された場合、そういったことを基準にして、もう少しやるのかどうなのか。所管するところで結構なのですけれども、橋以外に、例えば同様の趣旨でそういう感謝の意を表するような取り組みを何か今後、考えられているのかどうか、この３点をお聞かせください。","respondent":"松本河川下水道課長","answer":"期間ですが、一応、今、５月３１日までということで予定しています。こちらにつきましては、東京都も実施しておりまして、東京都の動向も踏まえまして今後、３１日以降、やっていくのかどうかにつきましては検討していきたいと思ってあります。","voiceIndex":83,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、１点だけ。でも今みたいに皆さんの感覚の中で、例えばシルバー人材センターにしても何にしても、大変だなというのがあるではないですか。例えば部の中とかそういうところで１回、そういう契約関係を部の中で対応しているではないですか。そういうところを１回こういうことにしようよという話を部でして、それを例えば経理課に上げようとか、そういう動きは部の中でないのですか。","respondent":"稲田土木管理課長","answer":"区全体とのバランスもありますから、経理課のほうにもそのようなことは上げていきながら、新型コロナウイルス感染症の対応としてできる部分をやっていきたいと考えているところです。","voiceIndex":85,"id":"exchange-033"}]},{"id":"topic-06","title":"スカイウォーク３号復旧工事","agenda":"スカイウォーク３号復旧工事","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"人身事故はなかったということでよいか、その確認をしたいのと、あと今回のケース、いろいろ原因等の説明もいただきましたけれども、ここに限らず、今後の事故防止対策に何か生かすようなところがあるのか、なかったのかというのをお伺いします。","respondent":"溝口道路課長","answer":"今回のケースですが、区内６９橋ありまして、そのうちの１１橋ほど、同じようにパネルで覆われた歩道橋、橋梁がありますので、そういったものを点検していく際には、今回の事故の原因等を踏まえた点検等を行いながら。","voiceIndex":91,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"本来であればもう少し気をつけてほしいと。それはたまたま工事現場だったので余計、これはたまたま当たらなかったからよかったよねで終わりかなということがあったので、その辺どうなのか、考え方だけ伺いたいと思います。","respondent":"溝口道路課長","answer":"もう一つ、天災の補償関係なのですけれども、これは非常に難しい部分もありまして、例えば街路樹などがありますので、その倒木に伴っては、やはり天災なので補償できないなどというのもケースとしてはあります。","voiceIndex":93,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"たまたまそのあった事例は、工事だったので、本当にヒヤリハットどころか、もうあと少しタイミングがずれていたら死亡事故だったのではないかというようなことがあっても、その情報がその次の予防対策に生かせているように思えなかったので、区が関わるところについては特に人身事故は起きなくても次の防止につなげるような情報収集というのを今後、検討していただきたいという意味で申し上げましたので。","respondent":"溝口道路課長","answer":"そういった中での情報共有ですとか、今後、新たな技術、そういったものの導入の検討、そういったものも併せて行っていくことによって、委員ご指摘の今後、事故を起こさないためにどのようにやっていくのかという取り組みにつながってくるものだと考えています。","voiceIndex":95,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、今の１億１,０００万円もそうだけれども、今後、架け替えという大きなことも出てくるのではないですか。スカイウォークは、いろいろなところがありますよね。大崎にもたくさんある。そういう部分のスカイウォークの再開発絡みの扱い方の橋梁というのはどういう契約が一番多いのか教えてください。","respondent":"溝口道路課長","answer":"いずれにしましても、管理者それぞれ分かれて、所有は完了後、分けておりますので、それぞれの責任において何か対応しなければいけないものは対応していかなければいけない。","voiceIndex":97,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"景観上はどうかというのもあるのだけれども、そうなると経年劣化の対応はどちらの責任でというと、それまで全部、区が管理しているのだから、区が持ちますという契約は契約でいいのだけれども、今後こういうことがあるなら、それはパネルのほうがきれいだし見た目もいいのだけれども、そういう経年劣化を考えるのであれば。","respondent":"溝口道路課長","answer":"ただ、委員ご指摘のように、やはり当初の段階から維持管理費用が今後かかるようなものをどう取り扱っていくのか、また、そういうものをどう今後、引き継いで管理していくのか、そこはしっかり当初から考えて、当初よりその契約を結んでいく。","voiceIndex":99,"id":"exchange-038"}]},{"id":"topic-07","title":"「品川区水とみどりの基本計画・行動計画」の改定","agenda":"「品川区水とみどりの基本計画・行動計画」の改定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"推進目的の重点です。それと併せて、資料の３の主な改定の流れというところで、７月から９月頃に水とみどりの課題の検討と、各種調査を踏まえてとありますけれども、現時点では区としてはどんな課題があると考えておられるのかも伺います。","respondent":"高梨公園課長","answer":"ただ、先ほど申しました啓発に加えて、あと壁面緑化であったり屋上緑化といったような技術革新も進んで、最初の頃は難しかった壁面であったり屋上といったところも一定程度、技術が進んで、その面積も調査によると増えてきていますので、そういったところも含めて。","voiceIndex":105,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"区の４分の１ということなのですが、何のために緑化を進めていきたいと考えているのかを、もう少し併せて、そもそものところなのですけれども、伺いたい。そして、これから、どういう施策でこの緑化推進を進めていこうと。その中心となる施策はどのようなことを考えているのかというのも伺います。","respondent":"高梨公園課長","answer":"みどりを増やす具体的な方策といったところですが、そういったところも含めて、今回、計画改定の中でいろいろとご議論いただいて、改定を進めていくといったところですが、私の考えといたしましては、１つ、先ほども申しましたとおり。","voiceIndex":107,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"ありがとうございました。公園というのはみどりに覆われていようが、いまいがオーケーということだったかと思いますけれども、やはり施策を進めるにあたり、このみどり率の数値というのを増やしていくということは当然必要だと思いますけれども、実際のみどりを増やすことも意識していただきたいと。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"護岸もなかなか簡単には整備できない。それはもちろん上位計画で港湾局との連携はどういうふうに図っていくのだと。それは品川でこうやってやっていこうと、前向きにやっていただけるのであれば、そういうことも含めて、ぜひ切り込んでほしいと思うのです。ここら辺のところだけは、ぜひ突っ込んで、せっかくやるのだから、いいものにしていただきたいと思うのだけれども、どうかというのだけ伺います。","respondent":"高梨公園課長","answer":"品川区の計画は、基本計画部分と行動計画、要するに各施策をもう少しブレークダウンして考えましょうといったところ、あと各地区別に、それぞれの地区に応じた水とみどりについて施策を考えていきましょうと行動計画部分に分かれておりますので。","voiceIndex":110,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり区民の皆さんの一人ひとりの行動と、区として大きく打ち出す政策と、それもいろいろ関係していかなければいけないということでは、計画を立てること自体はすごくいいことだと思うのですけれども、ぜひ区民の皆さんの具体的なイメージにつながるようなものをつくっていって、もちろん私たちも意見を言うべきなのでしょうけれども、つくっていっていただきたいのと。","respondent":"高梨公園課長","answer":"区民意見の聴取につきましては、パブリックコメントは素案策定後、やらせていただくのですが、やり方についてはこれから検討の中で決めていきますけれども、何か区民アンケートといったような形で、パブリックコメント以外にも区民の方からの意見を取るであるとか、あと。","voiceIndex":112,"id":"exchange-043"}]},{"id":"topic-08","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、大雨が降った場合、下水と雨水が合流して目黒川に放流されることによる水質悪化というような問題もありますけれども、この流域というのは既にそういった問題は解決されているところなのか、分離式になっているのか、今回の工事とそういった改善との関係があるのか、ないのかとか、そこら辺も併せてお伺いします。","respondent":"松本河川下水道課長","answer":"全体で３期に分けまして、古い管きょから順次、再構築を行っておりまして、アセットマネジメントの手法を用い、経済的耐用年数が８０年程度あるものについて再構築するということで、今、第１期の再構築を進めているところです。","voiceIndex":118,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"最後のところですけれども、もしこういう管を取り替える、新しくするという事業で、一度地面を掘るわけですけれども、そういう水質の問題などの課題があるのであれば、これを併せて行っていくというほうがいいのではないかと思うのですけれども、そういった工夫というのはできなかったのか、そこら辺については何か見解があれば伺わせてください。","respondent":"松本河川下水道課長","answer":"下水道は、東京都２３区ですと約１万６,０００キロの下水道管があります。このうち８割が合流式の下水道管になっておりまして、今、言われたように全て分流式に替えるということになると、莫大な費用がかかると考えています。","voiceIndex":120,"id":"exchange-045"},{"speaker":"たけうち委員","kind":"質問","question":"すみません、先ほど８０年云々、再構築とあったのですけれども、その８０年というのはどういう根拠なのかという。いわゆる古いところを替えていくので、おおむね何年ぐらいになったら工事を施していくのかということと、それを例えば管きょ更生ですか、この内面を樹脂で補強したときに、その後は大体、何年ぐらいもつのかという。それで先ほど８０年と言ったこととの考え方を整理して教えてください。","respondent":"松本河川下水道課長","answer":"ですので、まだ第１期を進めておりまして、この後、第２期、第３期ということで進めていくということになりますので、この法定耐用年数５０年に対して、東京都としては今８０年でやっておりますので、これを継続していくのかどうかということについては。","voiceIndex":122,"id":"exchange-046"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。そうすると、法定耐用年数の５０年になる前に、超寿命化というか、５０年近くなってしまって完全に取り替えなければいけなくなる前に、内面を補強することで３０年ぐらい長くもたせて、いわゆる経費を大幅に削減していきながら取り組んでいくと、こういうことでよろしいのでしょうか。","respondent":"松本河川下水道課長","answer":"今のお話のとおり、法定耐用年数の５０年より３０年程度、延命しまして、経済的耐用年数というものが８０年になるように、効率的に下水道管を整備していくです。","voiceIndex":124,"id":"exchange-047"}]},{"id":"topic-09","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"いろいろ延期の理由などをご説明いただいたのですけれども、トンネル施工時のトラブルというのは何があったのかというのと、あと到達防護工の見直しということで補助工法の追加ということですが、その前に、資料によると月見橋の家の仕様構造の変更に伴うとあるので、月見橋の家の仕様構造の変更のほうが理由のように見えるのですけれども、そこら辺について何かもう少し状況。","respondent":"松本河川下水道課長","answer":"それが損傷したトラブルです。２点目の月見橋の家の仕様構造の変更に伴う到達防護工の見直しによる補助工法の追加ですが、月見橋の家の復旧にあたっては、建物の基礎構造を検討しています。","voiceIndex":130,"id":"exchange-048"},{"speaker":"たけうち委員","kind":"質問","question":"これは記憶が正しいかどうかあれなのですけれども、たしか建設委員会で現地を視察したような気がするのです。それで、日本で初めてとか世界で初めてとか、工法がすごいというようなことを伺った記憶があるのです。私が委員長だったような気がするのですが、そうするとその工法が予定どおりいかなかったということなのか、分かれば教えてください。","respondent":"松本河川下水道課長","answer":"併せまして、高潮対策の樋門と排水機場の建設ですが、こちらもやはりこの工事が終わってからの施工となりますので、当初ですと令和３年度から進める予定だったものが、令和９年度の中ごろ以降からの施工となってしまうです。施工のことは、申し訳ございません。","voiceIndex":132,"id":"exchange-049"},{"speaker":"たけうち委員","kind":"意見","question":"今の課長のときではなかったのですが、何か初めての工法で、それを実際に建設委員会で視察に行った記憶があるのです。それは仕方がないのですが、ただ、いずれにしてもこんなに延びてしまっているのでどうしようもないのでしょうけれども、そこが分かれば。","respondent":"松本河川下水道課長","answer":"この工事のトラブルにつきましては先ほどご説明したように、シールドマシンの後方部にあるテールブラシが破損した影響での遅延ということもありますが、大きなものとしては、次の月見橋の家で造るマンホールの構造がやはり複雑になったと。","voiceIndex":134,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4290#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":46608,"voices":142}},{"id":"r02-20200519-9","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"文教委員会","time":"午後 １時００分～午後 ３時５７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"新型コロナウイルス感染症にかかる区立学校の対応と今後の教育活動の予定","agenda":"新型コロナウイルス感染症にかかる区立学校の対応と今後の教育活動の予定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"できる子、できない子というのがいて差が出ていると思いますので、それぞれの進捗状況に配慮した柔軟な対応をしていただきたいと思います。併せて、メンタル面でも不安定になっている子どももいると思うので、そういった面でも支援をしていただきたいと思いますけれども、伺います。されることがあるということは、されないこともあるのかという気がしますが、その点を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"もう一点、メンタル面につきましては、教育総合支援センターとしましても巡回相談、またはＨＥＡＲＴＳというような機関を活用しまして、個々に学校に、またこれまでも引き続いてつながっている保護者については、ご連絡を差し上げて対応しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"その点でもぜひ配慮をお願いしたいと思います。これまでも言ってきましたが、やはりそもそも私たちは必要ないということで中止を求めております。今現在のこの状況で実施することは、今年度は少なくとも中止をすべきだと思いますけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"この場合、区で統一する必要は全くなく、そういった中での実施をして学習に活かしていければと考えていますので、実施の方向で考えているです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"その進捗状況を見るという意味ではこの３月から５月、今年度はもう２か月進んでいないということですから、それは見られないのかなという気がするのです。やはり今、学校が授業時数を確保するのが大変というところで必要ないのでは、中止すべきではということで言っておりますけれども、学校がやれる段階でやっていくということは、やれないこともあるということでよろしいのでしょうか。","respondent":"工藤指導課長","answer":"いいえ。学校が再開後、速やかに行うということで指導はしておりますので、それは統一日を設けるということではなく、という意味です。ですので、全校で実施するというものです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"速やかに実施ということで、やはりこれは授業時間確保も含めて中止をすべきだと思います。少なくとも今年度は中止にすべきだと改めて強く要望しておきたいと思います。それと、今、住民団体の調査で、大学生がこの間授業が中止になって、５人に１人が退学を検討しているという調査が出ておりますが、区としてはそういったところをどのようにお考えになっているのか、支援なども含めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"品川区にも大学生がいるわけで、義務教育ではないですけれども、区としての考えというのは何かもっているのかというところでお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"１つ確認なのですけれども、ＩＣＴの活用ということに関連しまして、先日、東京都で区市町村立学校におけるオンライン学習等の環境整備に向けた緊急支援という補正予算が組まれて、区立の学校に対してＰＣ等の緊急貸出とか、そうした支援をやるということになったのですけれども、品川区はこの東京都の補正予算の活用ということは考えていらっしゃるのでしょうか。","respondent":"篠田学務課長","answer":"こちらに関しましては、区のほうで持っている機械というのがすべてセキュリティの関係で学校内でしか接続ができないというような仕様になっているものですから、すぐにそういったご家庭にお貸出しをすることはできないということで。","voiceIndex":23,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。補正予算は東京都がせっかく組んでいるものですので、使えるものはしっかりと使って、有効活用していっていただきたいと考えております。オンライン学習についてなのですけれども、今後も品川区としてはどのような方向でもって進めていくのか。具体的なその工程というか、学習方法が、今、分かれば、教えていただきたいのですけれども。","respondent":"篠田学務課長","answer":"ただ、何分急な話でございましたし、今まで区で整備している環境もありますので、そことの整合性をとりながらというのがどうしても必要になってまいりますので、そういったことを念頭に置いて、できるだけ早くきちんとした答えが出せるように、今、検討しています。","voiceIndex":25,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問・要望","question":"どうもありがとうあります。相対的な評価として、ほかのお子さんの進み具体とかも非常に気になっているかと思うのですけれども、今、教育委員会でやられている学習状況の成果の確認というのは、具体的にどのような形でやっているのか。ほかのご家庭との比較というか自分の位置づけといったことも情報提供されているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"横山委員","kind":"確認","question":"３点、お伺いします。この２番の表の定期健康診断のところなのですけれども、学校再開後実施予定ということで、こちらは新年度に毎年実施をしている内容でよろしいのでしょうか。時期は１学期中に行うということでよろしいのでしょうか。確認させてください。２点目なのですけれども、学校と児童・生徒、また保護者の双方向のコミュニケーションというところで様々な手法があるかと思うのです。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"私のほうで、１点目の定期健康診断に関してお答えをいたします。学校再開後実施予定となってございまして、まず内容ですけれども、通常ですと４月の段階で、学校で測定等がまずあって、その後、内科等の診断があります。今、国のほうでもそのような指示はしていますけれども、基本的には学校では説明とか発表とか協議というところで学習内容を充実させて、家庭のほうでは、今までのドリル学習も含め、思考力を高めるような投げかけを学校からして。","voiceIndex":31,"id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。ですので、何かちょっとしたきっかけといいますか、気軽に聞けるような双方向のコミュニケーションの機会というところを、ぜひこの機会にさらに充実させていっていただきたいということも要望させていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"もちろん感染拡大しないように防止をして、注意をしながらということはありますが、その点でどのような感染防止をしつつ、この校庭開放をするのかというところで、具体的なところを少しお伺いしたいと思います。それから、ＩＣＴの活用についてなのですが、品川わくわくスクールの放送を５月１１日からしていきますというところで、これは各家庭はどのような形で受信していらっしゃるのでしょうか。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"は学校で密にならないように、先生たちに付いていただいて、密を避けるというようなことに配慮しながら、校庭と学校図書館もそうですけれども、そのようなところに配慮しながら行っていきたいと考えております。You tubeでも配信できておりますので、それはもうほとんどのご家庭で、どのような形かはまた別として、見られるということが分かってありますので、そちらで見ていただこうと考えています。","voiceIndex":35,"id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"それで、先ほどもちょっと議論があったのですけれども、特にＩＣＴの都の補助金のところで、主に通信のインフラ的なところでお伺いしていきたいのです。要するに、今、家に普通にパソコンだとかタブレット、スマホがある、持っている家庭もほとんどだと思いますが、そういうものを使ってそういう授業をリモートでやると、それは補助の対象にはならないということなのかということの確認です。","respondent":"篠田学務課長","answer":"私どもはまた独自に機械のほうを今後充実させていきたいとは思っているところではあるのですけれども、委員ご指摘のとおり、機械の入手というのが極めて困難な状況でございまして、いわゆるメーカーに聞いても代理店に聞いても。","voiceIndex":38,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"東京都が押さえている機器を使わなくてもこの補助は出るということなのですか。そういう今ある環境をうまく活用するような形で、とにかく家庭と学校をつなぐオンライン環境というのを整備していく。要するに、家庭にあるものとか今ある簡易なモバイルルーターとか、そういうものを使いながら、双方向のやりとりができるようにするということについてのお考えはどうか、最後にお伺いします。","respondent":"篠田学務課長","answer":"その辺りをきちんと検証しながら、これから第２波、第３波が出てきたときにはきちんと対応できるような形、どういった形で対応できるのかということを検討してまいりたいと考えているところです。","voiceIndex":40,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問","question":"計画的学習のところで、学校からの時間割を示すということで、この時間割というのは、具体的にはどのような感じで書かれているのかというのをちょっとお聞きしたくて。そういったこともいつ起こるか分からないので、やはり準備はちょっと早めにしてほしいなというところがあります。教育委員会のほうで、全家庭の通信状況とかを把握するためのアンケートを取られたことはありますでしょうか。","respondent":"矢部教育総合支援センター長","answer":"２点について答えします。時間割につきましては、小学生がよくもらう国語・算数・理科・社会のイメージかと思います。そこに時間が書いてありまして、学校によっては始まる時間だけ書いてあって、できたらもう終わりというところもあります。","voiceIndex":42,"id":"exchange-014"},{"speaker":"せお委員","kind":"意見","question":"保護者の方からの声で、学校によって時間割も違う、課題も違う。電話がかかってくるところ、頻繁にかけてくれるところもあれば、かかってこない学校もあるという感じで、ちょっと対応のばらつきがあるようなので、好事例とか、“ここの学校はこういうことをしていてすごくいいですよ”とか、今、校長会とかで共有していたりといったことはありますか。","respondent":"矢部教育総合支援センター長","answer":"特にホームページにつきましては、各学校長へ充実に向けて何度も働きかけてあります。校長会の折には子どもたちへのメッセージを寄せ書きのようにしている学校もあるとか、そういった事例について話をしまして、各学校それぞれの取組の工夫を促しています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それを１つ確認。３つ目は、これは東京都の仕組みで、公立学校、高校とかに体温感知器を全校で配置できるような予算立て、５月２７日に議会が開かれれば成り立つので、区立小・中学校にも２分の１でしょうか、補助が出るというお話があるみたいなのですけれども、その点についてもし対応できるようでしたらどうするのかということ、対応するかどうか考えていらっしゃるのかという辺りです。","respondent":"矢部教育総合支援センター長、篠田学務課長、工藤指導課長","answer":"部活についても、今、検討中ですが、校庭開放等が進めば少しずつできないかなと考えています。ただその中で、もちろん引き続きそういったものを整備していくというのは必要なことだと思っていますので、対応を考えていきたいという中では。これから分散登校等で時間割を組む際にも、やはり講師の方を最大限活用しながら。","voiceIndex":47,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうあります。それから、体温感知器はそういった状況ですので、今、何とか活用できるように調査して進めていただいて。品薄だから厳しいのかもしれませんが、お願いします。特別支援教室のほうは、通常ほどの回数は難しいかもしれませんが、開始していくということでよろしいのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"その予定です。","voiceIndex":51,"id":"exchange-017"},{"speaker":"芹澤副委員長","kind":"質問","question":"１点だけお伺いしたいです。結局、保護者の方々、教育委員会の皆さん、校長、教員も基本的には同じゴールを見ているかとは思うのですが、そこの熱量の行き違いというか、届かなかったことで「品川区の教育は…」と思っている方も一部いらっしゃるかと思うのです。そういった方々に対しての今後のアプローチというのは、何かお考えはあるのでしょうか。","respondent":"有馬庶務課長","answer":"それで、この間幾度となく校長会も開きまして、そういった意味でやっていることがちゃんと伝わらないと、結局何も意味がないことになってしまうので、ここはしっかりと発信力を大事に、伝わるようにやっていきましょうということで５月の初めにも取り組んだところです。","voiceIndex":53,"id":"exchange-018"},{"speaker":"芹澤副委員長","kind":"意見","question":"これからいろいろ頑張るということで、施策ももちろんそうですし、思いというか、取組だけではない部分というのもぜひ保護者の皆さんに伝えていただいて、ゴールを共有しながらこの災害を乗り越えられればと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-019"}]},{"id":"topic-02","title":"令和２年度新入学学校別増減要因一覧","agenda":"令和２年度新入学学校別増減要因一覧","exchanges":[{"speaker":"せお委員","kind":"質問","question":"私が知識がなくて申し訳ないのですが、単純にちょっと１点お聞きしたいのです。浜川小学校と浜川中学校の減要因の希望実数がすごく多いのですけれども、これは何か原因があるのでしょうか。","respondent":"篠田学務課長","answer":"浜川小学校につきましては、現在改築が始まっているという状況があります。特に浜川小学校の場合は改築期間がかなり長くなることが見込まれてございまして、言ってみれば１年生で入りますと、卒業近くまでずっと工事をしているというような状況になってしまう可能性があると。","voiceIndex":62,"id":"exchange-020"}]},{"id":"topic-03","title":"子どもの食の支援事業","agenda":"子どもの食の支援事業","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"この令和元年度の寄付金が、当初の目標３００万円を大きく上回りまして５５７万３,０７３円ということで、とてもよい結果に終わったわけですけれども、そのうちの１００万円は子ども食堂のほうの子ども応援基金に寄付しましたと。もう一つ、事業としてはこの２５８世帯への食品の配送があるわけですけれども、その５５７万３,０７３円の内訳として、この二つ以外に支出した部分があれば教えてください。","respondent":"三ッ橋子育て応援課長","answer":"子ども食堂の子ども応援基金に１００万円、それ以外はしあわせ食卓事業にその残額を、となっております。","voiceIndex":70,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。福井県産のお米をひとり親家庭に配送ということですけれども、これは、対象者が２５８世帯の前回しあわせ食卓事業で食品の配送を受けた家庭と、新たにひとり親家庭等医療証を受給した配送を希望する家庭、および子ども食堂ということですけれども、このお知らせはどのような形で行くのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"基準日以降に、またその対象となる方に対して、約９０世帯分、同様にお知らせをいたしまして、その中で食の支援が必要だという方が電子申請して、その方に対してお米を配送するという形になっております。","voiceIndex":72,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"対象が新たに９０世帯というところでしたから、今の２５８世帯足す９０世帯で、上限３６７世帯までには十分あるということで、若干余分があるというところですけれども、余ったりした場合はどうするのですか。","respondent":"三ッ橋子育て応援課長","answer":"今回、詳細にはお伝えしておりませんでしたけれども、この９０世帯の中で、ご希望があった方は６２世帯でございました。つまり、しあわせ食卓事業としては３２０世帯になるのですけれども、それ以外の部分に関しては子ども食堂へと考えております。","voiceIndex":74,"id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"今回、目標金額を大きく上回っていたりですとか、坂井市のプロジェクトも１か月で目標を達成したということで、すばらしい成果を上げていると考えています。そこでちょっとお伺いしていきたいのですけれども、子ども食堂の継続支援というところで、「子ども応援基金が増え、運営者の負担を軽減した」と資料にあるのですけれども、こちらは具体的にどのような形で負担の軽減が図られているのか。","respondent":"三ッ橋子育て応援課長","answer":"子ども食堂の負担軽減を具体的にですが、今までは上限５万円の助成金と言いますか、子ども応援基金からしながわ子ども食堂ネットワークを通じて各子ども食堂に実施しておりまして、それは年間５万円だったのですけれども、今回、１００万円を子ども応援基金に投入したことで。","voiceIndex":76,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"福井県坂井市産のお米をひとり親家庭等を中心に配送ということで、先ほども質問が出たのですけれども、上限３６７世帯ということで、この上限をこうした数にしたという根拠は。お米の数とかそういうことがあると思うのですけれども、どうして上限３６７世帯にしたのかというところをお知らせください。","respondent":"三ッ橋子育て応援課長","answer":"その中でたくさん寄付が入ったことによって、３００世帯以上の部分について、３６７世帯というふうになりました。そちらが上限よりも上がったこの３６７という結果となっているところです。","voiceIndex":78,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"確認","question":"今ここで頂いている３枚のこの資料は、この委員会のためのものなのですけれども、どなたかに配るものなのですかということが一つ。１,５００世帯のうち、逆に言えば約２６０世帯の方しか希望されなかったのですが、その辺りについてはどのようにお考えでしょうか。それからあと、単純に考えると配送料とかがかかるので、１世帯当たり５,０００円とかそれに近い金額なのでしょうか。お願いします。","respondent":"三ッ橋子育て応援課長","answer":"１,５００世帯の中の２５８世帯ということで、確かに委員がおっしゃるように、若干パーセンテージがどうかなという部分がありますが、私どもといたしましては、まず一番最初の段階ですけれども、まずは子どもの食の支援が必要な方が申し込まれたと捉えております。","voiceIndex":80,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。それと、１,５００世帯には本当にいろいろなご事情があると思うのですけれども、こういういい感じでアンケートの内容などもありますので、できるだけそういうのをお伝えして、申し込みやすいように。何に幾ら使ったみたいな、そういったいろいろな決算報告みたいなのは、どこにどのような形で出されるのでしょうか。それだけ追加で、すみません。","respondent":"三ッ橋子育て応援課長","answer":"今回につきましては特に詳細についてはご報告しておりませんけれども、必要に応じてご報告していきたいと考えています。","voiceIndex":82,"id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。必要に応じてというのは、どこがどう必要だと思えばいいというのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"今、手元にある資料でお伝えいたしますと、例えば保管料、その食品を保管する金額とか、あと作業をする方法とか、あと梱包代など、また配送料についてもありますけれども、商品代は今のところ約３,０００円となっております。トータルしますと、１３８万円余となっております。","voiceIndex":84,"id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、数字は結構ですので、例えば、子ども応援基金のほうが幾つの子ども食堂にそれぞれ合せて幾ら助成したとか、今お話があったような配送料がどうかというのを整理できた段階で、委員会か、何らかの形で公表していただければ。今はもう数字は結構ですので、お願いしたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"今、お伝えしましたように、１回目が１４０万円弱となっておりまして、あと２回目、３回目と、できましたらあと複数回と考えております。それがすべて終わった段階で全体を報告していきたいと思いますので、よろしくお願いいたします。","voiceIndex":86,"id":"exchange-029"},{"speaker":"新妻委員長","kind":"質問・要望","question":"ほかにいかがでしょうか。よろしいですか。すみません、私から１点お伺いします。第１回目の３月実施のときももう影響は出ていたのかもしれませんけれども、もう少し前に手を挙げていた方かなと思われますので。今回、もしこの上限に達していく、さらに申込者が多かったという場合の、漏れてしまった方々への次の支援策というのが、何かお考えがあるのかということをお聞かせいただきたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"令和２年度のガバメントクラウドファンディングにつきましても、一番最初から周知して全体として募集はしてまいります。","voiceIndex":88,"id":"exchange-030"}]},{"id":"topic-04","title":"令和２年４月入園申込状況等","agenda":"令和２年４月入園申込状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"不承諾者について伺いたいです。一次の発表では１,５９１人だったと思いますが、今は１,１７５人ということで表には書いてあります。この減った理由を伺いたいと思います。この不承諾数１,１７５人から待機児童数は１３人ということで、ここも激減しているわけですけれども、このほかの子どもたちというのはどうなったのか。この不承諾数から先の内訳を伺いたいと思います。","respondent":"若生保育支援課長","answer":"１,１７５人から１３人を引くと１,１６２人になるのですけれども、内訳としましては、現在在園中で転園を希望されている方が１８６人、それから求職活動をされていたのをやめた方が９２人、それから認可以外の保育施設、認証保育所ですとか。","voiceIndex":95,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"２歳児の子どもが不承諾２３５人で、待機児童数が１０人ということで、今回、２歳児が多くなったのはなぜなのか、区で分析しているところを伺いたいと思います。今回、東大井・八潮地区で９人ということで多くの方が待機児童になっているわけですけれども、この３年余り、この地域の待機児童数が多いのです。その理由と、今後の対策が必要になってくるのではないかと思いますけれども、いかがでしょうか。","respondent":"若生保育支援課長","answer":"今年度開設したところですけれども、今、事業者からも幾つか提案を頂いてありますので、区としてもなるべくエリアごとで充足できるような形で努力してまいりたいと考えております。","voiceIndex":97,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回２歳児が多いというところは、まだ理由が明確に分かっていないということでした。今まで３歳児の待機児童というのが区の発表の数字としては基本的になかったと思うのですけれども、今回出てきたというところで、また少し状況が変わっているのかなと思うのですが、「３歳の壁」が強まっているというのか、何と言っていいか分かりませんが、そこの区としてのお考えを伺えればと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"常々、区としても考えをお伝えしているところではありますけれども、待機児童数については申込者の０.３％ということで。そういったところから始めまして、今、私立が足りないようであれば区立でというようなお話も頂きましたが、まずは丁寧にご案内させていただいて。小規模園等も２歳までで、ただ、こちらについては連携園を確保している部分ですので、そこで連携をとって３歳に上がるというところで。","voiceIndex":99,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"区が発表している待機児童数でも私たちは少なくないと思っていますので、やはり不承諾数に応じた枠を確保していくことが必要だと考えていますし、少なくともこの待機児童数というところでは解消していかなければいけないと思いますが、改めて答弁がありましたら、ぜひ伺いたいと思います。","respondent":"若生保育支援課長","answer":"問題意識のところで誤差という言い方をしてしまったのですけれども、当然、ご希望された園に入園できなかったという方が一定数いらっしゃるということは区としても十分重く受け止めまして、今後、こちらを限りなくゼロに近づけていくという努力はしてまいりたいと考えております。","voiceIndex":103,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"ゼロに近づけていくということで考えていくということでしたけれども、やはりゼロにするということが必要だと思います。この間の認可保育園の増設をしてきているというところは一定程度の評価はしておりますので、それも含めて待機児童ゼロとして、私たちが言っている隠れ待機児童もなくしていくということでやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-035"},{"speaker":"塚本委員","kind":"意見","question":"今までの質疑にも若干関わるのですけれども、待機児童が今年は１３人ということで表にしていただきました。地区別にも年齢別にもこの待機児童が出ていまして、それぞれ１歳児、２歳児、３歳児が品川地区、東大井・八潮地区、大井地区で出ているわけですけれども、次のページの地区別空き状況を見ると、一応それぞれ空いてはいるのですよね。そこのところについて、もう少し詳細なご説明を頂きたいと思います。","respondent":"立木保育課長","answer":"やはりいろいろなご希望が重なってしまいますと、先ほどの入所調整ではございませんけれども、指数の高い方からどんどん入園が決まっていくという中では、なかなかご希望に沿えない部分もありますので、そういったときに、例えば“空きがあるのですけれども。","voiceIndex":106,"id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"定期利用というのは、フレキシブルに必要なところに必要なだけ定員を、定期利用の枠を設けるということはできるのでしょうか。","respondent":"立木保育課長","answer":"定期利用に関しましては、やはり部屋の広さ等も必要ですので、ある程度余裕がある、例えば新規開設で入園者が少ないとか、年齢が高いほうが空いているのでその部分を使えるとか、そういったような諸所の条件がありますので。","voiceIndex":108,"id":"exchange-037"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、品川区に新規参入する事業者というのはいるのでしょうか。それと、今回、社会福祉法人が１事業者参入しておりますけれども、この間、株式会社が多くて、久しぶりなのかなと思うのですが、この参入した経緯を伺いたいと思います。ココファン・ナーサリー旗の台が認証保育所から認可保育園へと移行する経緯も伺いたいと思います。","respondent":"若生保育支援課長","answer":"そういったところで、認可化のための適地が見つかり、建てられる見込みができたというところでご提案を頂いて、区でも審査・検討させていただきまして、今回、開設の予定に至ったものです。","voiceIndex":115,"id":"exchange-038"},{"speaker":"のだて委員","kind":"提案","question":"区としても何か支援をしたのか。離職率等のところでは、ココファン・ナーサリーのほうが６２.３％ということで人件費がちょっと少なくて、離職率は同じでしたけれども、そういったところも含めて職員の入れ替わりが大きいのかなと思うので、今後そういった大規模な入れ替わりがないように、職員の方がしっかりと続けていける形で支援をしていただきたいと思いますが、いかがでしょうか。","respondent":"若生保育支援課長","answer":"大和社会福祉事業センターの経緯をもう少し詳しくというところで、私どもにご提案いただいて、話を進めてきたというような経緯以外で、どういう思いをもって品川区に来られたかというところにつきましては、やはり社会福祉法人ですので。","voiceIndex":117,"id":"exchange-039"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"保育園のことなのですが、今日の報告事項に直接関係ないのでここで伺うのですが、登園自粛になっている状況の中で勤務をされていない保育士たち、あるいは看護師といった方たちがいらっしゃると思うのですが、その方たちに対する賃金の仕組みはどのようになっているのでしょうか。私立保育園で結構です。区立保育園は当然全部（支給するもの）だと思いますので。","respondent":"若生保育支援課長","answer":"そういったところで、事業者としましては通常どおり、保育士等の従業員に給料を支払っていただくというのを原則として考えてありますので、区としましても、私立保育園等に給料等を減らすようなことはなるべくしないような形でお願いしますということで。","voiceIndex":122,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうなのですね。そうするとほかの９人の方々が休業になるわけですよね。あるいは、そういうことがもし仮に起きた場合、二重取りしているということと、もう一つは事業者が保育士たちに本来の給料ではなく６割しか支払わないようなことが分かった場合、今、要望でなるべくというお話だったので、なるべくではなくて、きちんと指導していっていただきたいと思うのですが、その点についていかがでしょうか。","respondent":"若生保育支援課長","answer":"こちらについては、区が指示してそれを強制するというところはちょっとできないものではありますが、当然、国・都からも指導が来ておりますし、通常、そこで運営費が減った分、給料を６割にするというような必要もございませんことから。","voiceIndex":124,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後にそういうお話をしていただいたので、そういった形で、事業者の方が休業している職員の方にしっかりと本来支払うべきものを支払うように、確認、チェック、指導していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"今、大学生の方がアルバイトもできない、授業もないということで大変な状況になっておりますけれども、大学の授業料無償化の運動をやっている団体が調査をしたところ、５人に１人が退学を検討しているという結果も出ておりまして、その点について、区として大学生の支援ですとかそういったことも含めてどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"今後とも連絡を取り合う際に確認をしてまいりたいと考えています。","voiceIndex":127,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"それはあったほうがいいですけれども、答えられる方はいないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません。さっき言い忘れていて申し訳ありません。それについて、現状、どのような形でフォローされているのかというところと、今後どうしていくのか。保育園・幼稚園にとっては非常に貴重な仕組みで、大変にいい方法で、皆様が助かっていたと思うのですが、ちょっとその点だけ確認させてください。","respondent":"立木保育課長","answer":"ご家庭のフォローに関しましては、やはり何かフォローが必要なご家庭に関しましては園のほうからきちんといたしますし、また保育課にご相談があれば、きちんとしかるべきところとやり取りをさせていただいた中でしっかりと対応させていただいているというような状況です。","voiceIndex":132,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":46132,"voices":137}},{"id":"r02-20200519-5","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"総務委員会","time":"午後 １時００分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そのためには、やはり検査の抜本的な強化、この視点なくしては感染拡大防止と経済活動再開の両立はし得ないと思うのですが、品川区では１２日からＰＣＲ検査センターを開設しておりますけれども、経済と感染拡大防止には検査が重要だと、こういう視点についてはどのようにお考えなのか伺いたいと思います。","respondent":"立川総務課長","answer":"昨週も３５件の検査申込みがあったということで、検査を受けたい方が検査をできる体制というのを身近な自治体において準備するということは、これからの経済の再開に向けて大変重要なことだと認識しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"先日の補正予算でも議論がありましたけれども、こうした直接支援をさらに強めていくことが急がれると思うのですが、その点についても伺いたいと思います。品川区も品川、荏原の医師会と関係をつくっておりますけれども、こうした医療機関への抜本的な財政支援というのが急がれているのではないかと思うのですけれども、併せて伺いたいと思います。","respondent":"立川総務課長","answer":"区といたしましては、医師会等へマスクや消毒液等、いわゆる側面支援ということを実施させていただいてあります。ご質問の直接支援ですが、こちらは各所管において必要な対策については検討を進めていく必要があるというふうに認識しています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"ＰＣＲ検査センターの開設について、先ほど３５件の申込みがあったということですが、その申込みの人数と検査人数は同じなのでしょうか。２．対応状況の（８）プレス対応のところで区立保育園の休園の決定があったのですけれど、この休園についても、これまでの品川区は区立保育園の園名は公表しないということだったのですけれど、これからもその姿勢なのかというところを伺いたいです。","respondent":"立川総務課長","answer":"ＰＣＲ検査センターのご質問につきましては、厚生委員会が所管ですので、回答は控えします。保育園の休園に関する園名の公表につきましては、感染された方、また周辺にいらっしゃる方のプライバシー等を配慮して、公表しないという方針です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"特にＰＣＲ検査センターをせっかく品川区で開設したのですから、品川区内の発生状況、今は東京都のホームページに行かないと分からないではないですか。せめてそれぐらいでも確認できるように、区民の方たちが注意をできるように、もうちょっと公表に向けて要望したいと思いますがお考えを伺えたらと思います。","respondent":"立川総務課長","answer":"感染者数の公表につきましては、東京都のホームページに毎日最新の情報が載っておりまして、品川区のホームページにおきましても、そこのリンクを張らせていただいておりますので、人数の確認についてはできる状況です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"とにかく、品川区の状況を区民の方がすぐに分かるように促してほしいという意味で質問をしています。ぜひ、そういった部分の公表をしてほしいなと要望したいと思います。学校とはちょっと違うのですけれど、品川区全体として、区有施設等の再開の目処はどのように考えられているのかなといった現在の状況についてお伺いできればと思います。","respondent":"立川総務課長","answer":"緊急事態宣言が解除された後の対応ですけれども、区といたしましては、現状の施設や事業について、いわゆる一遍に開くとかということではなくて、段階を踏んで徐々に開くといった方向で、今検討している状況です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"再開に向けての検討が始まっているのは分かりました。第２波、第３波が来たときに、縮小だったり閉館だったりしていくと思うのですけれど、そのときの基準となるものというのが今、区としてつくられているのかという部分をお知らせください。","respondent":"立川総務課長","answer":"国の基本的な対処方針ですとか、東京都の方針ですとか、その辺を勘案いたしまして、区としての方向というのを決めていく必要があるというふうに考えているところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"新型コロナウイルス感染症についてはいろいろあるので、１つ簡単に確認なのですが、先週、施設の開館の状況ということで、品川区のホームページなどで情報をもらうような形になって、そこに張りつけてあったリンクが、１５日、全然違うページへのリンクだったのです。","respondent":"大澤広報広聴課長","answer":"申し訳ございません。リンクするページを誤って張ってしまいました。今後、このようなことがないよう、細心の注意を払って周知していきたいと思います。","voiceIndex":19,"id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"いろいろ、手違いはあるかと思いますが、確認のほど、よろしくお願いします。東京都は非常に難しいといいつつも、経済を動かしていかなければいけないという状況の中で、今後どういう動きをしていくのか。もし縛りがないのなら、地域のことを知っているのは品川区なわけだから、独自でいろいろ、実情に合わせた解除方法、対策というものも必要なのかなと思うのですがいかがですか。","respondent":"立川総務課長","answer":"基本的には国の対処方針であるとか宣言であるとか、そういったものをベースに、各都道府県知事が、その自治体ごとの対応というのを検討していく。区といたしましては、施設やイベント事業等について、どういうふうに運営していくのか。","voiceIndex":21,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"この間、自粛をするに至っても、国と東京都で意見の相違が出てきた部分もありますよね。どちらかというと東京都のほうがきつい自粛の方法。どうしていくのか、具体的な行動提起をするのが東京都だと思うのですが、では品川区の権限はないのか、品川区は何ができるのかというところはいかがなのでしょうか。","respondent":"立川総務課長","answer":"品川区としましては、先ほどもお話しさせていただいたとおり、国の基本方針であるとか、東京都の要請であるとか、そういったものを全て勘案して判断していく必要があるというふうに考えているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"そうなってくると、例えば東京都がここはまだまだ自粛をお願いしなければいけないところだといいつつも、いや、品川区は大丈夫ですよ、というところがあった場合には、意見の相違が出てくる部分であって、そうなってくると、東京都が駄目と言ったから駄目というふうな判断になってしまうのか、いや、品川区はこういう対策を取っていくから独自でやるよというところが言えるのか、その関係はどうですか。","respondent":"立川総務課長","answer":"例えば飲食店の営業規制でありますとか、また区民の皆様への外出の自粛要請であるとか、こういったものにつきましては東京都全体で統一的にやるべきものだというふうに考えております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"大体同じようなご答弁なので、これから先、宣言が解除されてきて、どんどん緩和されてくる。なので、しっかり守っていくのは当たり前だし、品川区の職員の方々、それぞれの分野において一生懸命やっていただいているのはよく分かるのですが、それだけでは今後済まないのではないですかということを、ちょっと強く言わせていただきたいなと思いますので、ご検討のほどよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"区のほうとして、今後どういうふうに考えているのかをちょっとお聞きしたいのですが、我々も様々、医療関係者、学者の方、専門家の方から意見を聞いていますと、今の新型コロナウイルス感染症のワクチンができて、それぞれ国民の６割、７割の方が抗体を得るまでは早くても２年以上、遅ければ４年も５年もかかるという話を聞いています。そして、高齢者に至っては全く外に出られない。そして、企業もそうです。","respondent":"立川総務課長","answer":"こういった感染症に関する対策の基本的な方針というのは、大きく分けて、感染拡大を可能な限り抑制し、区民の生命および健康を保護するということと、もう一つ、区民生活および経済活動に及ぼす影響を最小限にするという、これが２大方針というか基本的な対策の目的ですので。","voiceIndex":28,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"半年でなくす、１年でなくすわけにいかないではないですか。まちはまちで何とか残していくように、それで自粛もある程度、どの辺までやれるか分からないですけれど、皆さんが生活できて、まちの中に明るさも戻して、そして一緒に共存していくんだよ、というような、そういう環境をもって、まちが沈まないように、続けられるように、区として身近な自治体として、やってほしいと思うのです。","respondent":"立川総務課長","answer":"委員にご指摘いただいた、やはり新型コロナウイルス感染症と一緒に生きていくといった社会をこれから形成していく必要があるというふうに考えておりますので、区としてどういったことができるのかというのは検討を進めていく必要があるというふうに考えているところです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"小芝委員","kind":"質問","question":"ホームページの件でお聞きします。これは何か、限定している理由は、いろいろとありますけれども、教えていただければと思います。","respondent":"島袋人権啓発課長","answer":"リンクを張るなど、都のホームページに飛ぶようにご案内しています点と、人権啓発課のページに入っていただきますと、医療従事者の方に対する差別に関するところにも飛ぶようにできておりますので、今後も検討させていただきたい課題だと考えているところです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"小芝委員","kind":"質問","question":"そういった店に対する、ツイッターではよく、自粛警察という言葉が飛び交っていますけれども、そういう形で、例えばお店のシャッターに落書きをされたとか、電話で誹謗中傷を受けたとか、そういう例も報道レベルでは僕も知ってはいるのですけれども、品川区で実際にそういった例というのは今まであったのでしょうか。","respondent":"島袋人権啓発課長","answer":"人権啓発課のほうに頂く問合せ等ではこのような件はございませんでした。","voiceIndex":34,"id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれど、品川区ＰＣＲ検査センターのさっき聞いたご質問の中で、開設からの検査人数や陽性者の人数、搬送方法などは厚生委員会での議論ということだったのですけれど、この検査状況については、これから品川区のホームページでの情報提供というのを考えているのかどうかという部分を確認したいと思います。","respondent":"立川総務課長","answer":"所管に聞いた話では、検査状況の公表というのは特に考えていないです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"そこで搬送方法については書かれてなく、入院となってしまっている部分は、どうやって病院まで行くのかというところを、情報提供として欲しいなと思うので、そこの部分を改善していただきたいというのと、やはり区内の状況、先ほども話しましたけれど、せっかくＰＣＲ検査センターを持ったのですから、品川区での状況というのは公表されるべきだと思うので、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"新型コロナウイルス感染症に関しての質問がいっぱいあると思うのですけれど、それをホームページのほうで書いてあるところはないのでしたか。例えば広報広聴課などにいろいろと区民からの声があって、質問がいろいろと出てくると思うのですけれど、新型コロナウイルス感染症に関してまとめたものというのはなかったのでしたか。","respondent":"大澤広報広聴課長","answer":"一般的なＱ＆Ａは各ページに載っている場合もあるのですけれども、まとめてというのは今のところ、ページとしては作っていません。","voiceIndex":39,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"新型コロナウイルス感染症に対しての質問はどこが集約しているのですか。それぞれの所管になるのですか。","respondent":"立川総務課長","answer":"その他の、例えば防災行政無線の音がうるさいだとか、よく聞こえないだとか、最近よく聞こえるようになったとか、そういったご意見については総務課のほうで承っているところです。","voiceIndex":41,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"今後緊急にやってほしいのです。やはり新型コロナウイルス感染症に関して、何か問合せをする前にちょっと調べようかなとお思いになると思うのです。それをまず、どこに聞いたらいいか分からないというのがあって、取りあえずこのＱ＆Ａというところから入ってくるというふうにしてあげると、つながりやすいかなと思うので、それの検討を早急にお願いしたいと思いますがいかがですか。","respondent":"大澤広報広聴課長","answer":"前向きに検討します。","voiceIndex":43,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろとお話を聞いた後にすみません。いろいろ分かったことがありましたので、ちょっと確認だけさせていただければと思うのですが、新型コロナウイルス感染症の連絡会議ではなくて、対策本部が以前設置されて、４回までは報告を伺って、現状はどういうふうになっているのか、その状況について教えていただきたいと思います。","respondent":"立川総務課長","answer":"対策本部につきましては、２月３日に設置しまして、そこから対策本部会議というのを開催しておりまして、直近ですが、第１２回の対策本部会議というのが昨日５月１８日、実施されたところです。","voiceIndex":45,"id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。もう１２回やられていて、いろいろなところから情報を取りながら、その情報を基に今後の区政運営と各部署の対応について話し合いながら進めていくということで分かりましたので、ありがとうあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-022"}]},{"id":"topic-02","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"田中委員","kind":"質問","question":"工事工程なのですけれど、現在の予定だと令和３年度末、変更後は令和９年の中頃で、差が６年間もあってとても大きいなと思ったのですけれど、もう全部変わってしまったような、イメージとしてどういう感じなのですか。私も工事が全然分からないので、イメージが湧かないのですけれど、こんなに変わることというのはあるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"これ、予算はどうなっていくのか。多分、総務委員会に関係するところだとお金の話だと思うのですけれど、これはもう全く関係なく、ただ単に工事が延びましたという、東京都からの報告を受けたので、それにまつわる予算であったりとか、品川区に対しての、そういう出る出ない、いろいろなものがあると思うのですけれど、もう関係ないですよ、という認識でよろしいですか。","respondent":"島袋人権啓発課長","answer":"確かに都の工事ですので、予算に関しましては東京都のほうが責任を持って進めるということを伺っております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"そうすると、予算書や決算書などにこれも入ってきますよ、という認識でよろしいのですか。","respondent":"島袋人権啓発課長","answer":"こちら、全て東京都の持ちですので、区の予算書の中にはこの項目は入ってこないと考えております。","voiceIndex":57,"id":"exchange-025"}]},{"id":"topic-03","title":"スカイウォーク３号復旧工事請負契約","agenda":"スカイウォーク３号復旧工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、台風１５号の被害を受けたということですが、どういうふうにして壊れたのか、こういうふうになって壊れたのですよというのと、もし簡単に壊れるようなものでなければ、例えば台風でよほどひどい、何かぶつかってどうかしたのか分からないのですが、そうでなければ、施工の問題というのもあるように感じたのですが、その辺について分かる範囲で教えてください。","respondent":"東野経理課長","answer":"特に施工上の問題ではないというふうに聞いております。","voiceIndex":63,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"私の見解では、スカイウォークの上も全部屋根が架かっていて、塞いであったので、あれで腐食するというのはちょっとなかなか、一般的には考えられない状況で、そこでパネルが簡単に落ちるというのは、どうしても我々が見る限りでは、どこかやはり、施工が悪いように感じたのです。それでちょっと質問させていただきました。は中身までちょっと分からないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"契約の相手側なのですけれど、今回江東区の企業になっているのです。制限付き一般競争入札という形になっていて、別に品川区でなければいけないとは思っていませんが、今回、金額だけでこうなったのですが、今までだと、品川区の事業者が多かったかなと思っていて、今回広げての入札だったのか、その辺の経緯はいかがですか。","respondent":"東野経理課長","answer":"委員からもご案内ありましたとおり、制限付き一般競争入札でございまして、こちらにつきましては、公告している入札参加資格、それから入札参加条件に一致しているという業者になります。ですから、品川区以外の業者もこれについて入ることができる、そういう案件です。","voiceIndex":66,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"品川区外の事業者がここに加わることができる条件というのは、例えばどういう条件だと入れるのですか。","respondent":"東野経理課長","answer":"品川区の業者に限るというふうに記載しているものでなければ、品川区外の業者でも入ることができます。","voiceIndex":68,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"それは分かるのですけれど、今までは結構品川区の業者が多かったのかなと思っているのですが、品川区内のということを外すことのできるケースと、外せないケースというのはあるのですか。","respondent":"東野経理課長","answer":"それぞれの案件によりまして、判断しています。品川区の施工業者だけですと、この入札に呼ぶ対象が絞られるとか、そういうものになりますと、品川区外の業者も入れるということも想定しています。","voiceIndex":70,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ただ、それでもなかなか難しいだろうということがあって、私はどうしても品川区にという固執をしているわけではなくて、事業者のいろいろな特徴があると思うのです。なので、枠を広げてもいいのではないか。私の印象だと、品川区の事業者、というのが強かったかなという思いがあるので、その辺はいかがですか。","respondent":"東野経理課長","answer":"今回の工事に限りましては、やはり一般的なところというよりも、少し特殊な工事という部分もありますので、そこは対象を広げて公告をしたというような状況です。","voiceIndex":72,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"なので、いろいろな需要があるときに品川区の中では技術面も含めて難しいだろう、だからこの件についてはもうちょっと広げてみるというような判断の基、入札という形でしているのかなという認識はしたのですが、ではその品川区の事業者はどこまで力があるものかというのは、これは所管が違うと思うのですけれど、ある程度は把握をしていて。","respondent":"東野経理課長","answer":"ですので、それを全部区外まで広げるか広げないかという判断につきましては、その工事に対してほかのところでの実績があるかといった部分で結果のほうで判断していくです。","voiceIndex":74,"id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"最後に、品川区内、区外を問わず、いい施工をしてほしいというのがあります。なので、私の考え方は、品川区内というように限定するのではなくて、広くいい施工をするところを、こういう入札などについてはある程度広げられるだけ広げてほしいなという思いがあるのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"契約、公共事業ということで、新型コロナウイルス感染症に関わって１点伺いたいのですけれども、新型コロナウイルス感染症対策で、いろいろな判断の上で現場が止まっているという話をよく伺うのですけれども、区が契約をして今実施している工事の中で、そういう案件というのは今どういう状況なのか、伺いたいと思います。","respondent":"東野経理課長","answer":"公園関係なのですけれども、それにつきましては現在、５月６日の再開という形になっておりますので、一時中止をしていたものにつきましては、皆再開をしているという状況です。","voiceIndex":77,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"感染拡大を防ぐことと工事を進めていくということは、もちろん初めての体験ですし、なかなか苦労されるところもあるかと思いますが、これは公共事業になりますので、区のほうでも必要な支援だったり助言だったり、何とか現場が感染症対策に照らしても安全に、そして工期どおりに進むようにというのでしょうか、そういうふうに進めていただきたいと。","respondent":"東野経理課長","answer":"国のほうでは、雇用調整助成金が現在検討されているところですので、そういった国の対策なども含めながら、業者のほうと十分な調整を図るように所管のほうへは指導していきたいと思います。","voiceIndex":79,"id":"exchange-035"}]},{"id":"topic-04","title":"品川区東五反田五丁目付近再構築工事請負契約","agenda":"品川区東五反田五丁目付近再構築工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問","question":"入札のときに技術者の配置だったりというのが計算できるかは、なかなか難しいものなのですか。積算金額の超過もしてしまうものなのか、何というか、４つの事業者の中で３つの辞退が出るというのが、どうしてなのだろうというのを思ってしまって、その辺、難しいと思うのですけれど、入札のときに何かあるのかなと思うのですけれど、お答えいただけますか。","respondent":"東野経理課長","answer":"技術者の配置が困難だというような辞退理由ですが、こちらにつきましては、入札公告をした際に、当然技術者の配置についても求めているものですが、設計図書をご覧いただいた上で、果たしてその人数が配置できるのかという、それは会社の中での条件になりますので。","voiceIndex":88,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"辞退理由についても、この場で伺うのではなくて、ここに書いていただけると、委員会までの間に、どういう質問につなげようかなということもいろいろとできるので、ぜひそういうことを、もう少し詳しい説明を求めたいと思いますがいかがでしょうか。","respondent":"東野経理課長","answer":"これらの算出にあたりましては、かなり詳しい資料が必要となってしまいますので、委員会資料の中で予定価格までのものにつきましては出していないのですけれども、委員会資料として必要な部分につきましては、今後検討してまいりたいと思います。","voiceIndex":90,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"入札申込みをされて、それぞれ４つあって３つが辞退です。図などを見ると大体似たようなもの、場所によって多少変わってくるのだろうと思うのですけれど、目的等々は一緒なのかなと思うのですが、そうなったときに、品川区内の事業者の中である程度こういう事業ができるよというのは、品川区内では大体この４社なのでしょうか。下請ですからね、いろいろな方が。事業者は４つだけというわけではないですよね。","respondent":"東野経理課長","answer":"ただ、技術者の配置につきましても、こういった工事に対して必要だというものを公告の中で示していますので、それに対応する技術者がいるかいないかという判断は、入札いただいた業者の中で判断していただくというような形になろうかと思います。","voiceIndex":93,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"例えば下請の方々もそうなのですけれども、たくさんあるわけではないので、やはり限られてくると思うのです。そうするとやはり、パイは決まっていて、そこでのやりくりがどうしても出てきてしまうということになってしまうと思うのです。だから、ここのちょっと不自然というか、もっと広げたほうが逆にいいのではないですか。今回も品川区に限定されているのですか。","respondent":"東野経理課長","answer":"それから品川区の中での下水道事業という部分で、品川区の区内業者での対応を、ということが求められているものです。そういったところを勘案して、工事発注をしたというようなところになります。","voiceIndex":95,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、何かやりにくいところがあるならば、やりにくいところを改善してあげるなどしていかないと、何となく、せっかく区内で頑張ってほしいという事業者が逆の方向に行っているような状況が作られてしまっているとするならば、非常にもったいないので、そういうことも含めて、入札に対しての枠を広げるなり、状況をしっかり踏まえるなり。","respondent":"東野経理課長","answer":"入札条件を絞りますと、おのずと業者の数が減っていく、そういったところもありますので、その点につきましては、区外の業者を入れるかどうかの判断をどの時点でするかということも含めて、今後検討してまいりたいと思います。","voiceIndex":97,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"そこまで区のほうは知っているのでしょうか。というのは、もし、ミリ単位で、今５０ミリ云々という話が大雨のときにはありますけれど、それが１００ミリ、１５０ミリ、２００ミリと仮に大雨の場合に、ここは危険な地域だと、配水管から各家庭に逆流するということもあるわけですけれど、そういう情報というのは区のほうにも来るのでしょうか。参考に教えてください。","respondent":"東野経理課長","answer":"５０ミリ以上の雨が降ってというような、ゲリラ豪雨のような状況もありますので、そういったところについて東京都と十分な調整をしながら、改修事業を進めているというふうに伺ってあります。","voiceIndex":99,"id":"exchange-041"}]},{"id":"topic-05","title":"(6)債権の放棄","agenda":"(6)債権の放棄","exchanges":[{"speaker":"西本委員","kind":"質問","question":"分からないところがあります。過払金です。なので、今までも過払いをしていて返金をしてほしいということがいろいろあると思うのです。その際に、やはりある程度はお願いするにしても、応えてくれる人と応えてくれない人がいて、その違いは何ですかというようなときに、金額にもよると思うのですけれど、間違ったものはしようがないねと。なので、強弱があると思うのです。","respondent":"中山会計管理者","answer":"今はシステムを変更して、住民基本台帳と連動しているので、逆にそういう対象ではない施設に入所されたときには行政のほうで把握ができるような、そういうことで過払金も、きちんとした債権ということを確保できるような形を取って。","voiceIndex":106,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"今の時期だから４年か５年くらい催促を行っているわけではないですか。それで、ご家族の方に相談したりしているわけですよね。あるのですけれど、なるべく短いことでお互いの折衷案をうまく出しながら、結局、こういう形になってしまうわけですから、早く結論を出してあげるというのも、その人のためになるのかなというふうに思いますので、今後いろいろ配慮していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-043"}]},{"id":"topic-06","title":"令和２年７月５日執行東京都知事選挙執行要領","agenda":"令和２年７月５日執行東京都知事選挙執行要領","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、新型コロナウイルス感染症対策についてということで、投票所に、つまり投票しようと思って来た方に、鉛筆とシャープペンシルの持参と書いてあるのですけれども、単純にボールペンは駄目なのですか。ちょっとそこを不思議に思ったので、ご説明いただきたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"なので、かすれて見えなくなる可能性がありますので、お勧めをしていないという状況で、今までは記載台に鉛筆を置いて書いていただいているというところなので、広報にはその旨、かすれて読み取れない可能性があるので。","voiceIndex":113,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"そうだったのですか。では、変な話、マジックというのかサインペンというのか、水性のものははじいてしまうということ。でも油性のものもあるので、もうちょっと説明していただけますか。","respondent":"秋山選挙管理委員会事務局長","answer":"水性のボールペンはなかなか乾きが遅いので、こすれる可能性が高いというふうに言われています。筆記用具の特性等については把握はしておりませんが、インクの乾きが遅い物についてはそういう可能性があるということで、ご説明をさせていただいています。","voiceIndex":115,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"来る人たちがばらけていればいいのですけれど、前日であったりとか、あとは雨になりそうだというような、台風の時期ではないのでどうかなと思いますけれど、そういうときだと先に行っておこうという方々がたくさんいらっしゃるのです。それから、選挙人同士の間隔を概ね１ｍ確保ということになると、結構幅を取ると思うのです。結構ぎちぎちなところがあるのではないかと思うのですけれど、いかがですか。","respondent":"秋山選挙管理委員会事務局長","answer":"１ｍの間隔なのですけれども、投票所の中の記載台についてはなかなか、１人置きに使っても１ｍというのはちょっと難しいところでありますけれども、投票所に入るために並ぶときに１ｍ間隔で並んでいただいて。","voiceIndex":117,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"もう一つ。新型コロナウイルス感染症の感染者は少なくなっているというふうに思ってはいるのですけれど、やはり外出できないですよね。今回の新型コロナウイルス感染症は治療に結構長くかかります。そうすると自宅待機であったり、病院でという方々がいらっしゃると思うのですけれど、その人たちの投票というのは何か工夫をする予定はありますでしょうか。","respondent":"秋山選挙管理委員会事務局長","answer":"ただ、それ以外の自宅待機者等につきましては、これは今、東京都を通じて国に照会をかけているところですので、どのような方法があるのか、その点については東京都から発出のガイドラインの中に記述があるというふうに聞いておりますので、それを見ながら。","voiceIndex":119,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"予防なのですけれども、やはり投票率を上げたいのです。今、照会しているということなので、いろいろと対策は取られると思うのですけれども、それが当事者に伝わらないと実行できないので、告知の方法も含めてしっかり対応を取っていただきたいなというふうに思っておりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-048"},{"speaker":"小芝委員","kind":"確認","question":"選挙公報のところでちょっと確認したいのですけれども、全世帯に公報が、投票日の２日前、それまでに配布されるということなのですけれども、まれに、家が奥まった路地の裏にあったりで、どうしても行き届かないケースがあるかもしれないのです。これまでに、直近の選挙でもいいので、そういった事例があったのかどうか教えてもらえますか。","respondent":"秋山選挙管理委員会事務局長","answer":"まれにマンション等で入るなということで届けられないところもありますので、そういうところは何とか交渉したり、届けていただくなりということがありますけれども、実際に届いていないということであれば再度届けるということで、ご連絡を頂ければ。","voiceIndex":122,"id":"exchange-049"},{"speaker":"小芝委員","kind":"質問","question":"それこそ投票日の前日の、例えば土曜日でも、もし届いていないというのであれば業者のほうにお願いして、すぐにお届けできるような、そういった仕組みというふうに考えておけばよろしいですか。","respondent":"秋山選挙管理委員会事務局長","answer":"土曜日の対応まではちょっと確認はしていないのですけれども、平日であれば確実に対応します。","voiceIndex":124,"id":"exchange-050"},{"speaker":"つる副委員長","kind":"確認","question":"それで、身体に不自由のある方などであれば、それ以外の方も当然ですがエレベーターを基本ご利用いただいて、その不在者投票の場所に行くということを考えると、いろいろなことが指摘されている中で、エレベーターの中の密を避けるとかそういう対応、対策も当然必要になってくるであろうなと考えられるので、そういう部分の配慮の確認。","respondent":"秋山選挙管理委員会事務局長","answer":"区役所の期日前投票所の場所ですけれども、執行要領で決めているところでございまして、６階の２６１・２６２会議室ということになってあります。","voiceIndex":126,"id":"exchange-051"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"銀行の組戻というのは私も初めて聞いたのですけれども、つまり、２回送ってしまった相手が何か手続きをしなくても、区のほうに戻ってくるということなのか、先ほどの私債権の放棄みたいに、やはり相手の同意というか手続きがなければ返ってこないというものなのか、ちょっとそこの組戻の仕組みがよく分からなかったので、ご説明いただきたいと思います。","respondent":"中山会計管理者","answer":"２点ご質問いただきました。この振り込まれたものの内容ということですが、例えば委託料であったり、工事関係の支払いであったり、物品の支払いであったりという、通常の区の業務で行っている支払いになります。なので、割と事業者の方が多いという状況になっております。","voiceIndex":132,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、間違ってしまったことは間違いですけれども、その回収はどこまでできるのか。もちろん全額回収するつもりで対応はするものの、その辺はどういう見通しなのか、金額が大きいだけに、非常に気になるところなのですが、最後にもう一度ご説明いただきたいと思います。","respondent":"中山会計管理者","answer":"ある程度、債権者登録の方が多いという中では、顔の見える関係が今までできておりますので、おわびとともに手続きのご協力ということで、全額回収していくということで頑張っていきたいと考えています。","voiceIndex":134,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に要望ですけれども、やはり事故の規模としては約１４億円と大きいものでありますので、組戻の一定のめどが立った時点で、改めて総務委員会に終了の報告となることが一番うれしいわけですけれども、報告をしていただけるよう要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"組戻等々に関して、コストがある程度かかりますよね。ただではないと思うのですけれど、それはどのレベルになりますか。それは全部こちら持ちという、一般財源から出ていくのだろうと思うのですけれど、どのぐらいのレベルですか。","respondent":"中山会計管理者","answer":"組戻の金額というのは区と指定金融機関とが結んでいる契約によります。今、１件４５円ということになっております。","voiceIndex":137,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"ちょっと計算しないと分からないのですけれど、組戻ではないものを使ったりというふうになると、いろいろな経費が、振込料だ何だかんだという形になるので、結局別途振込むなどとなると、振込料金が必要になるわけで、それは多少細かい話になりますけれど、その振込料を抜いた金額でやってもらうのか、あとは振込料は別途、そうしたらまた振込料がかかるなと思って。","respondent":"中山会計管理者","answer":"お客様には申し訳ないのですが、できるだけその銀行の組戻のほうで手続きをお願いしているところです。それがやはり難しいというお客様につきましては、納付書での納付ということでお願いをしております。納付書につきましては１件２円という手数料がかかるような状況です。","voiceIndex":139,"id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"今の報告の部分なのですけれど、本当にこの事故の経緯、どうしてこのようなことが起きたのかといった、その原因をきちんと明らかにしてほしいと要望いたします。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-057"},{"speaker":"つる副委員長","kind":"確認","question":"組戻手数料はそんな金額なのですねという感じで、ちょっと最初、いろいろ見て確認すると、一般だと８００円以下とか６６０円とか、個人の場合はそうなのでしょうけれど、行政や事業者間だとそのぐらいなのかなと思って、でも１件４５円かかるということは理解したので、そうなのですが、先ほどの、今現在の３６２件のうちの債権者登録と随時というものの内訳の件数というのは分かりますか。","respondent":"中山会計管理者","answer":"随時が全部で２９件あるのですが、随時のうちお戻しいただいた分が２６件ということになっております。２６件が随時で１回限りのお客様で、こちらのほうにご返金いただいたということになります。","voiceIndex":143,"id":"exchange-058"},{"speaker":"つる副委員長","kind":"確認","question":"そうすると、残りの随時は３件で、当然対象金額というのでしょうか、それが大きな規模なのか、もしくはその３件、どこという明示はちょっと駄目なのですけれど、見込みというのですか、いわゆるお返しいただく方法は別にしても、それが当然立つようなところなのか、いや、ちょっと、という、なかなかそれはないと思うのですが。その辺も再度もうちょっと、概要のところを可能な範囲で教えてください。","respondent":"中山会計管理者","answer":"今、当面の措置としましては、必ずデータ送信のハードコピーを取って、必ずそれを確認するというような作業もやっておりますが、もう少し指定金融機関と、実際どういうふうにしていくとこういう事故が防げるのか。","voiceIndex":145,"id":"exchange-059"},{"speaker":"田中委員","kind":"確認","question":"さっき確認し忘れてしまったのですけれど、ご説明の中にもしあったらごめんなさい。この事故が分かったのはいつ、何日だったのかというのを教えてください。","respondent":"中山会計管理者","answer":"事故の発覚というのは、実際のところ４月３０日に振込が２件されていますという事業者からのお知らせによるものです。","voiceIndex":147,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"今日で総務委員会、最終日という形になったのですけれども、１年間ありがとうございましたということと同時に、来期の、これから本会議にかけられてということで委員会メンバーが決まるわけですが、議会運営委員会で無所属は総務委員会には属せないという取決めがなされました。委員長、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":41257,"voices":155}},{"id":"r02-20200520-14","meetingId":"r02-cm05","date":"2020年5月20日","dateIso":"2020-05-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時０７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと議事の運営について意見と、あと質問を１点だけさせてください。委員長としてこういう判断をされたということですが、今回、なぜ陳情審査を見送るという判断をされたのか、理由だけお伺いさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":2,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6088#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":2660,"voices":13}},{"id":"r02-20200522-18","meetingId":"r02-cm05","date":"2020年5月22日","dateIso":"2020-05-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時４５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京２０２０大会に向けた機運醸成ＰＲ動画","agenda":"東京２０２０大会に向けた機運醸成ＰＲ動画","exchanges":[{"speaker":"つる委員","kind":"質問","question":"例えば３キャラクターにマスクをさせて登場させるとか、ソーシャルディスタンスとかフィジカルディスタンシングを取らせて映像を撮るとか、そういったものの中では、子どもたちにも、新しい時代なのだということのＰＲもできるのではないかと思うのですが、その辺りの企画とかは現状、お考えの中にあるかどうか教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"コロナが広がる状況の中で、なかなか大きく大会に向けてというＰＲは、今は難しい時期だと認識しております。その中でも私どもは、できることはやろうということで、インスタグラムとツイッターを使っていろいろな発信はしています。","voiceIndex":8,"id":"exchange-001"},{"speaker":"つる委員","kind":"質問","question":"動画とは少し外れるかもしれませんけれども、世界の感染状況がどうなるかというのは分からない中で、さっき言ったように希望をつくるという部分では、２３区のどこかでも、ある区ではカウントダウンを再開するところがあります。いろいろな規制があるのかどうか分かりませんけれども、その辺の考え方を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"カウントダウンタイマーの件なのですが、私どももいろいろ検討して、どうしようかということで、今のところ閉じています。","voiceIndex":10,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"当然この緊急事態が解除されても、本来行うべきであった７月、８月の時期、今年の夏にはまだにぎわいが戻りませんが、例えば来年の、もう日にちが決まっておりますので、７月２５日、１年前だとか、半年前だとか、にぎわいはできないですけれども、機運が醸成できるような取組みというのを、２０１９年度で思い切りやったような取組みを２０２０年度も、できることとできないことがありますけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今年度も当初の予定では、夏に向けて幾つかの機運を上げるようなイベントは企画しておりました。","voiceIndex":12,"id":"exchange-003"},{"speaker":"西村委員","kind":"質問","question":"いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"非常に貴重なご意見、ありがとうあります。例えば１分間で腕立て伏せ何回とか、スクワット何回とか、いろいろな形で、子どももできる、例えば縄跳びだったり、いろいろな形が考えられると思いますので、ご意見のようなものも含めて企画はしていきたいと思います。","voiceIndex":14,"id":"exchange-004"},{"speaker":"西村委員","kind":"質問","question":"しな助の方の英語のワークショップは、私どもも見られる状態になるのですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今配信しているのはワークショップではなく、一方的に流しているものなのですけれども、これはしな助の方だけなのです。ただ、なかなかすてきな内容なので、終わった後には一般公開も、しながわネットＴＶで流そうかという話はしています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"私もぜひ来年、オリンピックをやっていただきたいという希望を持っている一人なのですけれども、一方で現実的に見ると、またコロナウイルス感染の第２波がやってくるかもしれないとか、日本はよくても、世界との関係でどうなのかなという問題もあります。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、あまり大規模なイベントにお金ばかり使って、もったいなかったとはならないように、きちんと情勢を見据えながら、どういった形が適切なのかということを確認しながら進めていきたいと思います。","voiceIndex":19,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。ぜひ早めにそうした情報は頂かないと、品川区も困ってしまうと思いますので、今の状況というのをこれからどう考えていくのかということをお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私ども品川区も、大会組織委員会に何人も職員を派遣しておりますので、そういった職員からの情報提供もありますし、オリンピック・パラリンピックの担当課長会というものが随時ございまして、その中でも大会組織委員会や東京都がいろいろな説明に来ておりますので。","voiceIndex":21,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、つる委員からも確認をさせていただきましたカウントダウンの件についてですが、緊急事態宣言が解除されるところが一つのタイミングですけれども、品川区のホームページ上でもオリンピック・パラリンピックの特設サイトがトップ画面から外れておりまして、コロナの関連のトップ画面になっておりますが、そのホームページのトップ画面へ、また出していくというところのお考えが今後どうなのかというのを。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区のホームページの、今までは左上のほうに、トップ画面に出ておりましたが、今はコロナ対策が出てあります。こちらは広報広聴課とのやり取りになると思いますが、今後一定程度、コロナが収まった時点で、またお願いしたいと思います。","voiceIndex":23,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"コロナとの共生がこれから始まっていくということで、オリンピックを迎える１年後も、新しい生活様式と言われている中での、私たちがそういう生活をする中でオリンピックを迎えていくことになると思うのですけれども、ぜひトップ画面にカウントダウンも復活させていただいて、その際には、オリンピックを迎えるためにコロナに打ち勝っていくというメッセージも出していただきながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"２度目でごめんなさい。さっき伝え忘れていました。例えば「いいね！ホームページを開けば、何色になっていたら、大阪とかがやっているけれども、例えば花が咲くとか、そういうものでも、まさにみんなの団結力というものもできていくのではないかと思いますので、ぜひいろいろ知恵を課でも考えていただいて、やっていただきたいと思いますが、何か感想を頂ければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それもヒントにしながら、なかなか課の職員だけで考えても、アイデアが底をついてしまうところもありますので、ぜひいろいろな意見をまた頂いて、区民みんなで盛り上げられるような、近くにいなくてもつながれるような取組みというのをしていきたいと思っています。","voiceIndex":26,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":11058,"voices":32}},{"id":"r02-20200526-10","meetingId":"r02-cm05","date":"2020年5月26日","dateIso":"2020-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議事日程(1)、追加議事日程および追加議事日程(2)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"監査委員の２件、選任同意ということですが、まず、本多議員についてですけれども、監査委員は第１会派および第３会派から選出されるべきだとの考えから賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"日程第２については、第３会派でないという理由で反対したいと思います。この際、一言述べしますが、これまで品川区議会はずっと第１会派、第３会派で監査委員を選出してきました。こういった選任の方法は、やはりフェアな進め方ではないと思いますので、改めて監査委員は第１会派および第３会派から選任されることを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"}]},{"id":"topic-02","title":"正副委員長の互選","agenda":"正副委員長の互選","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ほかの自治体で選任、委員長とかいろいろ決められるときに、問題が起きている事例が見受けられます。ですから、最初に臨時委員長の席には大会派の人を入れたほうが、問題が生じないかと思うのですが、いかがでしょうか。","respondent":"米田区議会事務局長","answer":"これまで臨時委員長等を決めるに当たりましては、年長議員の方に臨時委員長になっていただいていますので、そのように先ほど説明させていただいたものです。","voiceIndex":22,"id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"質疑というわけではないですけれども、令和２年度行政視察について議長から説明があったとおりでよいと考えています。ただ、今後、新型コロナウイルス感染症の収束状況、また、第２波、第３波も含めて区議会としてどう対応すべきなのか、議長のほうで十分考えておられるかとは思いますけれども、引き続き協議しながら進めていただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":9096,"voices":55}},{"id":"r02-20200608-6","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"区民委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"もう一点は、これも大きな流れでいいのですけれども、戸籍住民課に伺いますけれど、印鑑、判子は今もう、いろんな意味で、果たして必要なものかというのが話題に出ているのですけれども、大きな意味でいいので、その辺についてはどういうふうに考えていこうとしているのか教えて頂きたいと思います。","respondent":"黛生活安全担当課長、木村戸籍住民課長","answer":"こちらにつきまして、積極的に地域の皆様方にご説明申し上げまして、一つでも多くの地域に防犯カメラを設置していただけるように努力してまいる所存です。私どももそういう状況を注視しながら、判子を押さなくても済むような手続が、どういうことができるだろうかというのは、これからも研究を続けてまいりたいと思っています。","voiceIndex":30,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"地域活動課で、１６ページの「地域課題の自主的解決の支援」というので、実績がゼロなのですけれど、課題がなかったのならいいのですけど、使いづらい状況とか、そういうことではないのですかという確認なのですが。それに対しての対応はどうされているのかというのをお聞きしたいと思います。それから、経営変化対策資金２０２０の４・５月の融資あっ旋に関する相談件数が３,２５７件あるということです。","respondent":"川島地域活動課長、黛生活安全担当課長、遠藤商業・ものづくり課長","answer":"地域課題の自主的解決の相談件数ゼロというところですけれど、こちらは町会・自治会から専門的な地域課題の相談対応をするということで。区内４警察署とも、関連する情報の共有を進めておりまして、何かありましたときは瞬発的に対応できるように努めてまいりたいと存じます。今回のコロナ対策につきましては、私どももかなり融資の枠を広げていただくなり、あるいは補償につきましても、国からできるだけ貸すようにという形で。","voiceIndex":34,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区民に一律３万円で、子どもは１５歳以下が５万円ということで、本当に出ますけれども、対策が必要な状況にあるのではないかと。なので、そういった都の施策、国の施策もそうですけれども、実態の把握というのをぜひ、このときだからこそ進めていっていただきたいと思いますし、都や国の支援策がどこまで行き届いているのかというのを把握していただきたいと思うのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"都や国の部分の状況把握ですが、実際の把握というのは、先ほど言ったとおり、直接の数字というのはなかなか難しいところかと思いますが、私ども、例えば社会保険労務士の相談窓口、雇用調整助成金などの窓口。","voiceIndex":38,"id":"exchange-003"},{"speaker":"つる副委員長","kind":"提案","question":"事務事業概要なので簡潔に聞きたいのですけれど、１点、提案と検討いただきたい点でして、新型コロナに関連して、この６月１日から小学校等が分散登校になって、日中、あと夕方以降、お子さんがいる機会が多くなっているということで、教育委員会を中心に、地域の方と連携して、子どもたちの安全安心のためにいろいろ対策を取っていただいているということは分かっています。","respondent":"黛生活安全担当課長","answer":"現段階におきましても、生活安全サポート隊が、例えば５時を過ぎて公園などで遊んでいる子どもを見かけましたら、車を降りて、直接、子どもたちに、「もう帰りなさい」ということで声かけなどをしているところでございまして、こういうもの等を引き続き行いながら、今。","voiceIndex":41,"id":"exchange-004"},{"speaker":"つる副委員長","kind":"質問・要望","question":"事務事業概要なのであれですけれど、ぜひほかの教育委員会、それから防災行政無線は防災課だと思うのですけれど、連携を取って、この夏も、夏季休業であったところが短縮されて、子どもたちが子どもたちだけで日中外に出ている機会が増えてくると思いますので、熱中症対策なども含めて、そうした危険にさらされないような対策・対応というものを、しっかりと生活安全担当を中心に各所管に投げかけて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"事務分掌のところで、すごく本当に答えがないところだとは思うのですけれど、１点、こういう機会でないとなかなかお伺いできないと思うのでお伺いしたいのですけれど、今、スポーツというところで出てきて、最近はチェスなどもマインドスポーツという事で言われているかと思います。これは、問題意識の共有という意味で質問させていただければと思います。","respondent":"中元スポーツ推進課長","answer":"東京都などでも、産業労働局ですか、ああいうところが、地域の事業、企業活動の推進という部分を、まちおこしみたいな形で地方ではやっているところもありますので、区全体の中でどこが、それぞれの組織の目的に果たしてかなうのかというところで、今後。","voiceIndex":69,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"このコロナの状況の中で、本当に様々な行事が軒並み中止になっていると、この事務事業概要を見ても感じているところですけれども、今後、働き方とか、いろいろ在り方が、このコロナで問われている中で、スポーツというのは、マスクをしながらというのは本当に危険だし苦しいし大変だと思うのですけれど、区として、こういった状況の中でのスポーツの在り方というのを、今後、長引くと言われている中では。","respondent":"中元スポーツ推進課長","answer":"それで、大きくはまだ、今まさに新しい生活様式ということで言われているところを、私どもも日々、情報収集し、研究しながら、また施設を開けていくにしても、いろいろな皆さんの健康管理、健康チェックもきちんとお願いしながら、ご協力いただける方に使っていただくとか。","voiceIndex":72,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、スポーツ庁のガイドライン等々もということだったのですけれども、そういう今後のスポーツというものを、専門家というのですか、いるのかどうか、こういうときのスポーツのやり方というのを、医師会の皆さんとか、感染症の専門家の皆さんと、さらにスポーツのところでの専門の皆さんでの話合い、議論というのですか。","respondent":"中元スポーツ推進課長","answer":"感染症の専門の方はいらっしゃいませんが、筑波大学の体育の専門の教授の方などもいらっしゃいますし、様々、その中でもお話は出てくるかと思っているところですので、なかなか区独自で、今、何しろ感染症の専門の方は本当に感染症対策でお忙しいかと思いますので。","voiceIndex":74,"id":"exchange-008"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"意見","question":"これはコロナ禍における商店と商店街の今後の取組と施策についてなのですけれども、大枠では個人商店と商店街支援についてです。こちらの調査の希望事項につきましては、商店・商店街が消費者を呼び戻す施策について、現状の課題と区の支援策についてです。そして、中・長期期的な観点から、今後の状況に応じてどのような取組ができるか。他自治体の取組も参考にしながら、その２点の調査を希望いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"歩行者の喫煙です。もう一点が、先ほど質問させていただいたｅスポーツについては、品川区が、多分ほかの自治体では検討していないようなところを、自治体としてｅスポーツをどういうふうに推進していけるのかというところも、所管事務調査ということでやらせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-010"},{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、所管事務調査について２点要望したいと思います。その新しい時代の中で、今後、品川区の取組がどうしても課題になってくると私は考えます。地域の絆が、これからより一層高まっていく必要性が高いと思いますので、私は、地域で住む人を牽引する町会を、ぜひとも品川区で支援していただきたいと思いますので、町会・自治会の支援について要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-011","title":"町会・自治会支援"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり今回のコロナで宿泊業と飲食店は大打撃を受けたということも報道されているのですけれども、そうした企業、業者と商店街というところでは、すごく、それがなくなることで、生活の大きなところですから、生活の大きな支えを失うというのは、精神的にも本当に、自殺にも追い込みかねないところにまで問題になってくると思うので、そこへの支援の在り方、そして実態をつかんでいけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"皆さんから意見が出て、全て所管事務調査したい、すばらしい意見が出たのですが、来年の４月、５月まで、この委員会は２０回はないですよね。ですから、これは委員長・副委員長に、皆さんのご意見をまとめていただいて、私は全部、所管事務でやりたいです。でも、物理的な回数等も条件としてあるので、正副にお任せいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-013"},{"speaker":"つる副委員長","kind":"提案","question":"一方で、希望のない話題ばかりが続く中でありますので、所管はオリンピック・パラリンピック委員会とのすみ分けはあるわけですけれど、オリンピック・パラリンピックで１つの希望を持つメルクマールになるようなものを所管している委員会ですので、そうしたことも含めた地域の振興に資するようなことができるような、そこも未来志向な形で所管事務調査の中に入れればいいかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":36295,"voices":88}},{"id":"r02-20200608-7","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"厚生委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"公明党のあくつ広王です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"９ページのことなのですけれども、法人への派遣職員ということで、組織図の中に書いてあり、それから、法人からの派遣職員を含むと書いてあるのですけれども、法人からの派遣職員というのは、この組織図ではよく分からない気がしたのですが、どの法人からどこに何人派遣されているのか、ご説明願えますか。","respondent":"寺嶋福祉計画課長","answer":"全体の組織図の話になりますので、私から申し上げます。法人からの派遣につきましては、高齢者福祉課の高齢者支援第一・第二係に、区内の法人から４名の職員が派遣されております。職種としては、主任ケアマネジャーです。","voiceIndex":28,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"先ほどもお話が出ていたのですけれども、介護保険の第八期の計画策定の年なのですが、介護保険の計画策定に向けて、前の年にニーズ調査を行うということが厚生労働省から求められていたと思うのですが、品川区は行っていないのではないかと思うのですけれども、その理由を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"ページですか。さっきの説明にあったと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"その第八期計画の策定スケジュールやメンバー、あるいは委員会の回数や、おおよその日程を教えていただければと思うのですけれども。","respondent":"宮尾高齢者福祉課長","answer":"第八期の介護保険事業計画に向けてですが、こちらは現在の第七期あるいは第六期のときと同様に、基本的には、介護保険制度推進委員会と一緒に策定の準備を進めてまいりたいと考えています。時期を見て、別途ご報告をする予定でおります。","voiceIndex":39,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"それで、最終的に骨子案ができて、パブリックコメントというのが、従来のパターンだと思うのですけれども、パブリックコメントだけではなくて、区民に対する説明会を行うという形に、今回から切り替えてほしいというのが私の要望なのですけれども、その点では、区民への説明会、そして要望を聴いて。","respondent":"宮尾高齢者福祉課長","answer":"ただ、調査は、先ほどご答弁申し上げましたニーズ調査に加えまして、毎年モニタリング・アンケート調査等も実施しております。こういった結果も反映をさせていただきたいと考えていますので、現時点では住民の説明会等を実施する予定はございません。","voiceIndex":44,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"私としては、紙で聞くだけではなく、説明会は、区民同士も顔を合わせることになるわけですから、独自の意義があると思います。説明会という形での要望を聴く場、そしてそれを骨子案に反映させるようなことを考えていただきたいという要望を申し述べておきます。その点に関しては以上です。続けていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"障害者福祉課の方にも同様のことをお聞きします。第６期障害福祉計画、それから第２期障害児福祉計画策定の年です。同様に、策定委員会のメンバーや、委員会の回数は４回ほど予定されているということを、さっきおっしゃられていましたけれども、もう一度重なりますが、回数や日程、それから素案策定、当事者・家族・事業所などへのヒアリングや説明に対する考え方、それからパブリックコメントの日程や……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"計画策定のスケジュールなどございましたら、お聞きできたらと思いますけれども、お願いいたします。","respondent":"築山障害者施策推進担当課長","answer":"今年度実施します障害福祉計画の策定に関してですけれども、策定委員会は先ほど説明させていただきましたとおり、４回程度を予定しています。","voiceIndex":49,"id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"生活福祉課の方にお聞きします。それで、品川区の実態をお聞きしたいのですけれども、その報道は４月だけでしたが、比較するために、できれば３月、４月、５月の申請件数、昨年度と今年の申請件数、できればその増加率を品川区についてお伺いしたいのですけれども、お聞きできるでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"非常に生活困窮者は、共産党でもアンケートを取っていますし、新聞報道やテレビの報道でも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"これから、生活保護の申請は増えると思います。それで、品川区はどのように対応しているかということで、ホームページを調べてみたのです。私が見たところ、目次があるだけという形で。そういうことが品川区のホームページや、生活保護に関するリーフレットに足りないのではないかと非常に思いましたので、それをやっていただきたいということを、今日お願いしたかったということなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうです。だからこそ、リーフレットやパンフレット、そしてホームページでの案内を、きちんと作っていただきたい。そして、そういうリーフレットやパンフレットを、新型コロナウイルス感染症で本当に困った区民の方が、すぐ目につくところに置いていただいて、品川区はこのような制度を持って、自分も助けてもらえるのだと思えるようなものを作っていただきたいと思います。それを本当に要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-013"},{"speaker":"おくの委員","kind":"質問・要望","question":"もう１点だけ。すみません。それに関連して、生活福祉課の仕事はますます増えることが予想されます。これまでも、ケースワーカーの受け持ち人数が多く、ケースワーカーを増員すべきことを求めてきました。今のケースワーカーの１人あたりの受け持ち人数というのは一体何人なのか。そして、最も多いケースワーカーの方は何人を受け持っているのか、教えていただきたいと思います。","respondent":"櫻木生活福祉課長","answer":"ケースワーカーの担当世帯数についてのご質問かと思います。直近の数字で申し上げますと、４月時点で保護世帯数４,５５２、ケースワーカー４３名で、ケースワーカー１人あたりの世帯数は１０５世帯となっております。","voiceIndex":68,"id":"exchange-014"},{"speaker":"おくの委員","kind":"質問","question":"組織図で、ここには生活福祉課６７人の職員と書かれていますけれども、非常勤の方は常勤換算で何人いるのか、伺っておきたいと思います。","respondent":"櫻木生活福祉課長","answer":"会計年度任用職員は現在３０名いまして、常勤換算いたしますと、２２人相当となります。","voiceIndex":73,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"９ページの組織図のところなのですが、先ほど障害者福祉課が４７人ではなくて、３６人という訂正があったと思うのですけれども、私は障害者福祉課の皆さんがすごく忙しくされているというのを団体の皆さんからお聞きして、本当に夜も遅くまで明かりがついているので、４７人に増えてよかったと思っていたのですけれども、実は３６人ということで、去年が３９人と書かれていましたので。","respondent":"寺嶋福祉計画課長、松山障害者福祉課長","answer":"社会福祉協議会に３名、それから三徳会、品川総合福祉センター、さくら会に各１名、計６名が法人への派遣です。障害者福祉課の職員数についてですけれども、申し訳ありません、昨年度についても非常勤職員を含めて集計をしていたために、昨年度の職員数としては。すみません、こういった事情ですので、この後、『品川の福祉』という形で製本することになりますので、その際に改めまして。","voiceIndex":76,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それを見せていただければ、最終的には分かることなのですけれども、今の時点で福祉部全体の職員の人数というのはどうなっているのかというのだけ把握しておきたいのですけれども、去年が何人で、今年が何人で、増えたのか、減っているのか、会計年度任用職員がどうなっているのか、その辺の職員体制の全体像がもしも分かれば、教えていただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"今この段階で、全数を申し上げることができませんので、申し訳ございませんが、『品川の福祉』のところで新しい数字を改めてご紹介するということで、今日のご答弁とします。","voiceIndex":80,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"分かりました。職員のところはそういうことで、ぜひ増やしていただきたいという要望だけ、お伝えしておきたいと思います。","respondent":"櫻木生活福祉課長","answer":"大きく２つのご質問を頂いております。１つは生活保護、暮らし・しごと応援センターの周知、もう１点が住居確保給付金の件数ということでございまして、概要についてご説明します。","voiceIndex":82,"id":"exchange-018"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当に大変な中、お疲れさまです。ただ、区民の皆さんもすごく待ちに待っているという状況があると思うのですけれども、支給までに２カ月ぐらいかかるという報道がされているところもあるようなのですけれども、申請からおおよそ２カ月ぐらいかかってしまうものなのか、その辺のところの見通しが分かったら、教えていただけたらと思います。","respondent":"寺嶋特別定額給付金担当課長","answer":"処理件数なのですが、まだ作業のペースが完全に慣れてきてフル回転しているという状況まで、もう一息なのですけれども、見込みとしましては１日３,０００件、これは２４時間態勢、３交代で委託を入れてやっていますけれども、夜間をやらないと２,０００件程度ということなので。","voiceIndex":90,"id":"exchange-019"}]},{"id":"topic-04","title":"事務事業概要を再度、議題に供します。 再度のご案内ですが、この事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務","agenda":"事務事業概要を再度、議題に供します。 再度のご案内ですが、この事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これは、品川区が特に保健師が少ないということを示すデータではないかと私は思ったのですけれども、それで、２３区、保健師１人あたり、何人の人間を受け持っているかという数を割り返しますと、品川区は９,０００人を超えるわけです。それが新型コロナウイルス感染症のときに現れてきたのではないかと非常に思ったのですけれども、その辺はどのようにお考えなのかということを伺っておきたいと思います。","respondent":"鷹箸保健予防課長","answer":"今回、新型コロナウイルス感染症対応に関しまして、看護師、派遣の看護師とか、あとは庁内からも多くの職員の協力を得て、何とかこれまでやってきた中で、事務職に関しては先ほどグラフのところでご説明したのですが、区に患者が出ますと、入院勧告、就業制限。","voiceIndex":120,"id":"exchange-020"},{"speaker":"おくの委員","kind":"質問","question":"さっき人口と保健師の数ということで挙げたのですけれども、一般論としても、品川区の保健師はそれほど少ないものではないというご認識なのでしょうか、伺います。","respondent":"榎本荏原保健センター所長","answer":"先ほど保健師の活動のところでご説明いたしましたけれども、精神保健福祉の活動が、グラフの中では一番多かったですが、そういった点につきましては、品川区においては心理職の配置をしているというのが、かなり特徴的な、ほかの２３区にはほとんどないという状況でありますので。","voiceIndex":122,"id":"exchange-021"},{"speaker":"おくの委員","kind":"質問・要望","question":"失礼しました。では、新型コロナウイルス感染症対応に関してもう一つ伺っておきます。これは既に始められたのでしょうか。他方で、健康観察を受けている濃厚接触者の件数は２,３４８件だと。大変な増大ということになると思うのですけれども、区としてはどのように体制を強化していくつもりなのか、その辺をお伺いしたいと思います。いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"今後、そのような対象者が増えた場合には、確かに委員ご指摘のとおり、今設置されている帰国者・接触者外来あるいはＰＣＲ検査センターの対応数では賄えなくなる可能性がありまして、第２波に備えて。","voiceIndex":127,"id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"今のことに関連して、これから冬にかけて、インフルエンザ等もいろいろはやって大変なことになってくると思うのですけれども、新型コロナウイルス感染症のことに集中するためもあって、インフルエンザの予防接種の無料化を進めて、どんどん予防接種を受ける対応、受ける人が増えるように持っていく対応も必要ではないかと私は思うのですけれども、この点、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国民健康保険のことを伺いたいのですけれども、新型コロナウイルス感染症による国民健康保険の減免制度というのが対象になるというところが厚生労働省から出ていると思うのですが、前回の厚生委員会の中でもお話させていただきましたけれども、これがいつから対象になっていくのか。","respondent":"池田国保医療年金課長","answer":"それで、６月１５日に保険料の発付ということで先ほど説明させていただきましたけれども、その中に国民健康保険の便りが入りますので、その便りの中に、新型コロナウイルス感染症減免についての説明書を入れするということと、それから。","voiceIndex":133,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3568#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":56955,"voices":140}},{"id":"r02-20200608-8","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"建設委員会","time":"午後 １時００分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"様々なまちづくりの動きの推進を強化していくということでご説明がありましたけれども、そうすると、担当部長は、事務が増加したことによって、それを処理するためということでしたので、どのように事務作業をやっていくかという、担当部長としての仕事内容をお聞きしたいです。","respondent":"中村都市環境部長","answer":"この担当の部署そのものの業務としましては事務量の増加といったものがありますけれども、これはまちづくりの推進の事業でございまして、そうしますと、まちづくりは品川区だけが単体で動くところもありますが、さらに東京都あるいは国。","voiceIndex":37,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"私としては、再開発ですとか、そういうものを推進していく必要はないと思うのですけれども、いかがかということと、あと、今までこれだけの体制をとったことというのはあるのでしょうか。それぞれの課、部に配置されている職員の人数も伺いたいと思います。今回の担当部長と都市開発課長とまちづくり立体化担当課長という体制。","respondent":"中村都市環境部長、多並都市開発課長","answer":"それは不燃化であったり、耐震化であったり、そういった取り組みについて言えることですけれども、また、にぎわいの維持と向上。失礼いたしました。現在の人数とほぼ同等だったと記憶して……。そういう体制で進めていきたいと思っているところです。","voiceIndex":39,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"部長の人数分だけ今回増えたということでしたけれども、私としては、やはりこうした開発の体制をとっていくということは、区民の暮らし、福祉を充実させていくというところの人材も予算も、開発のほうに振り分けられていってしまうということを感じているのですけれども、そういった今回の体制、担当部長も配置したということで、福祉よりも開発に優先性が表れているのではないかと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"簡潔に。まとめて伺います。これだと１年前の数値ということになってしまいますので、ぜひ最新の数値を事務事業概要に載せるべきだと思うのですけれども、いかがでしょうか。もう一点、今、公園の整備で、公園のない町会に公園を整備していくということで品川区も進められていると思うのですけれども、これをどういう方針で、あるいは方法で進めていくのかという区の考え方を伺いたいと思います。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"私から、１点目のまちづくりと東京都の動きとの関連性のところですけれども、不要不急の中で、やはりまちづくり事業、先ほど部長からもご説明させていただきましたが、短期的なスパンもありますけれども、長期的なスパンの中で。補足としまして、ご質問の中に、不要不急の事業として補助２９号線はいかがかという話もございましたが、基本的には、この事業は東京都の事業ですので、東京都が判断していくというところではありますが、今のところ。","voiceIndex":45,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"すみません。公園については、部が違って申し訳ありませんでした。要望していただきたいと思います。不要不急の事業の判断のところでは、総合的な判断をしていくということで、そうすると、区内で判断をしていく事業の中で、中止や延期していくものがあるのかということと、あと、実際検討というのは行われたのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"そういう形でしっかり支援していきたいという意味ですので、中止か、延期かという検討というのではなくて、地域の方のご意見をまずはしっかりとよく聞いていくというのが区の立場の今のやるべきことだと考えているところであります。","voiceIndex":48,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"最後の質問にしたいと思いますけれども、区のほうで検討するということではないと。住民の方の支援をしていくという話でしたけれども、やはり区の財源を投入されるわけですから、区としても新型コロナウイルス対策に尽力をしていくということでは、区のほうで判断していくことも必要なのかと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"区のほうで入るというか、まずはまちづくりの基本は、地域の方が皆さんがご自分で考えて、どうしていこうかと考えられる協議会だったり、準備組合だったり、そういう段階からご自分たちで組織されて検討していくと。","voiceIndex":51,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"都市計画課の２１ページ、空港環境担当についてお伺いしたいのですけれども、４月２０日の総務委員会で新設されるという報告があり、どのような事業をされるのかといったことが気になっていたのですけれども、この中で、空港環境担当の事業が騒音測定のことしか書かれていないというのを思いまして、「区民からの声を国に届けるとともに」などと書いてあるので、ほかにもきっと。","respondent":"鈴木都市計画課長","answer":"ご質問の空港環境担当、今年度より新設ということでございまして、こちらの事務事業概要は予算化されているものを中心に記載させていただいておりまして、予算化されて今年度実施していく一番大きなものとしては、区内２か所に測定局を設けて騒音を測定していくというものです。","voiceIndex":53,"id":"exchange-007"},{"speaker":"田中委員","kind":"意見","question":"ありがとうございました。その事業の中で、測定値の公表をしていくといったことが書かれていますけれども、これから区のホームページ等でも公表していくということと、あと、区民から寄せられた声や、それに対する答えだったりとかも、この担当の中でやられていくのかといったところもお知らせいただければと思います。","respondent":"鈴木都市計画課長","answer":"羽田の新ルートについては、３月２９日より本格運用が開始されて、南風時は４月の頭から実際飛行が開始されてあります。区のほうでは、既に１回目のときから騒音の測定を行ってあります。基本的には、毎月とりまとめて、翌月の月末に月単位で騒音値の公表を行っていく予定です。","voiceIndex":55,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"多く寄せられる要望、意見と、それに対する答えとかがホームページに載っていれば、Ｑ＆Ａみたいな形で出ていれば、自分が聞きたいこととかも“ここを見れば分かるのだ”といったことにもなるのかと思うので、ぜひそういったことも要望したいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"せっかく新設されて、きっといろいろと相談ができるのだろうと期待されている方たちもおられると思うので、ぜひホームページだったり、情報発信をきちんとしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか確認をします。まちづくりですから、長期という話が部長のほうからありましたけれども、ただ、マスタープランの中でもかなり変わってきているのではないかという思いがあるので、そこの補正というのをどうかけながら、この１年間議論すればいいのかということです。これから建設委員会で議論する中で、大きな影響が出てきてしまわないかというのがすごく心配されるのですが、その辺はいかがでしょうか。","respondent":"森住宅課長、中村都市環境部長、鈴木都市計画課長、多並都市開発課長","answer":"そういったものを集計いたしまして、今具体的に申し上げたような管理項目の中で、不備がある。組織の話につきまして、部長、あるいは担当部長というのは、形式上では、部の一番上に２つ並んで配置されるわけですが、ただ。１０年といいますと令和４年度末になるわけでございまして、次回の見直しを１年で行うのか２年で行うのか。現在も様々なまちづくりの都市計画手続きが進んでいる事業がありますけれども、それについても。","voiceIndex":61,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、１点だけ教えてください。例えば、人が集まるマンションの管理セミナーみたいなのも、多分、大分できないのだろうという部分があるではないですか。マイナスは分かっているから、例えば、１０のうち２割ぐらいは減ると思っていますとか、そこら辺の肌感覚と、現実的にどのように思っていらっしゃるか、いつ頃までにそれを分かるようにしようと思っているか、そこら辺を教えていただきたい。","respondent":"中村都市環境部長","answer":"そういったところで、今、全庁的に事業の中止・延期を見据えた見直しが行われておりますので、この中で都市環境部としても、一定割合は、すぐに何割というふうには申し上げることはできませんけれども、やはりパーセンテージでいけば２桁台のパーセンテージで。","voiceIndex":67,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひお願いだけしておきます。どうしてこういうことを言うかというと、各管理職の方々がその事業のことは一番分かっていらっしゃる。なおかつ部長がそういうのを分かっていらっしゃる。だけれども、必ず私ら議員としては、来年度予算だって、区民サービスの低下はしないように組んでくれということは、もうすぐこれは始まってくる頃だろうと思うけれども、そういう要求をしていくわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-013"}]},{"id":"topic-02","title":"では、報告事項、羽田空港の機能強化に関する要望","agenda":"では、報告事項、羽田空港の機能強化に関する要望","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、要望に行った目的、どういう目的で行ったのか。なぜ行ったのかということです。要望の中で、新型コロナウイルスの影響の中で就航需要の減少を踏まえ、一層の騒音軽減策の推進を求めるということで書かれているのですが、これはどういう意味なのか、具体的に何を求めているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"要望の目的ですが、３月２９日から本格運用が開始されてございまして、ただ、新型コロナウイルスの関係で、就航本数減便、運休が続いている中で、本格運用が開始されて実施されてきてあります。","voiceIndex":75,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"この発言要旨については、このとおりだというご説明でしたけれども、就航便数が減っているわけですよね。つまり、騒音が来る、品川の上を飛ぶ機会も減っているという中で、一層の騒音軽減策の推進というところが、少し矛盾するというのか、よく分からないのです。そこが何を求めていらっしゃるのか、区のビジョンというか、考えがおありでしたら、ご説明いただきたいと思います。","respondent":"鈴木都市計画課長","answer":"その意図は、この発言にはございませんが、当然ながら、従前に戻すとか、あるいは運行時間帯、夕方３時から７時の３時間程度というところで計画が実際に進められておりますが、この３時間をもう少し短くするとか、そうしたところ、新型コロナウイルス感染拡大に伴う中で。","voiceIndex":77,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"私たちも区議団としてアンケートを行っていまして、やはり減便されている中でも、騒音がうるさいと。そうした中で、今、従前のルートに戻すことも含めてというお話がありましたけれども、そうすると、新飛行ルートを固定化しない取り組みというのは、区が求めるこの取り組みというのは、品川の上を飛ばないルートを求めたということで理解していいのでしょうか。","respondent":"鈴木都市計画課長","answer":"ご質問、２点いただきまして、１点目の、要望書にもあります新飛行ルートを固定化しない取り組みの実施、これは、昨年８月の国の本格運用決定前、それ以前から、区として固定化しない取り組み、この意図は、当然。当日、航空局長のほうから、首都圏での騒音の共有というところがございましたが、これまで平成２６年、国がこの機能強化を計画として打ち出して以降、様々、オープンハウス型あるいは教室型説明会の中で国が説明してきている内容。","voiceIndex":79,"id":"exchange-016"},{"speaker":"のだて委員","kind":"確認","question":"今、千葉県との確認書が国土交通省と交わされたということで、国土交通省のほうがそれを理由に元のルートに戻せないということを言っているようですけれども、区としては、この確認書をどのように認識されているのでしょうか。午後３時から７時の間、千葉県の上は飛ばないということで確認をされておりますが、そうすると、新ルートが固定化されかねないと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"私、こちらを所管してから３年、その中では、オープンハウス型説明会、区内１３地域全域で教室型説明会も実施していただいております。その中で、国のほうからの説明の中には、騒音を首都圏全体として共有するという説明はなかったかと記憶しています。","voiceIndex":82,"id":"exchange-017"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、そういう千葉県のところで悩みがあったということは知っていたけれども、確認書ですとか、説明会では首都圏全体で騒音を共有するという目的では説明されてこなかった。今、私が伺ったのは、確認書はご覧になっていらっしゃるかと思うのですが、これが品川の上を飛行するということを固定化する、新飛行ルートを固定化するということにならないのかと、区としての認識を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その確認書の内容を見てございませんが、基本的には区が要望したことについては、国はしっかり受け止めて回答いただいて、検討していくとしていただいておりますので、それを今後も強く求めていきたいです。","voiceIndex":84,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認書を見ていないということでしたので、ぜひそれは見ていただきたいと思いますし、国土交通省にもその説明を求めていくべきではないかと思いますので、ぜひそういった要望もしていただきたいと思います。それと、新ルートの固定化については、国のほうは取り組みをしていくと言っているということですけれども、千葉県との確認書を守るということになると、固定化しかねないということがあると思うのです。","respondent":"鈴木都市計画課長","answer":"そうした中で考えますと、これは国のほうでしっかり検討をしていただけるものだというところでの区の受け止めです。","voiceIndex":86,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"この羽田新飛行ルートの中止を国土交通省に品川区として、ぜひ区長を含めて求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"幾つかお伺いしたいのですけれども、まず、要望書の作成プロセス、過程をお知らせください。","respondent":"鈴木都市計画課長","answer":"要望書の作成過程のご質問ですが、実機飛行確認、あるいは３月２９日の本格運用開始以降、区民の方からいただいている声を踏まえてこの要望書について作成をしているわけですが、基本的には部のほうで、所管である都市計画課で作成をして、決定を取って、当日。","voiceIndex":90,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"この要望書の中にある区民の声、このような声も確かにあります。ただ、そのほかにも、やはり羽田新ルートを飛ばさないでほしいといった声が多く寄せられていたと思います。そのような声が反映されていないということはなぜなのかというのを伺いたいです。","respondent":"鈴木都市計画課長","answer":"そうした声は、先ほどご答弁差し上げたとおり、その一つひとつを国のほうには届けてありますが、先ほど区のスタンスをご説明したとおり、区民のそうした声を受けて、区のほうで中止を求めるということは、決定前、あるいは本格運用開始以降も、これは国策ですので。","voiceIndex":92,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"区民からいただいた声を踏まえて要望書を作成しているということでした。そして、先ほどのご答弁の中で、要望書の中にある「従前ルートへ戻すべきなどの声もあり」、この一言を入れたのは、従前に戻す、３時間をもっと短くという趣旨で示している。そして、それが公文書として残るのですから、きちんと訴えるべきところは訴えなければいけないと思うのです。そのところに関してお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"固定化についても、都心上空を飛行することがない、固定化しないでほしいというところをしっかり明確に書いてありますので、固定化しない取り組み、方法がどういったものがあるかというところは、国のほうでしっかり検討いただくべき内容だと感じているところです。","voiceIndex":94,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"だから、きちんとここの要望書の中で、容認できない、飛ばせられない、品川区としては認められないといったことをきちんと示すべきだと思います。そのことについて伺いたいのと、あと、先ほどのお話の中で、千葉県の確認書についてなのですけれども、確認書を区として知ったのは、要望書が出される５月２０日以前だったのか、以後だったのか、お知らせください。","respondent":"鈴木都市計画課長","answer":"区が伝えるべきことは、落下物、騒音環境という中の一つに、これは国策だからといって、この上空を飛ぶこと、これで海外とのつながり、あるいは国際線を増便していくものを、今後ずっとこれを固定化してこの機能強化を続けていくのではなくて。","voiceIndex":96,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"住民や、住民以外にも、品川区に来る方たち、みんなの生活や命、財産が本当に影響していることなので、自治体としてきちんと声を上げるべきだと思います。この要望書を出す前に、確認書の存在を知ったということでした。区として、千葉県と国の確認書のことに関してももっと言うべきことは言わなければいけなかったのではないかというのはとても思うのです。意見を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"この声をしっかり国に届けて、その不安を解消、払拭していただくための取り組みを進めていただくというところが区のやるべきこと、これまでも実施してきたことで、今後もしっかり行っていかなければいけないと考えています。","voiceIndex":98,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"５月２０日以前に確認書のことを知って、それから要望書を作ったということだったので、次にまた要望書を書くときには、この言葉で趣旨が伝わるだろうといった書き方ではなく、従前に戻してほしい、３時間よりもっと短くしてほしいといった区としての考えを、都心上空を飛行することがないようにといった文言をきちんと書くべきだと思います。そういった声もきちんと届けてほしいと思います。","respondent":"鈴木都市計画課長","answer":"固定化についても、固定化することがない取り組みをしていただきたいと。固定化しない取り組みというのはどういったものがあるかについても、これもその中身を国のほうでしっかり考えていただくというものと考えています。","voiceIndex":100,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、その文言を、区としての趣旨をきちんと次からは要望書に書いていただきたい。多分、きちんとこの１０分間の会議については記録をしていると思うので、そういったものもきちんと残してほしいですし、公開もしてほしいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"当然ながら、委員お話しのように、今後様々な場面で、様々な機会を捉えて、区としても要望していくことになりますので、そうしたやりとりについては、しっかり記録として残していくと考えています。","voiceIndex":103,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"今までの議論を踏まえた形で質問しますが、非常に心配なことがあります。それは、この要望書は、いろいろ考えた中でまとめられたのでしょうが、非常に意味不明なところがたくさんありまして、例えば、記書きの下に、新型コロナウイルスへの対応ということで、就航需要の減少を踏まえ、一層の騒音軽減策というのは何ですか。よく分からない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"ということは、本当にここで示された文言というのが、どこまで国土交通省の考え方と一致しているのかどうかというのは、確認しておかないといけないことなのではないかと思うのです。そうなったときに、区が言っている思いと、国土交通省がこのように書いてありますけれども、本当にそれが一致しているのかという確認はしていかなければいけないことなのではないのでしょうか。非常にそこが心配です。","respondent":"鈴木都市計画課長","answer":"それをどうした場でということになるわけですが、４月から組織化して、しっかり区のほうでも看板を掲げて、区民にも分かりやすいように、国に対してもしっかり伝えていけるように組織化しましたので、これはあらゆる機会を捉えて国とはその確認をしていきたいと思いますし。","voiceIndex":106,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"この文章を見ると、本当に不安で仕方がないのです。どこまで本気でやるのか。どこまですり合わせができている話か。そこには敏感になっていただきたいと思いますし、この建設委員会が担当になるわけですから、建設委員会の中には、しっかりとこれは新しい文言だということの認識を強めていただきたいと思います。なので、ぜひ今後の取り組みをしっかりとしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"ごめんなさい、１点だけ確認し忘れていました。発言要旨の中にある、「落下物対策を目に見える形で前に進めてほしい」という要望ですが、国は落下物はゼロにはできないと以前から言っているのですけれども、その中でこのような要望を出して、どのような回答があったのかというところを伺いたいのですけれども。","respondent":"鈴木都市計画課長","answer":"その意味で、これからもしっかり求めていかなければいけないところですが、国のほうでも、先ほどの打ち出した様々な取り組みのしっかりした履行については行っていくというところとともに、これは落下物と騒音については、区だけではない、ほかの自治体についても。","voiceIndex":110,"id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"検討ということは、やはりいまだに国としては前進していないということでいいですか。確認をさせてください。","respondent":"鈴木都市計画課長","answer":"国の受け止めは、区のあるいはほかの自治体の求めに対して、今後も検討、取り組んでいきますという回答をいただいておりますので、国の受け止めも、“今の打ち出しているもので終わりです”という認識ではいないと理解しています。","voiceIndex":112,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"つまり、落下物対策が今以上は進んでいないということですよね。検討していくというのは、いつも検討だと思うのです。その検討状況を知りたくて。この要望も、目に見える形で前に進めてほしいという要望ということは、そういったことだと思うのです。ですので、区として求めている落下物対策に対しての要望は叶っていないということでいいですか。","respondent":"鈴木都市計画課長","answer":"やはり落下物というのは、どんな取り組みをしても、本当になくなるのでしょうかというところは、区民の方からの声としては非常に大きいわけでございまして、その取り組み状況をしっかり示していただいた上で、さらにこれで立ち止まるのではなくて。","voiceIndex":114,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、今回求めたことで、航空局長からは、首都圏全体での騒音の共有ということがあるので難しいという回答だったということだったと思うのですけれども、そういったことであれば、やはりここで一歩また踏み出していただいて、ぜひ中止の立場に立っていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、さらに一歩踏み出さないと、固定化されてしまうと。固定化をしないように求めた実効性がなくなってしまうと思うので、中止の立場に立っていただきたいということで、改めてそこのところを伺いたいと思います。ですから、少なくとも今、減便になっているこの段階で中止を求めるべきだと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"羽田新ルート計画、実施につきましては、これも再三ご答弁申し上げていますが、国策でございまして、区として中止を求めるというところは考えてございません。基本的には、区民の不安払拭に向けた取り組みをこれまでどおり、今後もしっかり求めていく。","voiceIndex":118,"id":"exchange-035"}]},{"id":"topic-03","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ご説明ありがとうございました。新たに着任された部長が、自衛隊の任務を経験した上で着任するということだと思いますけれども、区の災害対策部門の責任者という職において、どのような活動をしていくのか、部長の考えを伺いたいと思います。町会のない公園で、先ほど旗の台の説明がありましたけれども、今後、進めていく方針というのはどのようになっているのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、認定ＮＰＯ法人の全国災害ボランティア支援団体ネットワークが「新型コロナウイルス避難生活お役立ちサポートブック」というのを出しておりまして、避難所運営で留意点は、今、お知らせしているということでしたが、こうしたパンフレット、冊子を配布するなどして、避難所での対応を示していくということが迅速に対応できるようになるのではないかと思うのですが、いかがでしょうか。","respondent":"中島防災課長","answer":"防災区民組織に通知した内容につきましては、今、委員ご指摘のありましたＮＰＯのマニュアル等も参考にしまして、作成しています。","voiceIndex":160,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"１つ目です。どういうものなのかを、この委員会できっちりと報告していただきたいと考えています。そして、最後に、都市環境部のほうでも言いましたけれども、都市環境部よりは都の補助金等との関係はあまり大きくはないのか、影響は起きないのかと思うのですけれども、その関係はどうなのでしょうか。それも含めて今後事業は展開していかなければならないと思っているのか、その辺のお考えをお聞きしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"その件に関してですが、この５６ページにある水族館顧客満足度満点プロジェクト検討委託というのが何なのかというだけでも結構なのですけれども。今後の水族館のあり方を検討していくということなので、どういう考え方でということを問うのはやはり難しいですか。行財政改革特別委員会になりますか。〔「当たり前だよ。","respondent":"塚本委員長","answer":"それはやはり水族館ということで、これは行財政改革特別委員会ということで決まっているので、こちらで、要するに、「しながわ水族館」という言葉が出るということがふさわしくないということだと認識しております。","voiceIndex":165,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり６月になっていますので、水害も出てくるでしょうし、避難所ということでの新型コロナウイルス対策というのは緊急に必要なことですので、ぜひとも早急に報告としてまとめていただきたいと要望します。ただ、品川区にとってはどうかといった場合には、やはり“ここは何とかしてほしい”という要望が多々出てくるかとは思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"１点だけ。防災課の７２ページの２、品川区地域防災計画なのですけれども、今年度の修正について、要配慮者利用施設などを記載する予定ということなのですけれども、このほかにはどのようなことが予定されているのか、もしご説明できるようでしたら、お願いします。","respondent":"中島防災課長","answer":"地域防災計画に関しましては、毎年度、見直し等を防災会議で行っておりまして、今年度はこちらに書いてある要配慮者利用施設というのが具体的なもので、今後、事業等を進めていく、国の動き等で必要なことについては防災会議のほうに諮って。","voiceIndex":172,"id":"exchange-041"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど新任の災害対策担当部長のご答弁の中で１つだけ確認をさせていただきたいと思います。そこらのところ、どのように思われているのか教えてください。もう一回、ご決意というか、私の受け取り方ではないのだということを示していただきたいと思います。","respondent":"滝澤災害対策担当部長","answer":"私、１５歳から自衛隊に入隊しておりまして、そのときの職業選択は多分父親の意思でしたのかなという中で、初めて自分の意思で職業選択をさせてもらったということで、強い気持ちをもって今回、品川区に就職をさせていただきました。","voiceIndex":174,"id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"職業、就職ということですが、やはり国を守る防人としての職務、任務であられるわけでありまして、職に就くというよりも職に奉ずるという心構えでされたほうが私はいいと思いますけれども、どのようにお考えですか。イメージのチェンジ、あるいはステージが変わったわけですから、そこのあたりの考え方を、もう一回、私の話を受けて、感想を聞かせていただければと。","respondent":"滝澤災害対策担当部長","answer":"まさに職に奉ずるという意味で、同義だと考えています。","voiceIndex":176,"id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２点伺います。１点目は、先ほど都市環境部でも伺ったのですけれども、新型コロナウイルスの件があって、都市環境部でも一緒で、全庁的に今、中止または延期、こういうことがあったときの不用額、マイナス関係、これを必ずしっかりまずピックアップをしろということがある。どれぐらいのレベルを考えていらっしゃるのか。そこをまず教えていただきたいと思います。","respondent":"溝口道路課長","answer":"区内事業者含めて、いろいろ様々発注していかなければならないと考えているところです。今年度、皆さんにご審議いただいて、予算がついているところもありますし、私どもも計画的に事業を進めていかなくてはいけないところではあると考えております。","voiceIndex":178,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"よろしくお願いします。それから、もう一点伺いたいのは、先ほど来、災害対策担当部長の話が出ているのだけれども、私はぜひご活躍いただけることを期待しています。それは、机上で作って、どういうことがあっても、直していく。それが動くのか。それはいつのときからか。ここから発信して、“私たちに仕切らせろ”ぐらいの話があってよかったような気がするのだけれども、どうかというところを聞きたい。","respondent":"藤田防災まちづくり部長","answer":"組織のあり方についても、これがゴールということではなく、一歩ずつ前に進めていければと考えています。","voiceIndex":180,"id":"exchange-045"}]},{"id":"topic-04","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"私は、今結構いろいろ言ったので、防災関係は何らかの形で。そういうのを我々が学ぶ機会があってもいいのかというところもあるので、そういうところも含めていただければと思います。最初のほうは、どうして防災というのは、一番私は計画のあり方というのが、先ほども少し言ったのだけれども、それが必ずあるので、そこら辺を含めてもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-046"},{"speaker":"大沢委員","kind":"提案","question":"立体交差事業。戸越公園しかり、北品川のほうもしかりということで、どうしてもこれ、国の財源、あるいは企業の財源に頼るところが多いと。しかしながら、国の事情によって、立体交差事業の進捗状況が変わってくるところもあって、そこらに左右されないような体制づくりが必要だと思いますので、立体交差事業について調査・研究をすべきではなかろうかと思って、今、提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"昨年の現状報告を見すると、「まちづくりの進め方について」ということがあるのです。その中に、先ほどの立体化の事業もあれば、いろいろまちづくりに関連する、集中して研究するというところが含まれるかと思いますので、そういう視点でお願いしたいというのが１点と、もう一つが、羽田の件です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4292#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":60508,"voices":192}},{"id":"r02-20200608-9","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"文教委員会","time":"午後 １時００分～午後 ３時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１の幹部職員紹介","agenda":"の１の幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけと申します。１年間どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"の２の事務事業概要","agenda":"の２の事務事業概要","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"先ほど、コロナの話も出ましたので、私から１点お伺いしたいと思います。コロナの関係で、学校の関係が非常に不安定になっている部分が多いと思うのですが、それはまたおいおい伺うことにして、高校入試です。都立高校の入試もやはり休校に配慮して方針を示すということが都教委から５月に示されていると思うのですが、そのときに６月の上旬から中旬にかけてそうしたものを示すという通知だったと思います。","respondent":"矢部教育総合支援センター長","answer":"私どももまだ待っているところですので、周知の必要がありましたら、早急に学校に通知していきたいと思います。","voiceIndex":28,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"区教委としては、これをどのように定めているのか、また定めていこうとしているのかを１点目にお伺いしたいと思います。そこら辺について改善の必要があると思うのですけれども、そこら辺についてもお伺いしたいと思います。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"大きく２点目の３密の状況ですが、まだこれからの感染状況にもよりますけれども、今は半分ずつ来ていますので、マスク着用、消毒、できる限り距離をとって、屋外での活動というようなことで工夫をしていますが、今後は状況を見まして。こちらが、例えば今回の事態を受けまして法改正等あれば考えていく必要はあろうかと思いますけれども、現時点では、そういった考え方がまだ示されてございませんので。","voiceIndex":30,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"学びの保障と安全の保障は、ある意味、両立させるのは非常に難しいとは思うのですけれども、両立させていかなくてはいけないテーマだと思います。２点目は、人事考課制度ですけれども、つまるところ、教員をある一定の基準で評価して、それを待遇に反映させるという制度があると思うのですが、これが品川ではどのような内容になっていて、また、どういう状況になっているのか伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"１点目の職員会議のことです。名称は「職員会議」がほとんどで通用しているところだと捉えております。内容は、２か月単位のところもあると思いますけれども、月別の行事についての確認というところが中心になるかと思います。人事考課についてのお尋ねですが、私どもは東京都教育委員会からもご指導いただく中で評価者訓練等も行いながら、教員のいわゆる業績評価等につきましては、日々の教員の職務行動等に照らしながら、客観的に公正的にできるように。","voiceIndex":33,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"やっぱりなかなか長時間労働があって、裁量権がない職場が非常に苛酷な現場になって、メンタル問題が出てきますし、それが子どもたちに直接接する教員なわけですから、教育の質にもつながっているという点で、私は、職員会議が形骸化していないかというような問題意識も持っていまして、自由に教員同士が悩みや意見交換ができているのか、どれぐらいそういう場になっているのかという問題意識があるので。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"１点目について付け加えします。分科会がありますので、一堂に会すというのは、多くても月１回というふうに認識しております。あくまでもその目標に対してどの程度達成したのかということが評価されるものですので、いわゆる評価基準が一定したものを当てはめるということではなく、あくまでも当初、自分が設定した目標に対して、では、達成度がどうだったのか。","voiceIndex":36,"id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、いわゆる校外施設、修学旅行的なものは、移動教室とか夏季施設の利用のこの２点しかないということでよろしいのですか。","respondent":"篠田学務課長","answer":"教育委員会のほうで関わりを持っているのは、こちらに書かれているとおり、移動教室と夏季林間学園になります。修学旅行に関しましては、各学校が独自に企画をして実施をしているというものです。","voiceIndex":39,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。先ほどのお話ですと、移動教室と夏季施設の林間学園は中止ということなのですけれども、やっぱり修学旅行も、親御さんの中には、非常にコロナウイルスの感染を気にされている方がいらっしゃいまして、各学校のご判断ということなのですが、現状、修学旅行の中止とかは検討されているのでしょうか。今の状況をお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"お話に挙がりました修学旅行につきましては、極力実施したいという気持ちがあるのは伺っておりますけれども、校長会と検討しまして、６月末には一定の判断を出したいという予定です。","voiceIndex":41,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問・要望","question":"私としては、オリンピック・パラリンピックは当然開催してほしいのですけれども、世界が相手ということと、ＩＯＣの判断ということもありますので、一方で実現するシナリオということを考えつつ、万が一中止というシナリオもやっぱり考えておかなければいけないと思うのですが、そうした場合、せっかくのオリンピック・パラリンピック学習を、中止の場合。","respondent":"工藤指導課長","answer":"そういった意味では、今後のレガシーということにつきましても、先ほど申し上げたような点は、オリンピック・パラリンピックを契機に、よりそれを学校教育の中でしっかりしていこうという位置付けですので、大会が実際にどうなるかというのはありながらも。","voiceIndex":43,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"学校の改築とか施設整備工事ですけれども、今のコロナウイルスの感染の中、やはりほかの民間においては工事が遅れるとか、そうした悪影響が出ているのですが、学校の改築、施設整備工事においては、コロナウイルスの影響はあるのでしょうか。","respondent":"小林学校施設担当課長","answer":"現在のところは、予定どおり目標に向かって進めているところです。","voiceIndex":45,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう１点教えていただきたいのですけれども、学校の出席ですが、今の段階では、既にもう出欠はとっているのでしたか。これ、自治体によってちょっと違いがあったと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"出席につきましては、登校が始まってございまして出席日になりますけれども、お休みしても欠席にはなりません。今回はそういう扱いでおります。","voiceIndex":47,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"これは、６月中は分散登校でずっとそういう考え方ということでよろしいのでしょうか。今後の方針は、どのようにお考えでしょうか。併せて教えてください。","respondent":"矢部教育総合支援センター長","answer":"６月、７月も同じ考えです。授業日数は、学年に応じて同じ数を本区の子どもたちに通ってくるようにです。","voiceIndex":49,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"いわゆる１学期中といいますか、少し時期が延びると思いますけれども、夏休みに入るまでは少なくともそういう考え方ということでよろしいのでしょうか。登校選択制という考え方も今ちょっと出てきているみたいなのですけれども、それについて何かお考えがあれば併せて教えてください。","respondent":"矢部教育総合支援センター長","answer":"登校の選択というのは、様々な形があるかと考えておりますが、今、東京アラートも鳴っているところですので、まず子どもの安全第一ということと、先ほどお話がありましたが、学力の保障という両方を協議しながら慎重に進めてまいりたいと思います。","voiceIndex":51,"id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"２点お聞きしたいのですが、まず１点目に、ＩＣＴ推進ですけれども、今回のコロナの感染拡大を受けて、先ほどもお話がありました１人１台タブレットということも進めてくださっているのですが、そのＩＣＴ推進の全ての検討の中で、長期入院されている児童に対してだったり、あと現在は特別支援学校に所属していて訪問教育を受けている在宅の方とか。","respondent":"篠田学務課長","answer":"現在、とにかく品川区の児童・生徒全てのお子さんに配布できるようにという形で、まず機械のほうの整備を考えてあります。具体的に個別のお子さん方にどのような形でフォローができるかというのは、これから先、丁寧に検討してまいりたいというふうに考えているところです。","voiceIndex":53,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"本当に今進めている、これからだと思いますので、まだまだ先だとは思うのですけれども、特に在宅のお子さんは保護者の方がちょっと遠慮されたりして、特別支援学校にしか行けないみたいな感じで考えている方もいらっしゃるので、制度が整ったら、そこから周知のほうも同時にしっかり、こういう制度があるとか、そういったことの周知も、制度が整ってからですが。","respondent":"工藤指導課長","answer":"そういった外的な要因で遅くなるということをできるだけなくしつつ、あとは先生方がご自身の働き方の質を高めていく、授業の質を高めると同時に、教材研究も質を高めて進めていただければというところで。","voiceIndex":55,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"子ども未来部での最重要課題の１つは保育園の待機児童問題だと思うのですけれども、その実態を正確に把握するということは重要だと思いまして、今日は考え方を伺いたいのですけれども、先ほど、９５ページに待機児童数が１３人ということでしたけれども、改めて待機児童数とはどういう数字なのか教えていただきたいのですが、この数字は、例年、年末には翌年度４月の申し込みが行われるわけですけれども。","respondent":"立木保育課長、若生保育支援課長","answer":"９５ページにお示しをさせていただきました待機児数ですけれども、これは４月１日入園時の数値ということになりますので、年末に４月入園のお申し込みをした方たちの審査等を一次、二次と経て。今後も何件かさらに開設も、地域ごとで事業者からのお声を頂いているところですので、今後もそういった声をこちらのほうでも検討して開設につなげていきたいと考えています。","voiceIndex":86,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"来年４月も８園の認可保育園の増設を予定しているということですが、待機児童が１３人ということで、それでも８園を開設するということですけれども、これは待機児童の１３人という数字に照らすと、かなり多い数になるわけですけれども、これは待機児童という観点は、つまるところ、実態を反映していないということになるのかお伺いしたいと思いますし、あと。","respondent":"若生保育支援課長、立木保育課長","answer":"待機児童の１３人に対して来年度開設が８園というのがそぐわないのではないかというようなご質問でしたけれども、現在計画している８園につきましても、今後、就学前人口が増加している、そういった増加に合わせまして。先ほどこちらの表でご説明をさせていただきましたが、４月入園を申し込みいただいた方の中で、一次、二次と審査をしてきた中で、こちらのほうで新規申込者が３,９８８名、その中で内定して入園された方が２,８１３名、いろいろ一次。","voiceIndex":89,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"増設はどんどんしてほしいですし、やはり深刻な実態に対応できるように、認可保育園の増設を進めていっていただきたいというふうに思います。これが１点です。それと児童相談所のところですけれども、４１ページですが、児童相談所を作っていく、子ども家庭支援センターも今年度から新設をしたということで、この関係性といいますか、事業のすみ分け、連携などはどうなっていくのかお伺いします。","respondent":"廣田子ども育成課長、加島児童相談所移管担当課長","answer":"学習会とか家族懇談会も予定しておりまして、なかなか本人にたどり着くことができないので、家族の方を通じて何とか外に出そうというところで、本人自らというよりも、どちらかというと家族を通して本人につながり。今後、課題検討を行っていく上で、支援を担っております子ども家庭支援センターの意見を聞きながら、検討を練り上げていきたいと考えているところです。","voiceIndex":92,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"そういった意味では、直接雇用で常勤で十分な人員配置がないと、なかなか令和６年といっても、人材育成は大変なのかと思っているので、そこら辺はやっぱり重視していく必要があるかと考えていますが、最後は雇用の問題ですか、やっぱり長く続けられて専門性を同じ職場で積み上げていくような環境を整えてあげないと、人がすぐ代わってしまったりすると。","respondent":"加島児童相談所移管担当課長","answer":"児童相談所のそういった専門職の指導育成を担うスーパーバイザーと呼ばれる職員につきましては、児童福祉法および国の通知等において一定の経験年数が求められるところですので、そういった異動の年数ですとか、継続的な人材の確保につきましては、人事部門と協議の上。","voiceIndex":95,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認させていただきたいのですけれども、冒頭で報告していただいた保育園の６月２日現在での登園率を教えていただきたい。ちょっとこの数字を確認させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-019"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれありがとうあります。それで７割程度ということですね。この保育園の再登園開始に当たって、子どもたちの保育が密にならないようにというようなことだったと思うのですけれども、未就学の子どもたちの保育が密にならないというのは一体どういう状況なのかということが、現場でかなり戸惑いがあるみたいなので教えていただきたいと思います。","respondent":"立木保育課長","answer":"例えば、できるだけクラス間で距離をとるとか、例えば園庭で遊ぶ際にも、極力クラスごとに分かれるとか、そういったようなことで、不可能なところはやむを得ずというところもあるのですけれども、極力できることをやっていこうということで指示は出しています。","voiceIndex":102,"id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"ちょっと現場のほうで戸惑いが聞かれたものですから確認させていただきました。もう１点、私立幼稚園ですけれども、区と私立幼稚園の関わり方というのは、なかなか難しいところがあるかというふうに思っております。","respondent":"若生保育支援課長","answer":"ただ、やはり私立というところで言えば、私学の考え方、特に私立幼稚園、品川区内の１８園に関しましては、子ども・子育て支援新制度の移行をしていない未移行園というような扱いでございまして、より独立性の高いといいますか、そういった形で。","voiceIndex":104,"id":"exchange-021"},{"speaker":"横山委員","kind":"確認","question":"すみません、１つ確認をお願いいたします。児童相談所のスケジュールの部分に変更が、見直しをしていくというお話があったのですけれども、説明会の部分のほかに、どういった部分で、全体については令和６年ということで特に変更はないということで確認させていただければと思います。","respondent":"加島児童相談所移管担当課長","answer":"計画説明会のスケジュールについてですが、児童相談所の開設予定年度、令和６年度中については変更はございません。ただ、１月２０日の文教委員会でご報告しましたとおり、当初は６月に説明会の開催を予定しておりました。","voiceIndex":106,"id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、恐らく一番新しい情報で４月２０日の保育課からのお知らせで、登園自粛に伴う育児休業期間の延長など、あと登園自粛における在園資格ですけれども、やはり６月末までということで変わりはないでしょうか。","respondent":"立木保育課長","answer":"やはり勤め先のほうとか、就職が内定している方とか、いつから仕事を始められるかというところは、今の情勢の中ではなかなか調整が難しいという声も届いておりますので、それにつきましては、６月の半ば、間もなく半ばになりますが。","voiceIndex":108,"id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"すみません、今のお話ですけれども、６月、この先、７月まで育休延長できるかもしれないというお話なのでしょうか。そこの関係を教えてください。","respondent":"立木保育課長","answer":"これが終了した場合には、一定程度、財源の担保もなくなりますので、基本的には自粛のお願いがなくなった場合には保育料を頂くことになろうかというふうには考えてありますが、これもまた今後、感染の拡大状況を見ながらという形になると思います。","voiceIndex":111,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"他区の状況を見ると、６月末というのはもうかなり少数派になっていて、むしろ７月あるいは秋ぐらいまでというところが、２３区で言えば、むしろかなり多くなっているかなと思うので、そういう意味では、品川区は延長する可能性もかなり高いということなのでしょうか。お答えできれば。","respondent":"立木保育課長","answer":"そこのところも含めまして検討している最中ですので、決まり次第、またホームページ等で……。","voiceIndex":113,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"児童虐待についてですけれども、コロナウイルス感染拡大の中、今現在で児童虐待相談は今回のコロナウイルスの影響で増えているのでしょうか。状況をお知らせください。","respondent":"崎村子ども家庭支援センター長","answer":"その対応件数が昨年の１０月から今年の３月まで半年ですけれども、約９０件ございました。そういった関係もありますので、一概にコロナの関係で増えているとは申せないところなのですけれども、ただ、虐待対応の件数としては、昨年と比べると増えているといった状況はあります。","voiceIndex":116,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"そういった送致の制度とか、ほかの家庭内暴力とかいろいろあるから、なかなか児童虐待とかというふうに特定して認定するということはできない。内訳ははっきりしないということですが、その分析というか、そうしたことはおやりになる予定とかはあるのでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"そういったところをどのように判断、捉えるかというところは、もう少し検討させていただければというふうに思います。","voiceIndex":118,"id":"exchange-027"}]},{"id":"topic-03","title":"の１に戻りまして、幹部職員紹介","agenda":"の１に戻りまして、幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。１年間どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-028"}]},{"id":"topic-04","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"先ほど、どなたかからもお話がちょっと出ましたけれども、ＩＣＴの活用ということで、今ちょうど国のほうのＧＩＧＡスクール構想があって、それが前倒しというお話もさっき教育委員会からありましたが、このコロナの件も含めて、これから同じようなことが繰り返し起きてくる可能性も高い中で、いち早くそういった１人１台ということもありましたので、またそれが配布というか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5004#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":48439,"voices":124}},{"id":"r02-20200608-5","meetingId":"r02-cm06","date":"2020年6月8日","dateIso":"2020-06-08","committee":"総務委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ概要説明ありがとうございました。総合実施計画についてですけれども、先ほども新型コロナウイルス感染症の影響を見極めた上でというご説明がありましたが、本年度どのような総合実施計画になるのか、いつごろ示されるのか、未確定な部分も含めて、もう少しご説明をいただきたいと思います。","respondent":"佐藤企画調整課長","answer":"総合実施計画の策定の見込みですが、委員ご紹介のとおり、今は新型コロナウイルス感染症の感染が今後どうなるか、見極めが必要な状況でありますので、我々としても先延ばしするつもりはないのですけれども、実施計画に関しては成果目標をきちんと出して。","voiceIndex":36,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"併せて、前回も言いましたが、新型コロナウイルス感染症対策の財源を確保する上でも、いわゆる不要不急の事業は中止または延期とする対応が必要だと思うのですけれども、東京都が５月に依命通達を出しておりますが、これらに則って、どのような事業を対象にするのか、不要不急の事業の対応について、何か考えを持っているのであれば、その点も伺いたいと思います。","respondent":"品川財政課長","answer":"今年度の財政状況ですけれども、確かに３月補正、それから４月、５月と補正をしまして、今回の第２回定例会でもかなりの額の補正をするという予定になってありますが、全体的に新型コロナウイルス感染症の状況がどのように動くかというところが見えない中で、財政状況も随時。","voiceIndex":38,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、今後、東京都との交渉にもなるのでしょうけれども、財政調整交付金は、やはり金額が減になるという見通しなのか、またこの財政調整交付金だと新型コロナウイルス感染症に関わる費用というのは、どこまで対象となるのか、またしたいというふうに区は考えているのか、国からの交付金もありますけれども、区が独自に出した１人３万円、中学生未満は５万円という、こういう事業にも活用できるのか。","respondent":"品川財政課長","answer":"財政調整基金の残高ですが、プレスにも出していますように、しながわ活力応援給付金のほうで財政調整基金を使いまして、おおむね基金の残高としましては、２２億円程度になるかと考えております。","voiceIndex":40,"id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"その交付金で今後新型コロナウイルス感染症の部分はどこまで対象になるか、国の交付金も活用できるのかというのは、現状では分からないというか、見通しも含めて不明な部分があるということなのか、そこだけ最後にお願いします。","respondent":"品川財政課長","answer":"財政調整交付金のほうが、新型コロナウイルス感染症に活用できるかというところにつきましては、これからまた財政調整の交渉の部分に入っていきますので、基本的には令和２年度の財調交渉の中で、基本的には進められていくのではないかと考えております。","voiceIndex":42,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今日は事務事業概要ということなので、あまり具体的なところには踏み込まないようにということなのですが、とはいいましても選挙管理委員会のほうで、もう都知事選挙が迫ってきている中で、新型コロナウイルス感染症への対応というのは、既にいろいろお考えかと思います。今日のご報告からはその辺のことは分からないのですが、今、伺える範囲で検討されていることなどあれば、伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"都知事選の新型コロナウイルス感染症対策ですけれども、５月１９日の総務委員会において、都知事選の執行要領のご説明をした際に、新型コロナウイルス感染症対策についてもご報告をしています。","voiceIndex":44,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"実際、知的障害の方とかで投票にいらした方が、品川区の選挙ではとても丁寧に対応していただいているということを伺っています。ただ、どうしても障害者への対応というのは密にならざるを得ないとか、そういうことが出てきてしまうジレンマがあるわけです。その中でもぜひ投票していただきたいというところで、何か工夫されていることがあれば、伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"ご相談があった際は、比較的余裕のある期日前投票所のほうをご紹介したり、そういう形で合理的配慮の上、障害者の方も投票ができるような対応をとっていきたいと考えています。","voiceIndex":46,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、感染防止は万全にしながら、やはり投票率は下げたくないと思いますので、ぜひその辺の啓発をよろしくお願いします。選挙ということであれば、ある意味期間限定ですから、その辺については、個別対応と言うことだけでなく、音声による案内ということもぜひ、視覚障害者の方たちに向けて行っていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問","question":"ご説明ありがとうございました。広報広聴課のところで、お伺いします。できれば電話でも相談ができたらというお声もあるのですが、電話相談もなく、この専門相談が中止になってしまったという、その考え方をお聞かせいただければと思います。","respondent":"大澤広報広聴課長","answer":"専門相談につきましては、各団体との話し合いによって電話を受ける場所がなかなか確保できないのですとか、状況を聞いて、電話で相談を受けられないという団体の結論を受けて、その期間は中止にしていたものです。","voiceIndex":49,"id":"exchange-008"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。今後、またこれからもこのような状況になったとき、今回のことを受けて、何かできるような体制もぜひ、ご検討いただきたいと思います。新型コロナウイルス感染症の影響を受けて、やはり専門家に相談をしたいというお声がありました。そういうこともぜひご検討いただきたいと思いますが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"相手の団体があってということですので、区のほうで一概にこのようにすると決めるのは難しい部分もあると思いますが、相談のニーズがあったということは認識していますので、今後検討してまいりたいと思います。","voiceIndex":51,"id":"exchange-009"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"何とか感染防止をしながら開設できないかと思っていましたけれども、こうした状況のもとで、残念だということをお伝えしておきます。区民への周知だけは、ぜひ徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-010"}]},{"id":"topic-03","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"新型コロナウイルス感染症については、この後の報告事項のところで別に質問したいと思います。男女共同参画について、行動計画推進会議がこの間開かれており、今年もということで、今年に答申が出るということでよろしいのか、どのような意見や提案、方向性が示されているのか、概要を伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"７月に一度お会いできるような会議体を設定する予定でおりまして、各分科会から報告をいただきます。予定ですと３月にはというところですが、新型コロナウイルス感染症の関係で、若干延びますかどうかも確認しながら、様子を見ながら開催する予定です。","voiceIndex":94,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういった方向性や議論の内容なのか、当委員会にもぜひ報告していただきたいと思いますので、よろしくお願いいたします。ちなみに、パブリックコメントをかけるのですか。多様な意見が反映できればと思うので、その点だけ伺いたいと思います。これは、いわゆるＤ案は決定事項ということなのか、誰がどのようにＤ案を決めたのか、伺いたいと思います。","respondent":"島袋人権啓発課長、濱中庁舎計画担当課長","answer":"行動計画推進会議におけるパブリックコメントの実施ですが、今までパブリックコメント等は実施しておりませんので、今後も予定はしておりません。特にワンストップ窓口ですとか、保健衛生機能、教育機能、文化スポーツ機能ありますが、区民の皆さんが使われる窓口ですとか、そのあり方といった部分も、庁内の検討ＰＴで検討いたしまして、それを基に庁舎機能検討委員会で。","voiceIndex":96,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ幅広い意見が反映できるように、今後工夫していただきたいと、要望したいと思います。先ほど伺ったのは、誰がどのようにＤ案を決定したのかということを質問しましたので、改めて伺いたいと思います。陳情の中に載せられておりますので、その中でも経過が分かるような資料をぜひ示していただきたいと思いますけれども、その点だけ改めて伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"ほかになかなか候補地が見つかっていない段階で、Ｄ案が最有力であろうということで、区として考えているところです。","voiceIndex":99,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点だけいいですか。会計管理室に伺いたいのですが、前回のその他の中で１４億円のことが報告であって、再発防止等の対応をしていただきたいと思いますが、その後どういう経過になったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"経理課と会計管理室のほうで伺いたいのですけれど、最初に経理課の契約のところです。２７ページに契約係の表がありますね、この下に「契約金額が確定できない単価契約は除く」とあるのですけれど、それは件数からも金額からも、全部除かれているということなのでしょうか。単価契約というのを、具体的に一つか二つ、例示していただけると分かりやすいのですけれど。","respondent":"東野経理課長","answer":"これが予定数量を年間でどのぐらいかけてとか、そういう形になってきますので、それが確定していないものにつきましては、この表から除いてあると、そういうふうに理解いただければと思います。","voiceIndex":104,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"例えば今の公園の木の剪定などになると、工事でも、物品等ですか、何になるのか。は個別に伺うしかないかなと思いますけれど、事務事業概要ということでありますが、この単価契約のボリュームがどれぐらいかによって、この表の中に占める割合はどうなるのかと思いましたので、その辺をちょっと。今お答えできないようでしたら個別に伺いたいと思いますけれど、ぜひ教えてください。","respondent":"東野経理課長","answer":"例えば先ほどの樹木の剪定の場合ですと、樹木を剪定する頃に業者へ発注するという形になりますので、それが例えば１０回、２０回となりますと、それが一つの契約として数えられるかどうか、そういったところが判断の材料になってきますので、それが全部が全部。","voiceIndex":106,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"個別に伺うことがあるかと思いますが、そのときはよろしくお願いします。そういったときに「導入に関すること」というのは、どういう意味なのかと。私、この１ページの表を見た段階では、新公会計制度が導入されて、今までそうでなかったものが日々仕訳になってということだったので、むしろそういう役割のことなのかなと思ったのですが、それは違って、出納係がその役割になるのでしょうか。","respondent":"中山会計管理者","answer":"年度末にならないと分からないようなものとかもありますので、そこをどういうふうにすると一番きちっとした形でできるのかというのを、まだ模索しながらやっているところです。","voiceIndex":108,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。ただ、そうなると兼務ということでは、ほかのお仕事をしながらこれもやっていらっしゃるということで、結構今、ご説明を伺うと大変なお仕事かなと思うのですが、ほかの別のお仕事もやりながらということで、よろしいのでしょうか。","respondent":"中山会計管理者","answer":"兼務２人というのは係長を充てているわけですけれども、その係長だけでやっているわけではなく、他の職員も含めて仕訳の相談ですとか、どういうふうにやっていくかということは、会計管理室全体として対応しています。","voiceIndex":110,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"品川区では今、一部の方がやはり在宅ワークをされていると思うのですが、そういう中で、区民サービス、区民対応は十分にできているのかどうか。同時に、先ほど申しましたけれど、職員の方も実際の仕事において、区民サービスとしてきちんと対応できているのか、さらに残業代が、今はローンの返済だの様々な生活費の一部にもなっていたと思うのですが、その辺に対して何か影響というのはでているのでしょうか。","respondent":"黒田人事課長","answer":"在宅勤務も大体、一番多いときでも全体を平均しますと３割ぐらいでございまして、やはり区役所ですので、区民の方がいらっしゃったり、お電話をいただいたりということで、なかなか民間企業のように自宅で仕事をするというところは、非常に難しいというのが現状としています。","voiceIndex":112,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"もう一つ、例えば区の仕事を委託なり、派遣の方に協力してもらって、様々な事業を支えていただいていると思うのですが、その人たちに対する影響というのはないのですか。その辺の大まかな人数とか予算が、これぐらいの規模でやはり減りましたとか、そういうものは大体把握されているのでしょうか。","respondent":"黒田人事課長","answer":"当然、委託でありますとか、派遣ですとか、事業の見直しによっていわゆる成果が変わる部分については契約の見直し等もあると聞いておりますし、派遣のところで申し上げますと、新型コロナウイルス感染症の電話相談センターでは、逆に医療従事者、保健師、看護師は増員して。","voiceIndex":114,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"あるときは必要だから来てくれ、こういうときは要らないというのだと、その人たちの生活にも関わってくると思うので、それでお聞きしたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。それと、庁有車のマイクロバスなのですけれど、こういう状況下で出庫する回数というのは当然減っていると思うのです。職員の方がアイドリングをしておられると思うのですけれど、現状では、視察などでマイクロバスを使用していないと思うのですが、管理はどういうふうにされているのか、お聞きします。","respondent":"東野経理課長","answer":"今後、経済活動といったところで、新型コロナウイルス感染症が終息に向かいましたら活用も増えてくるだろうと思われます。今のところはあまり活用がないような状況です。","voiceIndex":119,"id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"意見","question":"分かりました。それでその整備は、例えば今、使用していないからバッテリーを外している状態にしていますとか、職員の方がアイドリングを毎日かけているのか、いざ出庫のときに、バッテリーが上がっていたら困ってしまうので、その辺どういうふうに整備されているかと思ったのです。","respondent":"東野経理課長","answer":"庁有車ですので、出庫する場合、外に出かける場合などに支障のないようにというところで管理を行っているところです。具体的にどういう管理を、というところまでは今、申し上げることができませんけれども、支障のないような管理を行っていきたいと思ってあります。","voiceIndex":121,"id":"exchange-023"}]},{"id":"topic-04","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"新型コロナウイルス感染症対策本部の対応について、幾つか伺いたいと思います。第２波、第３波に備えても、こうした検査や支援というのは引き続き大事だと思っています。区としては、この感染抑止と社会経済活動の開始を一体的に進めていくためには、何がどう重要だと思っているのか、基本的な認識を伺いたいと思います。","respondent":"立川総務課長","answer":"ご案内のいわゆる医療であるとか検査体制というのは、基盤として今後とも最重要事項であるとともに、東京都や国から打ち出されました「新しい日常」であるとか「新しい生活様式」、こういったことを、区としましては周知に努めてまいりたいと考えているところです。","voiceIndex":128,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"同時に最前線で感染対策に奮闘されている医療従事者への支援も引き続き必要だと思います。やはりそこで検査についてなのですけれども、医療従事者、公私および認証も含めた保育園の職員、学校の職員、介護や障害者施設の職員などに対してのＰＣＲ検査を定期的に実施し、区民そして職員の安全安心をつくることも、新型コロナウイルス感染症対策本部で検討していただきたいと思うのですが、いかがでしょうか。","respondent":"立川総務課長","answer":"現在のところ、健康な職員等に対してＰＣＲ検査を実施する考えはございませんが、今後の国や都の動向といったものを踏まえまして、この辺については考えていく必要があるのかなと思っているところです。","voiceIndex":130,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後の動向を見て考えていきたいということですけれども、やはり現に新たな感染も都内で２０人、３０人と報告されておりますし、感染経路が分からないことも明らかになっておりますし、市中感染が広がる中、まずはこういった福祉や学校、医療機関の職員全員の検査を、いち早く実施できるよう強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"残り２５万円ということですが、引き続き対応していただきたいということと、総務課のほうでは検討委員会をつくって調査するということでありますが、原因と予防策についてしっかりと調べていただきたいと思います。前回の委員会でしたでしょうか、ヒューマンエラーという話もありました。それを防ぐための対策も必ずすべきだと思いますので、ひとつよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-027"},{"speaker":"新妻副委員長","kind":"意見","question":"ご説明をいただき、ありがとうあります。残金２５万円余ということですけれども、振込をしていただくに当たっては、振込手数料というのは区の負担になるのかなと思うのですが、その金額がどれぐらいなのか、あらあらの金額がもしわかればお知らせいただければと思います。","respondent":"中山会計管理者","answer":"それから納付書による納入につきましては、１件につき手数料が２円ということで、これらが区のほうの負担になると考えているところです。","voiceIndex":140,"id":"exchange-028"},{"speaker":"新妻副委員長","kind":"質問","question":"そうすると、そういう様々な手数料のトータルは、まだ出ていないということでしょうか。","respondent":"中山会計管理者","answer":"それぞれの方とどういった形で返金をしていただくかという話は、合意が得られているところです。今、きちっとした総合計は出していないのですけれども、３万円以内で収まる見込みです。","voiceIndex":142,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"先ほど総務課が、中心になって調査を行うということだったのですけれど、どれぐらいの期間を見込んでいるかとか、もしあれば伺いたいと思います。それからどういう体制で行っているのか、まさかこれだけに専念するというのはなかなか難しいかなと思うのですけれど、一定見込みを伺えるとありがたいのですが。","respondent":"立川総務課長","answer":"今後３回ほど、第１回は５月２９日に行ったところですが、今後は６月中旬、また７月に２回ほどやりまして、最後まとめていきたいというふうに考えているところですので、７月下旬までにまとめまして、報告につきましてはそれ以降にさせていただこうと考えております。","voiceIndex":145,"id":"exchange-030"},{"speaker":"鈴木（真）委員長","kind":"質問・要望","question":"ちょっと私のほうから。前回の委員会のお話で確認なのですけれど、区が振込手続きをしたと、その後、区にみずほ銀行からまた連絡があったので、もう一度振り込んだという流れというふうに見たような気がするのですけれど、その辺は間違いがないのかというのと、組戻したとき、事務的には依頼をしますけれど、組み戻しというのは区が頼んだのか、みずほ銀行がしたのか、その辺はどうなのか気になっています。","respondent":"中山会計管理者","answer":"前回の報告の中でもさせていただいたのは、やはり会計管理者と指定金融機関との間で、きちっとした確認ができない中で起こった事故というふうに考えています。","voiceIndex":147,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"意見ということで、当然新型コロナウイルス感染症については、所管事務調査になろうがなるまいが、随時報告していただきたいと思いますけれども、一つ目は、新型コロナウイルス感染症対策ということ。それと男女共同参画の中で、行動計画推進会議が、スケジュール的に延びるかもしれませんけれど、答申を出すという段階ですので、性的マイノリティの理解促進が２つ目です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-032"},{"speaker":"湯澤委員","kind":"意見","question":"このたびの新型コロナウイルス感染拡大防止に当たって、東京都が都民に対して最新情報を提供するサイトを早急に立ち上げられたのは、シビックテックの活用があったからだというふうに認識しております。品川区におけるこのシビックテック活用について、調査項目にしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、感染が怖いというのは分かるのですけれど、それによって逆に弊害として、精神的、肉体的な病に陥る、経済活動も、これだけ社会がどん底といったらいいのでしょうか、本当に縮小してしまって、これから休業、廃業、倒産に対する心配ごとがあるならば、やはり区として、少なくとも品川区内はこういう方向で行くのだと、そうしないと子どもたち一つ捉えても、日々子どもたちの一日は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問","question":"当然ながら、終息しても新型コロナウイルス感染症と向き合って、生活様式が変わっていくわけですから、そういった部分で、昨年、令和元年度は広報のあり方についてということで、所管事務調査をやったと思うのですけれど、今年は総務課に自治体連携担当ができたということで、シティプロモーションも含めた連携をしていく中で生活様式が変わっていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"私は先ほどの事務事業概要で質問させていただきまして、若干誤解していたようなところがあるのですけれども、新公会計制度について、導入の前に所管事務調査が行われていますけれども、その後導入して、たしか昨年の予算特別委員会のときに、新公会計制度による決算報告、財務諸表みたいなものが決算特別委員会に出てくるのかという、どなたかほかの委員のご質問に対して、それはちょっと難しいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-036"},{"speaker":"新妻副委員長","kind":"提案","question":"探して、探して、やっとここにあったというような、そういうことではなく、区民が求めている情報が一目で分かるという、今回のことも踏まえて、やはり新型コロナウイルス感染症に関連してしまうと思いますけれども、そのような品川区のホームページのあり方を、一点、提案させていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":159,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言よろしいでしょうか。毎回一言述べさせていただいて、申しわけないのですけれど。今年は新型コロナウイルス感染症の関係で、無観客試合で行われているという中、視察のあり方については十分留意していただいて、ご判断いただきたいと。その点だけよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"まだまだ新型コロナウイルス感染症の感染に関しては、ご存じのとおりワクチンができるのが１年半から２年先、きちんと終息するには数年かかるというお話まで聞いております。その辺、委員長のほうにもしっかり申し上げていきたいと思いますし、私自身もそのときには委員会の方針はあるにせよ、自分の考え方として、信念として、行く、行かないは決断させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"第２波、第３波の議論もある中、あえて総務委員会で現地の視察をするということの緊急性は低いと思いますので、実施する、しないを含めて検討していただきたいと。ストレートに言えば、やらなくていいのではないかと私も思いますので、ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40814,"voices":166}},{"id":"r02-20200609-14","meetingId":"r02-cm06","date":"2020年6月9日","dateIso":"2020-06-09","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時３６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ホームページですと、荏原複合施設には設置施設として４つありまして、荏原特別養護老人ホーム、短期入所施設、荏原在宅サービスセンター、荏原在宅介護支援センターの４つ。それからその他の施設として、都民住宅、荏原健康センター、荏原保健センターの３つがあると書いてあるのですが、第一日野小学校に仮に移転するというのは、今７つあるうちのどの部分が移転するという形になるのでしょうか。","respondent":"佐藤企画調整課長","answer":"旧第一日野小学校に移転する対象の施設ということで、説明が不十分で申しわけございません。","voiceIndex":40,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"その２つに関してはその場に残る、ほかの部分が第一日野小学校に移転するだろうという理解でいいわけですか。それで、説明会を開くとなっているのですけれども、その説明の日程などは決まっているのでしょうか。","respondent":"佐藤企画調整課長","answer":"説明会の日程ですが、まだコロナの関係もあって、なかなか着手できなかったということもあります。今回、こちらの委員会で報告できましたので、今後、所管と詰めて、できるだけいいタイミングでやっていきたいと考えております。","voiceIndex":42,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"荏原複合施設の改修そのものは大規模改修であって、今７つ申し上げましたけれども、それ以上に新たな施設を入れるということではないと理解してよろしいでしょうか。","respondent":"佐藤企画調整課長","answer":"新しい荏原複合施設に関しましては、新しい機能を入れることは現時点では考えていません。","voiceIndex":44,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"第一日野小学校の周辺の方もいろいろ環境が変わりますので、説明会の日程などがわかりましたら、早急にお知らせいただければ、あるいは告知していただければと思います。その点、よろしくお願いいたします。もう一つ、危機管理のところでお伺いしたいと思います。これは一体何なのでしょうか。教えていただきたいと思います。","respondent":"立川総務課長","answer":"こちらは、平成２４年に総務課で作成したガイドラインでございまして、このガイドラインでは、危機管理体制の大枠、指針を示し、また、各課において危機管理マニュアルを作成する際等の指針ということでつくったものです。","voiceIndex":46,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"大抵こういうところに示された文章は、ホームページで検索すれば、かなり細部なものでも出てくるのですけれども、見ることはできないのですか。","respondent":"立川総務課長","answer":"こちらは、先ほど申し上げたとおり、いわゆる内部向けに作成したものでございまして、作成からもう既に７年経っているところです。このガイドラインの公表につきましては、今後、検討していきたいと考えております。","voiceIndex":48,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"危機管理についてというふうに項目として取り上げられるような大事なことですし、危機管理対策ガイドラインということで基本的な文書であろうと思います。ぜひ公表していただきたいと思うのですけれども、いかがでしょうか。","respondent":"立川総務課長","answer":"内容が公表にふさわしいかどうか、検討していきたいと思います。","voiceIndex":50,"id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"区の働き方改革についてであります。国でも新しい生活の仕方を銘打ってきているところもありますので、今後の取り組みの検討について、「Ｗｉｔｈコロナ」と言うのでしょうか。コロナとの共存といいますか、それを踏まえた取り組みについて、少しクローズアップしながら話し合いができればいいかなと考えています。これは私の意見ですので、理事者の方のご答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"水族館の運営についてお聞きしたいのです。実際、これから２０２５年問題もあって、水族館ももうそろそろ年数が来ていると思うのです。例えばそういう予算的なものも提示していただけるとありがたい。恐らく毎年、それぞれ相当の経費がかかっているかと思うのですが、直近で相当の予算を必要とされるのならば、どうなるかなという推移を見たいので、資料を出していただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"「区有施設、公有地等の活用に関すること」の中で、今回、荏原保健センターの仮施設が設置されて、大規模改修を行うという報告がありました。このような形でさまざまな区有施設で、今後、大規模改修の計画がされている。課によっては、いつも遅くまで明かりがついておりますので、区の職員の働き方を考えるにあたり、そういう現状がわかるような数字も出していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"働き方改革のところなのですけれども、結局、私が思うには、ただ単純に時間の話をするのではなくて、例えば事業があって、事業をどういう形で取り組んでいけば、それは時間短縮にもなるし、もっと効率的にこういうことができるよというようなことが、私はまさに特別委員会の役目だと思っているので、そういうところも正副委員長で行政側と話していただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10741,"voices":62}},{"id":"r02-20200610-18","meetingId":"r02-cm06","date":"2020年6月10日","dateIso":"2020-06-10","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけと申します。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"先ほどロードマップという話もありましたけれども、開催の可否が判断される時期、タイムリミットというのはいつ頃になると区は把握していらっしゃるのか、伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私が先ほど発言させていただきましたロードマップというのは、ちょうど今日のお昼のニュースで出ていたものです。１０日に理事会が開かれまして、そこで示されるというふうにニュース等では出ていました。直接的に組織委員会や東京都からの連絡は入っていないところです。","voiceIndex":34,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点なのですけれども、レガシーのところで、１点だけ確認させていただきたいのです。それが１点目です。文化プログラムのほうですけれども、様々いろいろ７５事業が認定されたということだったのです。実施予定などもあったと思うのですけれども、新型コロナウイルスの影響で中止されたものですとか、大会の延期に伴って延期されたものなど、その全体の大まかな開催状況について伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"文化プログラムについてなのですが、今、７５事業ありますというようなご説明を差し上げました。その中で、新型コロナウイルスの影響で中止になってしまったものというところでは、近々のものですと品川薪能は中止になっております。","voiceIndex":36,"id":"exchange-003"},{"speaker":"つる委員","kind":"確認","question":"前期のオリンピック・パラリンピック推進特別委員会の最後のときにも確認させていただいたときに、３階のプラッツァのカウントダウン表示、緊急事態宣言が明けた後にやるか考えるということだったのですけれども、やるのかなと思ったのですが、今はまだ表示はしていないですね。まさに新ロードマップを受けてやるのか、その１点をまず教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"プラッツァのところにあるカウントダウンタイマーの件です。大変遅くなりました。事業者が明日参りましてセッティングをします。よろしくお願いします。","voiceIndex":38,"id":"exchange-004"},{"speaker":"つる委員","kind":"質問","question":"明日、再点灯する。分かりました。そういう意味でやる部分もどのぐらいの量があるのか。それをまず、概略でいいので教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"開催の有無にかかわらず、次にどう残していくかですが、先ほどの説明の中でもお話し差し上げたのですけれども、まず３競技を中心にずっと機運醸成をしてきたわけです。","voiceIndex":40,"id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"逆にエコバッグの作成・配布よりも、ごみを出さない工夫のリーフレットだったりとか、そういったもののほうがいいのではないのかと思ったりしていて、そんなところを伺いたいのですが、いかがでしょうか。","respondent":"提坂環境課長","answer":"使い捨てプラスチックの関連のご質問ですけれども、容器を持参していない方については、ご説明したモールド容器ですとか紙製容器類をお配りして、お持ち帰りいただく。","voiceIndex":42,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"説明ありがとうございました。先ほどつる委員のほうから、庁舎前のカウントダウン表示の確認をさせていただきました。前期の最後に私もその続きで確認をしたことですが、ホームページのほうのカウントダウン表示はいつぐらいから可能なのかというところを１点確認させていただきたいと思います。ちょっとまとめて質問します。区が作成したものをぜひご紹介いただきたいと考えていますが、いかがでしょうか。","respondent":"提坂環境課長、辻オリンピック・パラリンピック準備課長","answer":"今のテイクアウトの関係で、どの程度モールド容器ですとか紙製の容器類を使っているかということは、ちょっと把握はしてございませんけれども、区だけではなくて周辺の自治体とか東京都と連携して。ほかの私どものＳＮＳとか、そちらのほうでカウントダウン等も含めて掲示はしていきたいと思います。","voiceIndex":44,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"私からは１点、しな助についてなのですけれども、ちょっとしつこい話になってきますけれども、やはりボランティアというのは自発的に取り組む、参加するのが楽しい、そういった意味合いがあるのですが、私も含め、やはりどうしてもイメージとしては奉仕活動。そういった部分でこの独自ボランティアの在り方といいますか、改めてどういった位置づけでどのようにしていくのかを教えていただけますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、ボランティアというのはボランティアをする方が与えるばかりではなくて、またそこからリターンというか、Ｗｉｎ-Ｗｉｎの関係性だと考えています。","voiceIndex":48,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"やはりそういった意味でも、このしな助も大会が終わったら終了ではなくて、そういった位置づけに何とか残していくというか、ボランティアレガシーと呼んでいいのか分からないのですけれども、そういった形で残していくことが大切ではないかと思うのですけれども、どうでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのあたりのその方自身のロードマップというのを手助けするのが私どもの役目かなと思いますので、もしもＮＰＯ等を立ち上げたいという方がいらっしゃいましたら、その支援はしますし、あくまでもそのしな助の意向を確かめながら。","voiceIndex":50,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"環境・リサイクルに関することなのですけれども、地球温暖化防止対策の推進だとか使い捨てプラスチック製品の削減、ＳＨＩＮＡＧＡＷＡ“もったいない”プロジェクト等々のこと、今、非常にすばらしい取り組みだと思いますので、ぜひ進めていっていただきたいのですけれども、この環境・リサイクルのことと、オリンピック・パラリンピックを具体的にどうやって結び付けていくのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-010"},{"speaker":"西村委員","kind":"質問","question":"もったいない推進店とフードドライブについて伺わせていただきます。それが１点です。紙で紹介するガイドブックを作られるということだったのですけれども、紙もやはり配布されないとごみになってしまいますので、こういったテイクアウトマップとの連携ですとか、ウェブの展開をご検討されていらっしゃるでしょうかというのを伺わせてください。これは感想です。","respondent":"提坂環境課長","answer":"今２３の商店街のほうで登録していただいているのですけれども、ほかの商店街とも交渉して推進店を増やしていただいて、いろいろな推進事業にご協力いただきたいと考えております。","voiceIndex":54,"id":"exchange-011"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"こんの委員","kind":"提案","question":"この環境・リサイクルというところで、今の活動、どのような状況で町会・自治会が活動しているかという現状とか、課題とか、あるいはその方たちがモチベーションをもって活動していくためにはどうしたらいいかとかいうようなところの取り組みも、この中で取り上げていただけたらという提案なのですけれども、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-012","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"提案","question":"それが１点です。２つ目は、アリーナ・障害者スポーツ施設に関することなのですけれども、議会運営委員会の特別委員会の設置資料には、備考に、「広町現庁舎敷地、パラアリーナ」と書かれてありますけれども、この広町現庁舎敷地にこのアリーナを整備するかどうかというのは決定事項ではないですし、区民的議論や合意もない状況だと思います。これも要望というか提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"趣旨的にはここでお答えがあるのかどうかは分からないですけれども、先ほど私が言った環境・リサイクルとオリンピック・パラリンピックをどう有機的に結び付けていくのかということは、しっかり考えなくてはいけないと考えております。委員会としてはまだそこまで具体的な内容、今後どうするのかというのは詰めていないという理解でよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-014"},{"speaker":"渡部副委員長","kind":"確認","question":"筒井委員もご案内だと思いますが、特別委員会というのは、議会運営委員会でどういう内容でこういうことをやるのだというふうにまず上がって、それをもんでこういうことだから設置動議が出されて委員会を開きなさいよということなので、そもそも関係があるからやるのであって、今、こんの委員からもご発言があったように、例えばそういう活動でも当然レガシーになるわけですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほどオリンピック・パラリンピックが中止になるかもしれないという報道もなされ、当然予定どおり実施されることを望みますけれども、この委員会運営としましては、実施するシナリオと同時に、残念なことですけれども万が一中止になるというシナリオも、両にらみで進めていかなくてはいけないのかなと考えておりますので、そうした２つのシナリオを考えた運営をしていっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":23466,"voices":71}},{"id":"r02-20200612-10","meetingId":"r02-cm06","date":"2020年6月12日","dateIso":"2020-06-12","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"国への要望の１点目、臨時交付金についてであります。当然ながらさまざまな対応を品川区でもしてきたわけでありまして、それに応じた、見合った配分というのを積極的に求めていただきたいという趣旨で、１点目の要望とさせていただきました。２点目、２ページ目ですが、保健所機能の強化に関する要望であります。その中で３点要望いたします。はこの通信経費の支援というのを１点目に求めています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"次、第４位ですが、鉄道連続立体交差事業の一層の推進を求める要望ということで、今さまざまに特別区の中でも鉄道によって影響が出ている部分が多いというところで、品川区もそれに当たって今さまざまなところで立体化事業が進んでいるところですが、国に求めることとして、１として区施工での事業化に対しての地域の実情に合わせた財政的支援の充実ということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私どもからは４本出させていただいています。国だけの要望ということで、羽田新飛行ルート運用に関する要望というところで、２項目です。以下３つについては、国と都両方への要望ですので、あわせて説明します。毎年出させていただいています高齢者施設に関する要望ということで、２０２５年問題というところで、(1)と(2)で２つ出させていただきました。は医療体制の確保というところが１番です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"共産党の提案の説明をさせていただきたいと思います。続いて、新型コロナ感染症にかかわって特定整備路線・市街地再開発事業についての要望ということで、５月５日に東京都副知事より依命通達が出ておりますが、コロナ対策の財源をつくる上でも不要不急な事業として、例えば市街地再開発や街路整備など、こうしたものの中止または当面延期を求めてコロナ対策の財源に振り分けていただきたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"これが国への要望です。３番目に、全国市議会議長会を通じた要望ですが、これは災害時には職員待機寮として、また区民の避難所として、また病人隔離所として、また医療従事者等の宿泊所として利用できる臨時大型施設をつくり上げることを求めます。要望内容は、1)首都直下大地震が近々に起こる可能性が高い。2)大量の避難民が生まれた場合に、区民の一時避難できる臨時大型避難所をつくることを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"２つ目の避難所における感染症対策と災害対策についてと、あと中段より下にある自衛隊中央病院との連携に関する要望など、この２番目の枠の中に一緒にまとめられないかなと。今そんなふうに思いましたので、とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"あえて言うならば、昨年も出しましたが、国民健康保険制度ですね、品川だけでなく全国どこの自治体でもこの負担割合がほかの健康保険組合に比べても高いというところで、やはりここは国民皆保険制度ですから、国がしっかり財政補填を強めていくということは当然の対応だと思いますので、ぜひご検討をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"これだけたくさんさまざまな要望が出ていますので、ではどうするのかという話で、皆さん各会派からの要望の多かったところを主として考えて、委員長、副委員長、また議長ともお話願いまして取りまとめていただいたほうがいいのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-008"},{"speaker":"こんの委員","kind":"意見","question":"先ほど自民党からもお話がありましたとおり、まとめていく項目をというお話がありましたが、そうだろうとは思います。なので、ある程度項目が分かれている中で、やはり共通の話題、課題というのが見えてきていますので、やはり二、三項目一緒に出ているところをまとめていくというのがよろしいのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"意見","question":"この項目は十七、八項目ある中で、ピックアップしていくというのが本当に大変だと思うのですが、うちとしては、第一希望で避難所における感染症対策、これもコロナ対策になると思うので、これを含めてほかの会派の皆さんもコロナに関することを一緒にうまく取りまとめていただけるとありがたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大体まとめてもらったので、大分ここは今の国と同じようにまとまってくるので、ある程度委員長のほうでまとめてもらってもいいのではないですか。この中でいくともう大体同じ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"一斉登校も再開するとの話もありますけれども、やはり密を避けて授業をするというのであれば、どうしたって学級規模を縮小することが必要だし、子どもの学びにとっても少人数学級は全国で実施されておりますので、ぜひ一致できたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほど自民党の芹澤委員からも説明させていただきました財調の問題、これはぜひ入れておいていただきたいと思いますので、追加でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど鈴木真澄委員からあった財調のことなのですけれども、先ほど国の部分についてはいわゆるコロナウイルス対策というところで１つにまとめていこうということになっていて、先ほどの自民党のご発言というのは、それとはまた別で単独で、今内容を拝見するとやはりコロナウイルス対策として財調はしっかりやってねというところに見受けたのですけれども、その中に入れ込むのではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然コロナ対策もありますけれども、それだけではなくて財調自体のあり方が今までもいろいろな議論をされています。配分の問題とかいろいろなものが絡んできますし、そこで新たな課題も出てきているということで、東京都に対して直接別の立場で要望するということで考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。私どもは、ちょっとずるいやり方ですけれども、コロナウイルスということで財政のこととかいろいろなことを１つの要望の中に幾つかの項目という形で入れたのですけれども、そこの取り扱いは、本当に申しわけないですが、議長、副議長にお任せしたいと思うのです。コロナウイルスということであれば財調も入れてもいいのかと思ったのですが、理解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"今財調のお話がありましたが、そのとおりだと私も思います。財調算定の中にしっかりコロナの対策を入れるべきだと思いますし、児相についてもきちんと今各区で動いている、動き始めている、既に準備をしているわけですから、あわせてそこは東京都の算定項目にしっかり入れるべきだと思いますので、一言述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう意味で、私たち自民党として児相は児相で要望を出していますし、財調の中にも児相という言葉、財政面でのフォローをしてくれということで両方入れている部分があります。ですから、当然コロナも入っているし、財調の中では含めた上での財源、個別事業は個別事業ということで要望しているということの流れでつくっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-018"},{"speaker":"本多委員","kind":"質問・要望","question":"この課題に対しましては、国に対する要望のところでうちは考えておりますので、うちの考えはコロナ対策に対する、あと避難所とか自衛隊中央病院との連携とか、その辺の施策で出していますので、必要ないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望内容は、防災対策の充実としては大事な指摘もあるかと思うのですけれども、全国市議会議長会に宛てるべきなのかというところはよく判断していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"今先にご発言いただいた２人の委員と同じ意見です。問題意識はよくわかります。防災という意味では医療の拡充ということ、災害対策とイコールの部分もあるのですけれども、それをちょっと全国市議会議長会に出すということの、そこまでの特出しをする必要があるのかというところでは慎重な判断が必要かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-021"},{"speaker":"須貝委員","kind":"提案","question":"提出したので、すみません、持論を述べします。今まで国とか都への要望は、そっちはそっちでやはりコロナ対策等しっかりやってほしいと。その中で、自治体でできることは地方で協力してそういう場所を確保する。ですけれども、皆さん方のご意見も今お伺いしましたので、それはそれで議運の場でだめならだめで構いません。ただ、趣旨だけは、そういう趣旨で提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-022"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"本会議場での一般質問ですが、これはマスクをして発言をするわけです。そこで速記をやっている方がいらっしゃるではないですか、今どうなのかわからないですけれども。まさか皆さんの座っている場所までつばが飛ぶとは思えないのですが、飛沫が来るとは思えないのですけれども、何かそういう工夫はできないものなのでしょうかと思いまして。それでちょっと提案させていただきました。","respondent":"渡辺議長、米田区議会事務局長","answer":"今ご提案いただいた議場でのマスクの着用、またはそれに関連する感染予防対策、既に事務局のほうで業者とのやりとりをしたり検討に入っております。ただ、それ以外の席ではマスクをされて発言をされているというのが東京都議会の状況だと見ております。その辺も踏まえまして、今議長の話にありましたようなところでの検討を、物理的な条件等も含めて検討を進めているところです。","voiceIndex":51,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":17627,"voices":55}},{"id":"r02-20200624-10","meetingId":"r02-cm06","date":"2020年6月24日","dateIso":"2020-06-24","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"意見ということで述べさせていただきたいと思います。コロナ禍の下、感染抑止と議会活動をどう両立させるかという点においては、やはり今は第２波への備えが必要なのだと思います。ただ、委員会ごとにばらばらというのはどうかと思いますので、そこは議長のほうで判断を示していただけたらと、これはお願いをさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"私も同意見で、医療関係者いわく、１０月の終わり、１１月から、感染がまた増えてくるのではないか、拡大するのではないかと専門家が言っています。まして区外の視察ならば、さらに遠方に行って、向こうも東京から来られては困るということがあるわけですから、そういうことを考えて、今回は議長・各委員長にはくれぐれもお願いしたいのですが、私は今年度は自重するべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"議長会要望事項調査票ということで資料がありますけれども、この内容については、この間議論した中身が反映されているものだと考えています。これは事後報告という扱いで、議長一任をしている前提の上で述べているわけですけれども、羽田新飛行ルート計画については、国に要望を届けていただきたかった、提案していただきたかったと思いますと、意見だけ述べさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"3)の駐車場内工事ということですけれども、免震ダンパー工事ということでお話あったのですが、偽装等の問題でいろいろ問題になったところだと思うのですけれども、もし分かればでいいのですが、全体の現状といいますか、今回の工事でどの辺まで手がついて、全体としてはどうなっているのか、分かれば教えていただきたいと思います。","respondent":"米田区議会事務局長","answer":"工事の内容ということで、免震ダンパーということで申し上げましたけれども、こちらにつきましては、今定例会中の委員会で所管より報告がされる予定と聞いてありますので、そちらで詳細はお尋ねになっていただければと思います。","voiceIndex":30,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5368#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10398,"voices":33}}]);
